// Proceso de compresión de Imágenes
function f_ComprimirImagenes($imagenBase64)
{
	// Decodificar la imagen base64
	$imagenDecodificada = base64_decode(preg_replace('#^data:image/\w+;base64,#i', '', $imagenBase64));

	// Crear una imagen a partir de los datos decodificados
	$imagenOriginal = imagecreatefromstring($imagenDecodificada);

	if ($imagenOriginal === false) {
		// No se pudo crear la imagen original, manejar el error
		return false;
	}

	// Crear una imagen comprimida
	$imagenComprimida = imagecreatetruecolor(imagesx($imagenOriginal), imagesy($imagenOriginal));

	// Manejar el tipo de imagen
	$imageType = exif_imagetype($imagenBase64);

	switch ($imageType) {
		case IMAGETYPE_JPEG:
			// Si es JPEG, copiar y comprimir
			imagecopyresampled($imagenComprimida, $imagenOriginal, 0, 0, 0, 0, imagesx($imagenOriginal), imagesy($imagenOriginal), imagesx($imagenOriginal), imagesy($imagenOriginal));

			break;

		case IMAGETYPE_PNG:
			// Si es PNG, copiar y comprimir
			imagecopyresampled($imagenComprimida, $imagenOriginal, 0, 0, 0, 0, imagesx($imagenOriginal), imagesy($imagenOriginal), imagesx($imagenOriginal), imagesy($imagenOriginal));

			break;

		// Agrega más casos según sea necesario para otros tipos de imagen (por ejemplo, IMAGETYPE_GIF, IMAGETYPE_BMP, etc.)
		default:
			// Tipo de imagen no compatible, manejar el error
			return false;
	}
	// // ------------
	// // Decodificar la imagen base64
	// $imagenDecodificada = base64_decode(preg_replace('#^data:image/\w+;base64,#i', '', $imagenBase64));

	// // Crear una imagen a partir de los datos decodificados
	// $imagenOriginal = imagecreatefromstring($imagenDecodificada);

	// // Crear una imagen comprimida
	// $imagenComprimida = imagecreatetruecolor(imagesx($imagenOriginal), imagesy($imagenOriginal));

	// // Comprimir la imagen copiándola en la imagen comprimida
	// imagecopyresampled($imagenComprimida, $imagenOriginal, 0, 0, 0, 0, imagesx($imagenOriginal), imagesy($imagenOriginal), imagesx($imagenOriginal), imagesy($imagenOriginal));

	// Guardar la imagen comprimida en un buffer de salida
	ob_start();
	imagejpeg($imagenComprimida, null, 15); // El tercer parámetro representa la calidad de compresión (ajústalo según tus necesidades)
	$imagenComprimidaBase64 = 'data:image/jpeg;base64,' . base64_encode(ob_get_clean());

	return $imagenComprimidaBase64;
}

// Obtener Peso Seco en función a la Humedad
function f_GetPesoSeco($tmh, $h2o)
{
	if (strlen(trim($tmh)) > 0 && strlen(trim($h2o)) > 0) {
		// Obtiene factor de humedad
		$factor = (100 - $h2o) / 100;

		// Obtiene Peso Seco
		$peso_seco = $tmh * $factor;
	} else {
		$peso_seco = '';
	}

	return $peso_seco;
}

// Proceso de eliminación de Lote de Programación - Despachos Segundo tramo
function f_Eliminar_DespachoSegundoTramo_ProgramacionLote($enlace, $id_programacionlote, $fechahora_registro, $usuario_registro)
{
	$estado = 0;

	// Obteniendo datos del Lote
	$id = '';
	$id_programacion = '';
	$cod_lote = '';
	$id_planta = '';
	$id_modalidadenvio = '';
	$codigo_despacho = '';
	$codigo_comercializacion = '';
	$codigo_planta = '';
	$tmh = '';
	$fechahora_registro_x = '';
	$usuario_registro_x = '';
	$is_loteaum = 0;

	$q_datos = "SELECT PD.Id,
														 PD.id_programacion,
														 PD.cod_lote,
														 PD.id_planta,
														 IFNULL(PD.id_modalidadenvio, 0) AS id_modalidadenvio,
														 PD.codigo_despacho,
														 PD.codigo_despacho_comercializacion,
														 PD.codigo_planta,
														 PD.TMH,
														 PD.fechahora_registro,
														 PD.usuario_registro,
														 L.is_loteaum
												 FROM despachos_segundotramo_programacion_detalle PD
														 INNER JOIN catalogolotes L ON PD.cod_lote = L.ccod_Lote
											WHERE PD.Id = " . $id_programacionlote;

	if ($res_datos = mysqli_query($enlace, $q_datos)) {
		if (mysqli_num_rows($res_datos) > 0) {
			while ($row_datos = mysqli_fetch_array($res_datos)) {
				$id = $row_datos["Id"];
				$id_programacion = $row_datos["id_programacion"];
				$cod_lote = $row_datos["cod_lote"];
				$id_planta = $row_datos["id_planta"];
				$id_modalidadenvio = intval($row_datos["id_modalidadenvio"]);
				$codigo_despacho = trim($row_datos["codigo_despacho"]);
				$codigo_comercializacion = trim($row_datos["codigo_despacho_comercializacion"]);
				$codigo_planta = $row_datos["codigo_planta"];
				$tmh = $row_datos["TMH"];
				$fechahora_registro_x = $row_datos["fechahora_registro"];
				$usuario_registro_x = $row_datos["usuario_registro"];
				$is_loteaum = $row_datos["is_loteaum"];
			}
		}
	}

	// Guardando Log
	$q_log = "INSERT INTO despachos_segundotramo_programacion_detalle_log (Id, id_programacion, cod_lote, id_planta, id_modalidadenvio, codigo_despacho, codigo_despacho_comercializacion, codigo_planta, TMH, fechahora_registro, usuario_registro, fechahora_log, usuario_log) VALUES (";
	$q_log .= "			 " . $id . ", ";
	$q_log .= "			 " . $id_programacion . ", ";
	$q_log .= "			'" . $cod_lote . "', ";
	$q_log .= "			 " . ((strlen($id_planta) == 0) ? 'NULL' : $id_planta) . ", ";
	$q_log .= "			 " . (($id_modalidadenvio == 0) ? 'NULL' : $id_modalidadenvio) . ", ";
	$q_log .= "			'" . $codigo_despacho . "', ";
	$q_log .= "			 " . ((strlen($codigo_comercializacion) == 0) ? 'NULL' : "'" . $codigo_comercializacion . "'") . ", ";
	$q_log .= "			'" . $codigo_planta . "', ";
	$q_log .= "			 " . ((strlen($tmh) == 0) ? 'NULL' : $tmh) . ", ";
	$q_log .= "			'" . $fechahora_registro_x . "', ";
	$q_log .= "			'" . $usuario_registro_x . "', ";
	$q_log .= "			'" . $fechahora_registro . "', ";
	$q_log .= "			'" . $usuario_registro . "')";

	if ($res_save = mysqli_query($enlace, $q_log)) {
	} else {
		return $estado;
	}

	// Elimina el correlativo de detalle asociado (solo si la modalidad genera codigo
	// y ningun otro lote del mismo despacho lo sigue referenciando, ya que el codigo
	// de detalle es COMPARTIDO por todos los lotes de la misma empresa dentro del despacho).
	if ($id_modalidadenvio == 5 || $id_modalidadenvio == 6) {
		$q_count_ref = "SELECT COUNT(Id) AS _COUNT
										FROM despachos_segundotramo_programacion_detalle
									 WHERE id_programacion = " . $id_programacion . "
										 AND id_planta = " . $id_planta . "
										 AND codigo_despacho_comercializacion = '" . mysqli_real_escape_string($enlace, $codigo_comercializacion) . "'";
		$count_ref = 0;

		if ($res_count_ref = mysqli_query($enlace, $q_count_ref)) {
			if ($row_count_ref = mysqli_fetch_array($res_count_ref)) {
				$count_ref = intval($row_count_ref["_COUNT"]);
			}
		}

		// Solo eliminar el correlativo si no quedan mas lotes usandolo
		if ($count_ref == 0) {
			$q_del_det = "DELETE FROM correlativo_despacho_detalle
										 WHERE id_programacion = " . $id_programacion . "
											 AND id_planta = " . $id_planta . "
											 AND id_modalidadenvio = " . $id_modalidadenvio . "
											 AND codigo = '" . mysqli_real_escape_string($enlace, $codigo_comercializacion) . "'";
			mysqli_query($enlace, $q_del_det);
		}
	}

	// Eliminar Lote programado
		$q_delete = "DELETE FROM despachos_segundotramo_programacion_detalle";
		$q_delete .= " WHERE Id = " . $id_programacionlote;

		if ($res_delete = mysqli_query($enlace, $q_delete)) {
			$estado = 1;
		} else {
			$estado = 2;
		}

	// Si no quedan más lotes en la programación, elimina también la cabecera y el correlativo de cabecera
	$q_count = "SELECT COUNT(Id) AS TOTAL
							 FROM despachos_segundotramo_programacion_detalle
							WHERE id_programacion = " . $id_programacion;

	$total_detalle = 0;
	if ($res_count = mysqli_query($enlace, $q_count)) {
		if (mysqli_num_rows($res_count) > 0) {
			while ($row_count = mysqli_fetch_array($res_count)) {
				$total_detalle = intval($row_count["TOTAL"]);
			}
		}
	}

	if ($total_detalle == 0 && $estado == 1) {
		// Eliminar TODOS los correlativos de cabecera de esta programacion (uno por modalidad)
		$q_del_cabs = "DELETE FROM correlativo_despacho
								 WHERE id_programacion = " . $id_programacion . "
									 AND id_planta = " . $id_planta;
		mysqli_query($enlace, $q_del_cabs);

		// Eliminar TODOS los correlativos de detalle de esta programacion
		$q_del_dets = "DELETE FROM correlativo_despacho_detalle
								 WHERE id_programacion = " . $id_programacion . "
									 AND id_planta = " . $id_planta;
		mysqli_query($enlace, $q_del_dets);

		// Eliminar cabecera de programacion
		$q_del_cab2 = "DELETE FROM despachos_segundotramo_programacion
									WHERE Id = " . $id_programacion;
		mysqli_query($enlace, $q_del_cab2);
	}

	// Vrificando si es Lote AUM y lo elimina de la tabla de Lotes y Validación de datos del Primer Tramo
	if ($estado == 1 && $is_loteaum == 1) {
		// Obtiene el Id del registro de la tabla de Catálogo de Lotes
		$id_registro = 0;
		$id_controlingreso = 0;

		$q_idregistro = "SELECT id_CatalogoLotes,
																		id_controlIngresoVehiculo
															 FROM catalogolotes
															WHERE ccod_Lote = '" . $cod_lote . "'";

		if ($res_idregistro = mysqli_query($enlace, $q_idregistro)) {
			if (mysqli_num_rows($res_idregistro) > 0) {
				while ($row_idregistro = mysqli_fetch_array($res_idregistro)) {
					$id_registro = $row_idregistro["id_CatalogoLotes"];
					$id_controlingreso = $row_idregistro["id_controlIngresoVehiculo"];
				}
			}
		}

		// Elimina el registro del maestro de Lotes
		$q_delete1 = "DELETE FROM catalogolotes
													 WHERE ccod_Lote = '" . $cod_lote . "'";

		if ($res_delete1 = mysqli_query($enlace, $q_delete1)) {
			// Elimina el registro de la tabla de Validación de Datos
			$q_delete2 = "DELETE FROM despachos_primertramo_validaciondatos
															 WHERE lote_cod_lote = '" . $cod_lote . "'";

			if ($res_delete2 = mysqli_query($enlace, $q_delete2)) {
				// Elimina el registro de la tabla de Correlativos de Lote
				$q_delete = "DELETE FROM correlativo_lotes";
				$q_delete .= " WHERE id_lote = " . $id_registro;

				if ($res_delete = mysqli_query($enlace, $q_delete)) {
				}

				// Elimina el registro de la tabla de la tabla de Ingresos
				$q_delete = "DELETE FROM controlingresovehiculo";
				$q_delete .= " WHERE id_controlIngresoVehiculo = " . $id_controlingreso;

				if ($res_delete = mysqli_query($enlace, $q_delete)) {
				}
			} else {
				$estado = 6;
			}
		} else {
			$estado = 5;
		}
	}

	// Eliminando la Distribución del Lote seleccionado
	$q_delete3 = "DELETE FROM despachos_segundotramo_distribucion_lotes
											WHERE cod_lote = '" . $cod_lote . "'";

	if ($res_delete3 = mysqli_query($enlace, $q_delete3)) {
	} else {
		$estado = 7;
	}

	return $estado;
}
