						// Inserta el correlativo en la tabla de correlativos de Comercialización
						if ($is_newcodigo == 1) {
							// Elimina los Correlativos que puedan existir en la tabla, menos los creados en balanza
							$q_delete = "DELETE FROM correlativo_despacho_comercializacion
																			WHERE id_programacion = " . $id_programacion . "
																				AND id_modalidadenvio = " . $row_detalle["ID_MODALIDADENVIO"];

							if ($res_delete = mysqli_query($enlace, $q_delete)) {
							}

							// Inserta el Nuevo Código
							$q_insert = "INSERT INTO correlativo_despacho_comercializacion (id_programacion, id_planta, id_modalidadenvio, correlativo, codigo, fechahora_registro, usuario_registro) VALUES (";
							$q_insert .= $id_programacion . ", ";
							$q_insert .= $id_planta . ", ";
							$q_insert .= $row_detalle["ID_MODALIDADENVIO"] . ", ";
							$q_insert .= $new_codigo . ", ";
							$q_insert .= "'" . $correlativo_comercializacion . "', ";
							$q_insert .= "'" . $fecha_registro . "', ";
							$q_insert .= "'" . $usuario_registro . "')";

							if ($res_insert = mysqli_query($enlace, $q_insert)) {
							}
						}
					}
				}
			}
		}
	}
}

// =============================================================================
// NUEVAS FUNCIONES PARA GENERACIÓN DE CÓDIGOS DE DESPACHO - 2DO TRAMO
// Colibri (id_planta=3) y Solandra (id_planta=5) - Modalidades 5 (VIII) y 6 (48 SAC)
// =============================================================================

// Obtiene la campaña activa de una planta.  Devuelve null si no existe.
function f_GetCampanaActiva($enlace, $id_planta)
{
	$id_campana = null;
	$codigo_campana = '';
	$fecha_inicio = '';

	$q = "SELECT Id, codigo_campana, fecha_inicio
					FROM tbconfig_plantas_campanas
				 WHERE id_planta = " . intval($id_planta) . "
					 AND estado = 'A'
					 AND fecha_fin IS NULL
				 ORDER BY Id DESC
				 LIMIT 1";

	if ($res = mysqli_query($enlace, $q)) {
		if (mysqli_num_rows($res) > 0) {
			while ($row = mysqli_fetch_array($res)) {
				$id_campana = $row["Id"];
				$codigo_campana = $row["codigo_campana"];
				$fecha_inicio = $row["fecha_inicio"];
			}
		}
	}

	return array(
		'id_campana' => $id_campana,
		'codigo_campana' => $codigo_campana,
		'fecha_inicio' => $fecha_inicio
	);
}

// Devuelve el prefijo del detalle según la modalidad (5=VIII, 6=48 SAC)
function f_GetPrefijoEmpresaDespacho($id_modalidadenvio)
{
	if ($id_modalidadenvio == 5) {
		return 'VIII';
	} elseif ($id_modalidadenvio == 6) {
		return 'CO';
	}
	return '';
}

// Calcula el siguiente correlativo (cabecera o detalle) según:
//   - planta (3=Colibri, 5=Solandra)
//   - modalidad (5=VIII, 6=48 SAC) - SOLO para DET (el detalle es por empresa)
//   - tipo: CAB = cabecera GLOBAL por planta (no se reinicia por empresa)
//           DET = detalle por planta+modalidad
//   - id_campana (solo para Solandra, NULL para Colibri y Solandra sin campana)
//   - is_campana_requerida (true por defecto; false permite Solandra sin campana)
// El punto de partida se toma de las variables globales.
// SIEMPRE compara contra el MAX existente en BD y toma el mayor.
function f_CalcularSiguienteCorrelativoDespacho($enlace, $id_planta, $id_modalidadenvio, $tipo, $id_campana = null, $is_campana_requerida = true)
{
	$resultado = array(
		'prefijo_cab' => '',
		'prefijo_det' => '',
		'correlativo' => 0,
		'codigo' => '',
		'id_campana' => null,
		'codigo_campana' => null,
		'error' => null
	);

	if ($id_planta != 3 && $id_planta != 5) {
		$resultado['error'] = 'La planta seleccionada no aplica para esta logica.';
		return $resultado;
	}

	// Para DET se exige modalidad explicita (5 o 6).
	// Para CAB la modalidad NO se usa (la cabecera es global por planta),
	// pero se acepta el parametro para mantener compatibilidad de la firma.
	if ($tipo == 'DET' && $id_modalidadenvio != 5 && $id_modalidadenvio != 6) {
		$resultado['error'] = 'Solo las modalidades 5 (VIII) y 6 (48 SAC) generan codigo de detalle.';
		return $resultado;
	}

	// 1. Determinar prefijo de cabecera según planta
	if ($id_planta == 3) {
		$resultado['prefijo_cab'] = 'C';
	} elseif ($id_planta == 5) {
		// Si se recibio un id_campana explicito (no null y no vacio), usarlo directamente.
		if (!is_null($id_campana) && $id_campana !== '' && intval($id_campana) > 0) {
			$campana = null;
			$q_camp = "SELECT Id, codigo_campana, fecha_inicio
									FROM tbconfig_plantas_campanas
								 WHERE Id = " . intval($id_campana) . "
								 LIMIT 1";
			if ($res_camp = mysqli_query($enlace, $q_camp)) {
				if ($row_camp = mysqli_fetch_assoc($res_camp)) {
					$campana = array(
						'id_campana' => intval($row_camp["Id"]),
						'codigo_campana' => $row_camp["codigo_campana"],
						'fecha_inicio' => $row_camp["fecha_inicio"]
					);
				}
			}

			if (is_null($campana)) {
				$resultado['error'] = 'La campana seleccionada no existe.';
				return $resultado;
			}

			$resultado['id_campana'] = $campana['id_campana'];
			$resultado['codigo_campana'] = $campana['codigo_campana'];
			// El usuario digita el codigo COMPLETO de la campana (ej. "CP31", "CPM33")
			$resultado['prefijo_cab'] = $campana['codigo_campana'] . '-S';
		} else {
			// No se paso campana explicita: intentar obtener la activa solo si se requiere.
			if ($is_campana_requerida) {
				$campana = f_GetCampanaActiva($enlace, $id_planta);

				if (is_null($campana['id_campana'])) {
					$resultado['error'] = 'No existe una campana activa para Solandra. Cree una desde Administracion de Plantas.';
					return $resultado;
				}

				$resultado['id_campana'] = $campana['id_campana'];
				$resultado['codigo_campana'] = $campana['codigo_campana'];
				$resultado['prefijo_cab'] = $campana['codigo_campana'] . '-S';
			} else {
				// Solandra sin campana: solo "S<nro>" (prefijo_cab queda vacio)
				$resultado['id_campana'] = null;
				$resultado['codigo_campana'] = null;
				$resultado['prefijo_cab'] = '';
			}
		}
	}

	if ($tipo == 'DET') {
		$resultado['prefijo_det'] = f_GetPrefijoEmpresaDespacho($id_modalidadenvio);
	}

	// 2. Obtener el correlativo inicial desde las variables globales
	$correlativo_inicial = 0;
	$var_global = null;

	if ($tipo == 'CAB') {
		// Cabecera GLOBAL por planta (NO se desglosa por empresa/modalidad).
		if ($id_planta == 3) {
			$var_global = 'CORR_COLIBRI_CAB_INICIO';
		} elseif ($id_planta == 5) {
			$var_global = 'CORR_SOLANDRA_CAB_INICIO';
		}
	} else {
		// Detalle por planta+modalidad
		if ($id_planta == 3 && $id_modalidadenvio == 5) {
			$var_global = 'CORR_COLIBRI_VIII_DET_INICIO';
		} elseif ($id_planta == 3 && $id_modalidadenvio == 6) {
			$var_global = 'CORR_COLIBRI_48SAC_DET_INICIO';
		} elseif ($id_planta == 5 && $id_modalidadenvio == 5) {
			$var_global = 'CORR_SOLANDRA_VIII_DET_INICIO';
		} elseif ($id_planta == 5 && $id_modalidadenvio == 6) {
			$var_global = 'CORR_SOLANDRA_48SAC_DET_INICIO';
		}
	}

	if (!is_null($var_global) && isset($GLOBALS[$var_global]) && intval($GLOBALS[$var_global]) > 0) {
		$correlativo_inicial = intval($GLOBALS[$var_global]);
	}

	// 2b. Verificar fecha global de vigencia del reset (evita retroactividad)
	//     Si la fecha actual >= CORR_DESDE, las variables _INICIO sobrescriben el historico.
	$aplica_reset = false;

	if (!is_null($var_global) && $correlativo_inicial > 0 && isset($GLOBALS['CORR_DESDE']) && !empty($GLOBALS['CORR_DESDE'])) {
		$fecha_desde = $GLOBALS['CORR_DESDE'];
		$fecha_actual = isset($g_date) ? $g_date : date('Y-m-d');

		if (strtotime($fecha_actual) >= strtotime($fecha_desde)) {
			$aplica_reset = true;
		}
	}

	// 3. Obtener el maximo correlativo actual
	$tabla = ($tipo == 'CAB') ? 'correlativo_despacho' : 'correlativo_despacho_detalle';

	$q_max = "SELECT MAX(correlativo) AS MAX_CORRELATIVO
							FROM " . $tabla . "
						 WHERE id_planta = " . intval($id_planta);

	// Para CAB la cabecera es GLOBAL: NO se filtra por id_modalidadenvio.
	// Para DET si se filtra por id_modalidadenvio (el detalle es por empresa).
	if ($tipo == 'DET') {
		$q_max .= "   AND id_modalidadenvio = " . intval($id_modalidadenvio);
	} else {
		// Cabecera: NO se filtra por campana. La numeracion es CONTINUA entre
		// campanas de Solandra (CP32-S220 -> CP33-S221). Si la nueva campana
		// no tiene registros, se usa el MAX real de cualquier campana previa
		// (filtrada por CORR_DESDE) o, en su defecto, la variable _INICIO.
	}

	// Filtrar por fecha CORR_DESDE para ignorar el historico antiguo
	if (isset($GLOBALS['CORR_DESDE']) && !empty($GLOBALS['CORR_DESDE'])) {
		$q_max .= " AND fechahora_registro >= '" . $GLOBALS['CORR_DESDE'] . " 00:00:00'";
	}

	$max_actual = 0;

	if ($res_max = mysqli_query($enlace, $q_max)) {
		if (mysqli_num_rows($res_max) > 0) {
			while ($row_max = mysqli_fetch_array($res_max)) {
				$max_actual = intval($row_max["MAX_CORRELATIVO"]);
			}
		}
	}

	// 4. Determinar el correlativo final
	//    - Si max_actual = 0 (tabla vacia): usar la variable como punto de partida
	//    - Si max_actual > 0 (hay datos):
	//         * Si hoy >= CORR_DESDE (aplica_reset): usar MAX(variable, max+1)
	//           para que la variable _INICIO actue como piso y respete los
	//           correlativos que la empresa ya maneja.
	//         * Si no: incrementar normalmente con max + 1.
	if ($max_actual == 0) {
		$resultado['correlativo'] = max(1, $correlativo_inicial);
	} else {
		if ($aplica_reset && $correlativo_inicial > 0) {
			$resultado['correlativo'] = max($correlativo_inicial, $max_actual + 1);
		} else {
			$resultado['correlativo'] = $max_actual + 1;
		}
	}

	// 5. Construir el codigo
	if ($tipo == 'CAB') {
		$resultado['codigo'] = $resultado['prefijo_cab'] . $resultado['correlativo'];
	} else {
		$resultado['codigo'] = $resultado['prefijo_det'] . $resultado['correlativo'];
	}

	return $resultado;
}

// Construye el código de cabecera final: ej. "C556", "CP31-S216" o "S216" (Solandra sin campaña)
// El codigo_campana ya viene COMPLETO del usuario (ej. "CP31" o "CPM33")
// Si id_planta = 5 (Solandra) y codigo_campana es vacio/null, devuelve solo "S<nro>"
function f_ConstruirCodigoCabecera($id_planta, $codigo_campana, $numero)
{
	if ($id_planta == 3) {
		return 'C' . $numero;
	} elseif ($id_planta == 5) {
		if (!is_null($codigo_campana) && $codigo_campana !== '') {
			return $codigo_campana . '-S' . $numero;
		}
		// Solandra sin campana: solo "S<nro>"
		return 'S' . $numero;
	}
	return '';
}

// Construye el código de detalle final: ej. "C1-VIII1" o "CP31-S1-VIII1"
function f_ConstruirCodigoDetalle($codigo_cabecera, $prefijo_empresa, $numero)
{
	return $codigo_cabecera . '-' . $prefijo_empresa . $numero;
}

