// Función para Obtener la diferencia de horas
function f_GetDiferenciaHoras($fecha_inicio, $fecha_fin)
{
	// Crear objetos DateTime para las fechas de inicio y fin
	$inicio = new DateTime($fecha_inicio);
	$fin = new DateTime($fecha_fin);

	// Calcular la diferencia entre las fechas
	$diferencia = $inicio->diff($fin);

	// Obtener la diferencia en horas
	$horas = $diferencia->h;
	$horas += $diferencia->days * 24;

	// Si la diferencia también incluye minutos, sumar fracción de hora
	if ($diferencia->i > 0) {
		$horas += $diferencia->i / 60;
	}

	return number_format($horas, 2, '.', '');
}

// Permite obtener el total de toneladas distribuídas como complemento de la Programación del Segundo Tramo
function f_GetTonelajeDistribuidoComplementos($enlace, $id_distribucionlote_padre)
{
	$total_tonelaje = 0;

	$q_tonelaje = "SELECT SUM(peso_distribuido) AS TONELADAS
											 FROM despachos_segundotramo_distribucion_lotes
											WHERE is_complemento_de = " . $id_distribucionlote_padre;

	if ($res_tonelaje = mysqli_query($enlace, $q_tonelaje)) {
		if (mysqli_num_rows($res_tonelaje) > 0) {
			while ($row_tonelaje = mysqli_fetch_array($res_tonelaje)) {
				$total_tonelaje += $row_tonelaje["TONELADAS"];
			}
		}
	}

	return $total_tonelaje;
}

// Permite Verificar y Actualizar el estado de lotes a "Despachado"
function f_UpdateEstadoDespachado($enlace, $id_controlIngresoVehiculo)
{
	// 1. Obtiene Id de Unidad y fecha de ingreso a planta del Ingreso de Vigilancia
	$id_unidadtransporte = 0;
	$fecha_ingresoplanta = '';

	$q_datos = "SELECT U.id_transporte,
													 CI.dFechaIngreso
											FROM controlingresovehiculo CI
													 INNER JOIN transporte U ON CI.placa = U.cplaca
										 WHERE CI.id_controlIngresoVehiculo = " . $id_controlIngresoVehiculo;

	if ($res_datos = mysqli_query($enlace, $q_datos)) {
		if (mysqli_num_rows($res_datos) > 0) {
			while ($row_datos = mysqli_fetch_array($res_datos)) {
				$id_unidadtransporte = $row_datos["id_transporte"];
				$fecha_ingresoplanta = $row_datos["dFechaIngreso"];
			}
		}
	}

	// 2. Identifica los lotes de esa Unidad en la Programación de Despachos
	$programacion_codlote = '';

	$q_datos2 = "SELECT DISTINCT
														DL.cod_lote
											 FROM despachos_segundotramo_distribucion_unidades U
														INNER JOIN despachos_segundotramo_programacion P ON U.id_programacion = P.Id
														INNER JOIN despachos_segundotramo_distribucion_lotes DL ON U.Id = DL.id_distribucionunidad
											WHERE U.id_unidad = " . $id_unidadtransporte . "
												AND '" . $fecha_ingresoplanta . "' BETWEEN U.fecha_ingresoplanta AND P.fechaestimada_despacho";

	if ($res_datos2 = mysqli_query($enlace, $q_datos2)) {
		if (mysqli_num_rows($res_datos2) > 0) {
			while ($row_datos2 = mysqli_fetch_array($res_datos2)) {
				$programacion_codlote = $row_datos2["cod_lote"];

				// 3. Obtiene la Unidad asignada de cada Lote de la Unidad Principal.
				//		Si no tuviera partes adicionales, se debe actualizar el registro a "Despachado".
				$is_despachado = 1;

				$q_datos3 = "SELECT id_distribucionunidad
															FROM despachos_segundotramo_distribucion_lotes
														 WHERE cod_lote = '" . $programacion_codlote . "'";

				if ($res_datos3 = mysqli_query($enlace, $q_datos3)) {
					if (mysqli_num_rows($res_datos3) > 0) {
						while ($row_datos3 = mysqli_fetch_array($res_datos3)) {
							$id_distribucionunidad = $row_datos3["id_distribucionunidad"];

							// 4. Obtiene los datos de la unidad asociada a la parte del Lote a inspeccionar
							$q_datos4 = "SELECT T.cplaca,
																					 U.fecha_ingresoplanta,
																					 P.fechaestimada_despacho
																			FROM despachos_segundotramo_distribucion_unidades U
																					 INNER JOIN transporte T ON U.id_unidad = T.id_transporte
																					 INNER JOIN despachos_segundotramo_programacion P ON U.id_programacion = P.Id
																		 WHERE U.Id = " . $id_distribucionunidad;

							if ($res_datos4 = mysqli_query($enlace, $q_datos4)) {
								if (mysqli_num_rows($res_datos4) > 0) {
									while ($row_datos4 = mysqli_fetch_array($res_datos4)) {
										$placa = $row_datos4["cplaca"];
										$fecha_ingresoplanta = $row_datos4["fecha_ingresoplanta"];
										$fecha_estimadadespacho = $row_datos4["fechaestimada_despacho"];

										// 5. Finalmente, inspecciona si la unidad de la parte del lote también tiene salida
										$q_datos5 = "SELECT fechahora_salida
																							 FROM controlingresovehiculo
																							WHERE placa = '" . $placa . "'
																								AND dFechaIngreso BETWEEN '" . $fecha_ingresoplanta . "' AND '" . $fecha_estimadadespacho . "'";

										if ($res_datos5 = mysqli_query($enlace, $q_datos5)) {
											if (mysqli_num_rows($res_datos5) > 0) {
												while ($row_datos5 = mysqli_fetch_array($res_datos5)) {
													if (strlen($row_datos5["fechahora_salida"]) == 0) {
														$is_despachado = 0;
													}
												}
											}
										}
									}
								}
							}
						}
					}
				}

				// 6. Actualiza el Estado de cada lote
				if ($is_despachado == 1) {
					$q_update = "UPDATE despachos_primertramo_validaciondatos SET";
					$q_update .= "  despacho_id_estadolote = 8";
					$q_update .= " WHERE lote_cod_lote = '" . $programacion_codlote . "'";

					if ($res_datos = mysqli_query($enlace, $q_update)) {
					}
				}
			}
		}
	}
}

// Genera el html de Muestreos de Operaciones por Planta y Lote
function g_GetOperacionesMuestreosxLote($enlace, $item_planta, $pos_row, $cod_lote, $is_gestioncomercial)
{
	$html = '';
	$d = 1;

	$q_datos = "SELECT Id,
												 fecha_muestreo,
												 numero_muestreo,
												 observacion
										FROM operaciones_gestionmuestreo
									 WHERE item_planta = " . $item_planta . "
										 AND cod_lote = '" . $cod_lote . "'
									ORDER BY fecha_muestreo";

	if ($res_datos = mysqli_query($enlace, $q_datos)) {
		if (mysqli_num_rows($res_datos) > 0) {
			while ($row_datos = mysqli_fetch_array($res_datos)) {
				$html .= '<div class="d-flex" style="padding: 5px; border: solid; border-width: 1px; border-color: #E6E9ED; border-radius: 7px; margin-bottom: 3px; background-color: #C7FFED;">';
				$html .= '	<div class="d-flex">';
				$html .= '		<table style="width: 100%">';
				$html .= '			<tr style="font-size: 12px;">';
				$html .= '				<td rowspan="2" style="border-right: solid; border-right-width: 1px; border-right-color: #D9D9D9; padding-right: 5px; border-top-left-radius: 5px; border-bottom-left-radius: 5px; width: 15px; background-color: #FFF587;">';
				$html .= '					' . $d . '. ';
				$html .= '				</td>';

				if ($is_gestioncomercial != 1) {
					$html .= '				<td rowspan="2" style="padding-right: 5px; border-top-right-radius: 5px; border-bottom-right-radius: 5px; width: 15px; background-color: #FFF587;">';
					$html .= '					<label style="border: solid; border-width: 1px; border-color: #D9D9D9; border-radius: 7px; padding-top: 3px; padding-bottom: 3px; padding-left: 4px; padding-right: 4px; background-color: #F29F05; color: #ffffff; cursor: pointer;" onclick="f_AddMuestreo(' . $item_planta . ', ' . $pos_row . ", 1, " . $row_datos["Id"] . ", '" . $row_datos["fecha_muestreo"] . "', " . $row_datos["numero_muestreo"] . ", '" . $row_datos["observacion"] . "'" . ');">';
					$html .= '      			<i class="bi bi-pencil-square"></i>';
					$html .= '      		</label><br>';
					$html .= '					<label style="border: solid; border-width: 1px; border-color: #D9D9D9; border-radius: 7px; padding-left: 6px; padding-right: 6px; padding-bottom: 1px; background-color: #FF5F5D; color: #ffffff; font-weight: bold; cursor: pointer; text-align: center; height: 20px;" onclick="f_EliminarMuestreo(' . $row_datos["Id"] . ', ' . $item_planta . ', ' . $pos_row . ');">X</label>';
					$html .= '				</td>';
				}

				$html .= '				<td style="border-right: solid; border-right-width: 1px; border-right-color: #D9D9D9; padding-right: 5px;">';
				$html .= '					Fecha: <label style="font-weight: bold;">' . $row_datos["fecha_muestreo"] . '</label>';
				$html .= '				</td>';

				$html .= '				<td style="padding-left: 5px;">';
				$html .= '					N°: <label style="font-weight: bold;">' . $row_datos["numero_muestreo"] . '</label>';
				$html .= '				</td>';
				$html .= '			</tr>';

				$html .= '			<tr style="font-size: 12px;">';
				$html .= '				<td colspan="2">';

				if (strlen($row_datos["observacion"]) > 0) {
					$html .= '					Obs: <label style="font-weight: bold;">' . $row_datos["observacion"] . '</label>';
				}

				$html .= '				</td>';
				$html .= '			</tr>';
				$html .= '		</table>';
				$html .= '	</div>';
				$html .= '</div>';

				$d++;
			}
		}
	}

	return $html;
}

// Obtiene la Fecha y Hora de Despacho Real
function f_GetFechaHoraDespachoReal($enlace, $lote)
{
	$fecha_despacho = '';

	$q_datos = "SELECT CI.fechahora_salida
										FROM despachos_segundotramo_programacion_detalle PD
												 INNER JOIN despachos_segundotramo_programacion P ON PD.id_programacion = P.Id
												 INNER JOIN despachos_segundotramo_distribucion_unidades U ON P.Id = U.id_programacion
												 INNER JOIN despachos_segundotramo_distribucion_lotes DL ON U.Id = DL.id_distribucionunidad
													 AND PD.cod_lote = DL.cod_lote
												 INNER JOIN transporte UN ON U.id_unidad = UN.id_transporte
												 INNER JOIN controlingresovehiculo CI ON CI.placa = UN.cplaca
													 AND CI.dFechaIngreso BETWEEN U.fecha_ingresoplanta AND P.fechaestimada_despacho
									 WHERE PD.cod_lote = '" . $lote . "'";

	if ($res_datos = mysqli_query($enlace, $q_datos)) {
		if (mysqli_num_rows($res_datos) > 0) {
			while ($row_datos = mysqli_fetch_array($res_datos)) {
				$fecha_despacho = $row_datos["fechahora_salida"];
			}
		}
	}

	return $fecha_despacho;
}

// Migra Lotes al Consolidado de Cierre Contable
function f_MigrarLotes_CierreContable($enlace, $id_tipoingreso, $arr_idregistros, $g_fecha, $usuario_registro)
{
	$l = 0;
	$arr_idregistros = explode(', ', $arr_idregistros);
	$idregistro_new = 0;

	while ($l < count($arr_idregistros)) {
		$skip_insert = false;
		$id_existente = 0;

		// 1. Verificar si ya existe el registro en consolidado_lotes_cierrecontable
		//    Esto aplica para AMBOS tramos (id_tipoingreso = 1 y 2) y evita duplicados al re-ejecutarse.
		$q_exists = "SELECT Id
								 FROM consolidado_lotes_cierrecontable
								WHERE id_tipoingreso = " . $id_tipoingreso . "
									AND id_registro = " . $arr_idregistros[$l];

		if ($res_exists = mysqli_query($enlace, $q_exists)) {
			if (mysqli_num_rows($res_exists) > 0) {
				$row_exists = mysqli_fetch_array($res_exists);
				$id_existente = $row_exists["Id"];
			}
		}

		// 2. Construir el SELECT de los datos del lote según el tramo
		//    Se reutiliza tanto para INSERT (cuando no existe) como para UPDATE (cuando ya existe).
		$q_select_datos = "";

		if ($id_tipoingreso == 1) {
			$q_select_datos = "
			SELECT V.Id,
							V.lote_cod_lote,
							V.lote_ticket_orden,
							" . $id_tipoingreso . ",
							DATE(V.lote_pesoinicial_fechahoraregistro) AS FECHA_INGRESOBALANZA,
							V.balanza_placa,
							V.balanza_placa2,
							CONCAT(V.guiaremitente_serie, '-', V.guiaremitente_numero) AS GUIA_REMITENTE,
							CONCAT(V.guiatransportista_serie, '-', V.guiatransportista_numero) AS GUIA_TRANSPORTISTA,
							CL_T.documento AS TRANSPORTISTA_RUC,
							UPPER(CL_T.razon_social) AS TRANSPORTISTA_RAZONSOCIAL,
							T.id_tipovehiculo,
							CD.licencia_conducir AS CONDUCTOR_LICENCIA,
							CD.nombres AS CONDUCTOR_NOMBRES,
							V.lote_id_tipocarga,
							NULL,
							V.lote_id_zonaorigen,
							CL.documento AS PROVEEDORMINERO_RUC,
							UPPER(CL.razon_social) AS PROVEEDORMINERO_RAZONSOCIAL,
							UPPER(EM.nombres) AS ENCARGADO_MUESTRA,
							NULL,
							NULL,
							V.lote_id_producto,
							V.lote_id_tipomineral,
							V.despacho_observacion,
							V.lote_pesoinicial_fechahoraregistro,
							V.lote_pesofinal_fechahoraregistro,
							V.lote_peso_inicial AS lote_peso_bruto,
							V.lote_peso_final AS lote_peso_tara,
							V.lote_peso_neto,
							'" . $g_fecha . "',
							'" . $usuario_registro . "'
				 FROM despachos_primertramo_validaciondatos V
							LEFT JOIN transporte T ON V.balanza_placa = T.cplaca
							LEFT JOIN tb_clientes CL_T ON T.id_Transportista = CL_T.Id
							LEFT JOIN tbconfig_conductores CD ON V.guias_idchofer = CD.Id
							LEFT JOIN tb_clientes CL ON V.lote_id_proveedorminero = CL.Id
							LEFT JOIN tbconfig_encargadosmuestra EM ON V.lote_id_encargadomuestra = EM.Id
				WHERE V.Id = " . $arr_idregistros[$l];
		} else {
			$q_select_datos = "SELECT DISTINCT
															DL.Id,
															PD.cod_lote,
															/*DL.num_parte,*/

															(CASE WHEN (SELECT COUNT(DL_x.Id)
																						FROM despachos_segundotramo_distribucion_lotes DL_x
																					 WHERE DL_x.is_complemento_de = DL.Id) > 0
																 THEN 1
															 ELSE CASE WHEN DL.is_complemento = 1
																			THEN (SELECT 1 + (COUNT(CC_x.Id) + 1)
																							FROM consolidado_lotes_cierrecontable CC_x
																						 WHERE CC_x.cod_lote = PD.cod_lote
																							 AND CC_x.id_tipoingreso = 2
																							 AND lote_item <> 1)
																		ELSE DL.num_parte END END) AS lote_item,

															" . $id_tipoingreso . " AS id_tipoingreso,
															/*DATE(DL.peso_bruto_fechahoraregistro) AS FECHA_INGRESOBALANZA,*/
															DATE(DL.peso_tara_fechahoraregistro) AS fecha_ingresobalanza, -- ahora los codigos de los tickets se basaran en la fecha de peso inicial
															DL.guias_placa1 AS PLACA1,
															DL.guias_placa2 AS PLACA2,
															CONCAT(DL.guiaremitente_serie, '-', DL.guiaremitente_numero) AS GUIA_REMITENTE,
															CONCAT(DL.guiatransportista_serie, '-', DL.guiatransportista_numero) AS GUIA_TRANSPORTISTA,
															TR.documento AS TRANSPORTISTA_RUC,
															TR.razon_social AS TRANSPORTISTA_RAZONSOCIAL,
															UN.id_tipovehiculo,
															CH.licencia_conducir AS CONDUCTOR_DNI,
															CH.nombres AS CONDUCTOR_NOMBRES,
															DL.id_tipocarga,
															DL.num_bigbag,
															24 AS id_zonaorigen,
															NULL AS proveedorminero_ruc,
															NULL AS proveedorminero_razonsocial,
															NULL AS encargadomuestra_nombres,
															RE.ruc AS REMITENTE_RUC,
															RE.razon_social AS REMITENTE_RAZONSOCIAL,
															V.lote_id_producto,
															V.lote_id_tipomineral,
															DL.observacion,
															/*DL.peso_bruto_fechahoraregistro,
															DL.peso_tara_fechahoraregistro,*/
															DL.guias_fecha AS fecha_pesoinicial,
															DL.guias_fecha AS fecha_pesofinal,
															DL.peso_bruto,
															DL.peso_tara,
															DL.peso_neto,
															'" . $g_fecha . "' AS fechahora_registro,
															'" . $usuario_registro . "' AS fechahora_usuario
												 FROM despachos_segundotramo_programacion_detalle PD
															LEFT JOIN despachos_segundotramo_programacion P ON PD.id_programacion = P.Id
															LEFT JOIN despachos_segundotramo_distribucion_unidades U ON P.Id = U.id_programacion
															LEFT JOIN despachos_segundotramo_distribucion_lotes DL ON U.Id = DL.id_distribucionunidad
															AND PD.cod_lote = DL.cod_lote
															LEFT JOIN transporte UN ON U.id_unidad = UN.id_transporte
															LEFT JOIN transporte UN2 ON U.id_unidad2 = UN2.id_transporte
															LEFT JOIN tb_clientes TR ON UN.id_Transportista = TR.Id
															LEFT JOIN tbconfig_plantas PL ON PD.id_planta = PL.Id
															LEFT JOIN tbconfig_modalidadenvio ME ON PD.id_modalidadenvio = ME.Id
															LEFT JOIN despachos_primertramo_validaciondatos V ON PD.cod_lote = V.lote_cod_lote
															LEFT JOIN tbconfig_conductores CH ON DL.guias_idchofer = CH.Id
															LEFT JOIN tbconfig_remitentessegundotramo RE ON DL.guias_iddestino = RE.id_destino
															AND DL.guias_idmodalidadenvio = RE.id_modalidadenvio
												WHERE DL.Id = " . $arr_idregistros[$l];
		}

		// 3. Si ya existe el registro, se re-sincroniza (UPDATE).
		//    Si no existe, se inserta por primera vez (INSERT) y se genera el correlativo del ticket.
		if ($id_existente > 0) {

			$res_select = mysqli_query($enlace, $q_select_datos);
			if ($res_select && $row = mysqli_fetch_array($res_select)) {
				$q_update = "UPDATE consolidado_lotes_cierrecontable SET
								cod_lote = " . ($row[1] !== null ? "'" . mysqli_real_escape_string($enlace, $row[1]) . "'" : 'NULL') . ",
								lote_item = " . ($row[2] !== null ? $row[2] : 'NULL') . ",
								fecha_ingresobalanza = " . ($row[4] !== null ? "'" . $row[4] . "'" : 'NULL') . ",
								placa1 = " . ($row[5] !== null ? "'" . mysqli_real_escape_string($enlace, $row[5]) . "'" : 'NULL') . ",
								placa2 = " . ($row[6] !== null ? "'" . mysqli_real_escape_string($enlace, $row[6]) . "'" : 'NULL') . ",
								numguia_remitente = " . ($row[7] !== null ? "'" . mysqli_real_escape_string($enlace, $row[7]) . "'" : 'NULL') . ",
								numguia_transportista = " . ($row[8] !== null ? "'" . mysqli_real_escape_string($enlace, $row[8]) . "'" : 'NULL') . ",
								transportista_ruc = " . ($row[9] !== null ? "'" . mysqli_real_escape_string($enlace, $row[9]) . "'" : 'NULL') . ",
								transportista_razonsocial = " . ($row[10] !== null ? "'" . mysqli_real_escape_string($enlace, $row[10]) . "'" : 'NULL') . ",
								id_tipovehiculo = " . ($row[11] !== null ? $row[11] : 'NULL') . ",
								conductor_licencia = " . ($row[12] !== null ? "'" . mysqli_real_escape_string($enlace, $row[12]) . "'" : 'NULL') . ",
								conductor_nombres = " . ($row[13] !== null ? "'" . mysqli_real_escape_string($enlace, $row[13]) . "'" : 'NULL') . ",
								id_tipocarga = " . ($row[14] !== null ? $row[14] : 'NULL') . ",
								num_bigbag = " . ($row[15] !== null ? $row[15] : 'NULL') . ",
								remitente_ruc = " . ($row[20] !== null ? "'" . mysqli_real_escape_string($enlace, $row[20]) . "'" : 'NULL') . ",
								remitente_razonsocial = " . ($row[21] !== null ? "'" . mysqli_real_escape_string($enlace, $row[21]) . "'" : 'NULL') . ",
								id_producto = " . ($row[22] !== null ? $row[22] : 'NULL') . ",
								id_tipomineral = " . ($row[23] !== null ? $row[23] : 'NULL') . ",
								observacion = " . ($row[24] !== null ? "'" . mysqli_real_escape_string($enlace, $row[24]) . "'" : 'NULL') . ",
								fecha_pesoinicial = " . ($row[25] !== null ? "'" . $row[25] . "'" : 'NULL') . ",
								fecha_pesofinal = " . ($row[26] !== null ? "'" . $row[26] . "'" : 'NULL') . ",
								peso_bruto = " . ($row[27] !== null ? $row[27] : 'NULL') . ",
								peso_tara = " . ($row[28] !== null ? $row[28] : 'NULL') . ",
								peso_neto = " . ($row[29] !== null ? $row[29] : 'NULL') . ",
								fechahora_registro = '" . $g_fecha . "',
								fechahora_usuario = '" . $usuario_registro . "'
							 WHERE Id = " . $id_existente;
				mysqli_query($enlace, $q_update);
			}
			$skip_insert = true;
			$idregistro_new = 0;
		} else {

			$q_insert = "INSERT INTO consolidado_lotes_cierrecontable(
							id_registro,
							cod_lote,
							lote_item,
							id_tipoingreso,
							fecha_ingresobalanza,
							placa1,
							placa2,
							numguia_remitente,
							numguia_transportista,
							transportista_ruc,
							transportista_razonsocial,
							id_tipovehiculo,
							conductor_licencia,
							conductor_nombres,
							id_tipocarga,
							num_bigbag,
							id_zonaorigen,
							proveedorminero_ruc,
							proveedorminero_razonsocial,
							encargadomuestra_nombres,
							remitente_ruc,
							remitente_razonsocial,
							id_producto,
							id_tipomineral,
							observacion,
							fecha_pesoinicial,
							fecha_pesofinal,
							peso_bruto,
							peso_tara,
							peso_neto,
							fechahora_registro,
							fechahora_usuario
						) " . $q_select_datos;

			if ($res_datos = mysqli_query($enlace, $q_insert)) {
				$idregistro_new = mysqli_insert_id($enlace);
			} else {
				$idregistro_new = 0;
			}
		}

		if (!$skip_insert && $idregistro_new > 0) {
			// Genera los Número de Ticket del Cierre Contable (Primer y Segundo Tramo)
			// 1. Obtiene le Fecha del nuevo registro
			$fecha_x = '';

			$q_fecha = "SELECT fecha_ingresobalanza
														FROM consolidado_lotes_cierrecontable
													 WHERE Id = " . $idregistro_new;

			if ($res_fecha = mysqli_query($enlace, $q_fecha)) {
				if (mysqli_num_rows($res_fecha) > 0) {
					while ($row_fecha = mysqli_fetch_array($res_fecha)) {
						$fecha_x = $row_fecha["fecha_ingresobalanza"];
					}
				}
			}

			// 2. Obtiene el N° de Ticket asignado a los registros anteriores
			$c = 1;
			$correlativo_x = 0; // Para identificar el Correlativo de cada registro
			$continuar = 1; // Ayuda a saber cuando continuar

			$q_numticket = "SELECT num_ticketbalanza
																FROM consolidado_lotes_cierrecontable
															 WHERE fecha_ingresobalanza = '" . $fecha_x . "'
																 AND Id <> " . $idregistro_new . "
															ORDER BY num_ticketbalanza";

			if ($res_numticket = mysqli_query($enlace, $q_numticket)) {
				if (mysqli_num_rows($res_numticket) > 0) {
					while ($row_numticket = mysqli_fetch_array($res_numticket)) {
						// 3. Identifica el Correlativo de cada registro

						$correlativo_x = explode('-', $row_numticket["num_ticketbalanza"])[1];
						$correlativo_x = intval($correlativo_x);

						// 4. Crea un Array para buscar el Nuevo Correlativo
						while ($c < 10000) {

							if ($c == $correlativo_x) {
								$c++;

								break;
							}

							if ($c != $correlativo_x) {
								// Setea Prefijo
								$prefijo = explode('-', $fecha_x);
								$prefijo = $prefijo[2] . $prefijo[1] . substr($prefijo[0], 2);

								// Setea Correlativo
								$correlativo = $prefijo . '-' . str_pad($c, 3, '0', STR_PAD_LEFT);

								// Actualiza Correlativo
								$q_update = "UPDATE consolidado_lotes_cierrecontable SET";
								$q_update .= "   num_ticketbalanza = '" . $correlativo . "'";
								$q_update .= " WHERE Id = " . $idregistro_new;

								if ($q_update = mysqli_query($enlace, $q_update)) {
									$continuar = 0;

									break 2;
								}
							}

							$c++;
						}
					}
				}
			}

			// Asigna el Correlativo
			if ($continuar == 1) {
				// Setea Prefijo
				$prefijo = explode('-', $fecha_x);
				$prefijo = $prefijo[2] . $prefijo[1] . substr($prefijo[0], 2);

				// Setea Correlativo
				$correlativo = $prefijo . '-' . str_pad($c, 3, '0', STR_PAD_LEFT);

				// Actualiza Correlativo
				$q_update = "UPDATE consolidado_lotes_cierrecontable SET";
				$q_update .= "   num_ticketbalanza = '" . $correlativo . "'";
				$q_update .= " WHERE Id = " . $idregistro_new;

				if ($q_update = mysqli_query($enlace, $q_update)) {
				}
			}
		}

		$l++;
	}
}

// ----------------------------------------------------------------------------------------------------------
// Re-sincroniza el Ticket Contable (consolidado_lotes_cierrecontable) cuando se edita un valor
// desde el módulo "Resumen de Balanza" (case 'grabar_EditBalanza'). Esta función se encarga de:
//   1. Para Recepción de Mineral (tipo_condicion == 1):
//      - Localiza el id_CatalogoLotes relacionado (id_registro si $is_tablalotes == 1, o
//        lo busca por id_controlIngresoVehiculo si es un campo de controlingresovehiculo).
//      - Encuentra el Id de la fila en despachos_primertramo_validaciondatos (donde
//        lote_id_lote = id_CatalogoLotes) que es la fuente real del Ticket Contable.
//      - Propaga el cambio al campo correspondiente de despachos_primertramo_validaciondatos.
//      - Si el registro ya fue migrado a consolidado_lotes_cierrecontable, lo re-sincroniza
//        llamando a f_MigrarLotes_CierreContable con id_tipoingreso = 1.
//   2. Para Despacho de Mineral (tipo_condicion == 2):
//      - El id_registro ya es el Id de despachos_segundotramo_distribucion_lotes (tabla que
//        es fuente directa del Ticket Contable para Segundo Tramo).
//      - Si el registro ya fue migrado a consolidado_lotes_cierrecontable, lo re-sincroniza
//        llamando a f_MigrarLotes_CierreContable con id_tipoingreso = 2.
function f_ResyncTicketContable_ResumenBalanza($enlace, $id_registro, $item, $valor_original, $tipo_condicion, $is_tablalotes, $is_tabladistribucionlotes, $g_fecha, $usuario_registro)
{
	$id_tipoingreso_sync = 0;
	$id_registro_sync = 0;

	if ($tipo_condicion == 1) {
		// 1. Resolver el id_CatalogoLotes
		$id_catalogo_lotes = 0;

		if ($is_tablalotes == 1) {
			// $id_registro ya es catalogolotes.Id
			$id_catalogo_lotes = intval($id_registro);
		} else {
			// $id_registro es controlingresovehiculo.Id. Buscar el catalogolotes relacionado.
			$q_lookup = "SELECT id_CatalogoLotes
										 FROM catalogolotes
										WHERE id_controlIngresoVehiculo = " . intval($id_registro) . "
										ORDER BY id_CatalogoLotes DESC
										LIMIT 1";

			if ($res_lookup = mysqli_query($enlace, $q_lookup)) {
				if ($row_lookup = mysqli_fetch_assoc($res_lookup)) {
					$id_catalogo_lotes = intval($row_lookup["id_CatalogoLotes"]);
				}
			}
		}

		if ($id_catalogo_lotes <= 0) {
			return;
		}

		// 2. Encontrar el Id de la fila en despachos_primertramo_validaciondatos
		$q_lookup_vd = "SELECT Id
											FROM despachos_primertramo_validaciondatos
										 WHERE lote_id_lote = " . $id_catalogo_lotes . "
										 ORDER BY Id DESC
										 LIMIT 1";

		$id_vd = 0;
		if ($res_lookup_vd = mysqli_query($enlace, $q_lookup_vd)) {
			if ($row_lookup_vd = mysqli_fetch_assoc($res_lookup_vd)) {
				$id_vd = intval($row_lookup_vd["Id"]);
			}
		}

		if ($id_vd <= 0) {
			return;
		}

		// 3. Propagar el cambio al campo correspondiente de despachos_primertramo_validaciondatos
		//    según el item que se está editando.
		$vd_campo = '';
		$vd_valor_sql = '';

		switch (intval($item)) {
			case 2:
				$vd_campo = 'balanza_placa';
				break;
			case 3:
				$vd_campo = 'balanza_placa2';
				break;
			case 5:
				$vd_campo = 'balanza_id_tipovehiculo';
				break;
			case 6:
				$vd_campo = 'balanza_id_chofer';
				break;
			case 7:
				$vd_campo = 'lote_id_tipocarga';
				break;
			case 8:
				$vd_campo = 'lote_id_zonaorigen';
				break;
			case 9:
				$vd_campo = 'lote_id_proveedorminero';
				break;
			case 10:
				$vd_campo = 'lote_id_encargadomuestra';
				break;
			case 11:
				$vd_campo = 'lote_id_producto';
				break;
			case 12:
				$vd_campo = 'lote_id_tipomineral';
				break;
			case 13:
				// En resumen_balanza el usuario ingresa el peso en KG (tal como lo muestra el label).
				// El print_ticketbalanza.php muestra V.lote_peso_inicial directamente (en KG).
				// NO se multiplica por 1000 (a diferencia de primertramo_distribucion donde el input
				// ya viene dividido por 1000).
				$vd_campo = 'lote_peso_inicial';
				$vd_valor_sql = floatval($valor_original);
				break;
			case 14:
				$vd_campo = 'lote_peso_final';
				$vd_valor_sql = floatval($valor_original);
				break;
			case 15:
				$vd_campo = 'despacho_observacion';
				break;
			default:
				// Items 1, 4, 18 no tienen contraparte directa en despachos_primertramo_validaciondatos
				// para el Ticket Contable.
				break;
		}

		if (strlen($vd_campo) == 0) {
			return;
		}

		if (strlen($vd_valor_sql) == 0) {
			if (strlen(trim($valor_original)) == 0) {
				$vd_valor_sql = 'NULL';
			} else {
				$vd_valor_sql = "'" . mysqli_real_escape_string($enlace, $valor_original) . "'";
			}
		}

		$q_vd_update = "UPDATE despachos_primertramo_validaciondatos";
		$q_vd_update .= "   SET " . $vd_campo . " = " . $vd_valor_sql;
		$q_vd_update .= " WHERE Id = " . $id_vd;

		if (!mysqli_query($enlace, $q_vd_update)) {
			return;
		}

		// 4. Si se actualizó un peso (item 13 = bruto, item 14 = tara), re-sincronizar TODOS
		//    los campos de peso de despachos_primertramo_validaciondatos desde catalogolotes.
		//    Esto es necesario porque:
		//      a) En resumen_balanza el input llega en KG sin divisor de 1000 (a diferencia de
		//         update_PrimerTramo_DistribucionDatos).
		//      b) q_save + q_save2 ya actualizaron catalogolotes correctamente (nPeso_InicialBalanza,
		//         nPeso_FinalBalanza, nPesoBrutoBalanza, nPesoTaraBalanza, nPesoNetoBalanza).
		//      c) V puede tener valores stale de ediciones previas (por ejemplo, lote_peso_final
		//         corrupto por la regla anterior que recalculaba en base a lote_peso_neto viejo).
		//         Sincronizar desde catalogolotes es la unica forma de garantizar que el ticket
		//         muestre los valores correctos sin arrastrar incoherencias entre bruto, tara y neto.
		if (intval($item) == 13 || intval($item) == 14) {
			$q_sync = "UPDATE despachos_primertramo_validaciondatos V
									INNER JOIN catalogolotes L ON V.lote_id_lote = L.id_CatalogoLotes
									   SET V.lote_peso_inicial = L.nPeso_InicialBalanza,
										   V.lote_peso_final   = L.nPeso_FinalBalanza,
										   V.lote_peso_bruto   = L.nPesoBrutoBalanza,
										   V.lote_peso_tara    = L.nPesoTaraBalanza,
										   V.lote_peso_neto    = L.nPesoNetoBalanza
									 WHERE V.Id = " . $id_vd;

			mysqli_query($enlace, $q_sync);
		}

		$id_tipoingreso_sync = 1;
		$id_registro_sync = $id_vd;
	} elseif ($tipo_condicion == 2) {
		// Para Despacho de Mineral, el id_registro ya es el Id de
		// despachos_segundotramo_distribucion_lotes, que es la fuente directa del Ticket Contable.
		$id_tipoingreso_sync = 2;
		$id_registro_sync = intval($id_registro);
	} else {
		return;
	}

	// 5. Verificar si el registro ya fue migrado a consolidado_lotes_cierrecontable
	if ($id_tipoingreso_sync <= 0 || $id_registro_sync <= 0) {
		return;
	}

	$q_chk_migrado = "SELECT COUNT(Id) AS _COUNT
										FROM consolidado_lotes_cierrecontable
									 WHERE id_tipoingreso = " . $id_tipoingreso_sync . "
										 AND id_registro = " . $id_registro_sync;

	$chk_migrado = 0;
	if ($res_chk_migrado = mysqli_query($enlace, $q_chk_migrado)) {
		if ($row_chk_migrado = mysqli_fetch_array($res_chk_migrado)) {
			$chk_migrado = intval($row_chk_migrado["_COUNT"]);
		}
	}

	// 6. Si ya fue migrado, re-sincronizar el Ticket Contable con los nuevos valores
	if ($chk_migrado > 0) {
		f_MigrarLotes_CierreContable($enlace, $id_tipoingreso_sync, $id_registro_sync, $g_fecha, $usuario_registro);
	}
}

