					$html .= '  </td>';

					$html .= '  <td id="td_codinterno_' . $d . '" style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; font-weight: bold;">';
					$html .= '   ' . $row_datos["cod_interno"];
