								$q_ficticio = "INSERT INTO recepcion_ensayos_detallefactura (id_cabecera, item, descripcion, cantidad, precio, total, tiene_dscto, dscto, fechahora_registro, usuario_registro) VALUES(";
								$q_ficticio .= $id_recepcion . ', ';
