																																									 WHERE Id = " . $row_datos["is_ampliacion_de"] . ") AS DATOS),

																												cod_interno =  (SELECT cod_interno
																																							 FROM (SELECT D_x.cod_interno
																																									 FROM recepcion_ensayos_detalle D_x
																																									 WHERE Id = " . $row_datos["is_ampliacion_de"] . ") AS DATOS)
																									WHERE Id = " . $row_datos["Id"];

												if ($res_update = mysqli_query($enlace, $q_update)) {
												}
											}
