		$fecha_recepcion = mysqli_real_escape_string($enlace, $_POST["fecha_recepcion"]);

		// Obtiene datos
		$q_clientes = "SELECT DISTINCT cliente_documento,
															cliente_razonsocial
												 FROM recepcion_ensayos_cabecera
												WHERE DATE(fechahora_recepcion) = '" . $fecha_recepcion . "'
