	case 'get_ListaVentasAmpliacion':
		$res = array();
		$estado = 0;

		// Recuperando parámetros
		$fecha_recepcion = mysqli_real_escape_string($enlace, $_POST["fecha_recepcion"]);
		$documento = mysqli_real_escape_string($enlace, $_POST["documento"]);

		// Obtiene datos
		$html = '';
		$c = 1;

		$q_ventas = "SELECT C.Id,
														C.cod_interno_preliminar,
														SUBSTRING(C.fechahora_recepcion, 12, 5) AS HORA_RECEPCION,

														(SELECT COUNT(D_x.Id)
															 FROM recepcion_ensayos_detalle D_x
															WHERE D_x.id_cabecera = C.Id
															AND D_x.estado = 'A') AS TOTAL_MUESTRAS,

														(SELECT IFNULL(SUM(D_x.exceso), 0)
															 FROM recepcion_ensayos_detalle D_x
															WHERE D_x.id_cabecera = C.Id
															AND D_x.estado = 'A') AS EXCESO,

														(SELECT SUM(EA.total)
															 FROM recepcion_ensayos_analisis EA
															WHERE EA.id_detalle IN (SELECT D_x.Id
																												FROM recepcion_ensayos_detalle D_x
																											 WHERE D_x.id_cabecera = C.Id)) AS SUB_TOTAL,

														CASE WHEN C.tiene_recojo = 1 THEN 10 ELSE 0 END AS TIENE_RECOJO

											 FROM recepcion_ensayos_cabecera C
											WHERE C.cliente_documento = '" . $documento . "'
												AND DATE(C.fechahora_recepcion) = '" . $fecha_recepcion . "'
												AND C.is_instruccion = 1
									 ORDER BY C.fechahora_recepcion";

		if ($res_ventas = mysqli_query($enlace, $q_ventas)) {
			if (mysqli_num_rows($res_ventas) > 0) {
				$estado = 1;

				while ($row_ventas = mysqli_fetch_array($res_ventas)) {
					$html .= '<tr id="tr_VentaAmpliacion_' . $c . '" style="cursor: pointer; font-size: 14px; ' . (($c == 1) ? 'background-color: #FFF587;' : '') . '" onclick="f_GetListaMuestrasAmpliacion(' . $c . ', ' . $row_ventas["Id"] . ');">';
					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: right;">';
					$html .= '    ' . $c;

					if ($c == 1) {
						$first_Id = $row_ventas["Id"];
					}

					$html .= '  </td>';

					$html .= '  <td id="td_MuestraAmpliacion_' . $row_ventas["Id"] . '" style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';
					$html .= '    ' . $row_ventas["cod_interno_preliminar"];
					$html .= '  </td>';

					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';
					$html .= '    ' . $row_ventas["HORA_RECEPCION"];
					$html .= '  </td>';

					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';
					$html .= '    ' . $row_ventas["TOTAL_MUESTRAS"];
					$html .= '  </td>';

					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: right;">';
					$html .= '    ' . number_format($row_ventas["EXCESO"] + $row_ventas["SUB_TOTAL"] + $row_ventas["TIENE_RECOJO"], 2, '.', '');
					$html .= '  </td>';
					$html .= '</tr>';

					$c++;
				}
			}
		}

		echo json_encode(array('estado' => $estado, 'html' => $html, 'first_Id' => $first_Id));

		break;

	case 'get_ListaMuestrasAmpliacion':
		$res = array();
		$estado = 0;

		// Recuperando parámetros
		$id_recepcion = mysqli_real_escape_string($enlace, $_POST["id_recepcion"]);

		// Obtiene datos
		$html = '';
		$c = 1;

		$q_muestras = "SELECT Id,
															nombre_muestra
												 FROM recepcion_ensayos_detalle
												WHERE id_cabecera = " . $id_recepcion . "
													AND estado = 'A'
											 ORDER BY Id";

		if ($res_muestras = mysqli_query($enlace, $q_muestras)) {
			if (mysqli_num_rows($res_muestras) > 0) {
				$estado = 1;

				while ($row_muestras = mysqli_fetch_array($res_muestras)) {
					$html .= '<tr id="tr_itemmuestrasampliacion_' . $c . '" style="cursor: pointer; font-size: 14px;">';
					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';
					$html .= '  	<input id="chk_itemmuestrasampliacion_' . $c . '" class="form-check-input" type="checkbox" onchange="f_SelectedMuestrasAmpliacion(' . $c . ')">';
					$html .= '    <input id="id_muestraampliacion_' . $c . '" type="hidden" value="' . $row_muestras["Id"] . '">';
					$html .= '  </td>';

					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: right;">';
					$html .= '    ' . $c;
					$html .= '  </td>';

					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';
					$html .= '    ' . $row_muestras["nombre_muestra"];
					$html .= '  </td>';

					// 1. Obtiene análisis de Precios Generales
					$analisis = '';

					$q_analisis = "SELECT CONCAT('(', EA.abv, CASE WHEN LENGTH(IFNULL(C.abv, '')) > 0 THEN CONCAT(' ', C.abv) ELSE '' END, ')') AS abv,
																			REA.total
																 FROM recepcion_ensayos_analisis REA
																			INNER JOIN tb_ensayos_analisisclasificaciones_detalle ACD ON REA.cod_analisis = ACD.Id
																			INNER JOIN tb_ensayos_analisisclasificaciones C ON ACD.cod_clasificacion = C.Id
																			INNER JOIN tb_ensayos_analisis EA ON ACD.cod_analisis = EA.Id
																WHERE REA.id_detalle = " . $row_muestras["Id"] . "
																	AND is_paquete = 0
																	AND is_paquetecliente = 0
															 ORDER BY EA.orden";

					if ($res_analisis = mysqli_query($enlace, $q_analisis)) {
						if (mysqli_num_rows($res_analisis) > 0) {
							while ($row_analisis = mysqli_fetch_array($res_analisis)) {
								$analisis .= '            ' . $row_analisis["abv"] . ', ';
							}
						}
					}

					// 2. Obtiene análisis de Paquetes Generales
					$q_paquetes = "SELECT C.abv,
																			C.descripcion AS CLASIFICACION,
																			REA.cod_analisis,
																			REA.total,
																			REA.is_paquete,
																			REA.is_paquetecliente
																 FROM recepcion_ensayos_analisis REA
																			INNER JOIN tb_ensayos_analisisclasificaciones_paquetes P ON REA.cod_analisis = P.Id
																			INNER JOIN tb_ensayos_analisisclasificaciones C ON P.cod_clasificacion = C.Id
																WHERE REA.id_detalle = " . $row_muestras["Id"] . "
																	AND REA.is_paquete = 1";

					if ($res_paquetes = mysqli_query($enlace, $q_paquetes)) {
						if (mysqli_num_rows($res_paquetes) > 0) {
							while ($row_paquetes = mysqli_fetch_array($res_paquetes)) {
								// Armando la descripción de análisis por paquete
								$abv = '';
								$descripcion = '';

								$q_analisispaquete = "SELECT A.abv,
																										A.descripcion
																							 FROM tb_ensayos_analisisclasificaciones_paquetes_detalle D
																										INNER JOIN tb_ensayos_analisis A ON D.cod_analisis = A.Id
																							WHERE D.cod_paquete = " . $row_paquetes["cod_analisis"];

								if ($res_analisispaquete = mysqli_query($enlace, $q_analisispaquete)) {
									if (mysqli_num_rows($res_analisispaquete) > 0) {
										while ($row_analisispaquete = mysqli_fetch_array($res_analisispaquete)) {
											$abv .= $row_analisispaquete["abv"] . ' - ';
											$descripcion .= $row_analisispaquete["descripcion"] . ' - ';
										}
									}
								}

								if (strlen($abv) > 0) {
									$abv = substr($abv, 0, -3);
									$descripcion = substr($descripcion, 0, -3);
								}

								// Creando el query final
								$q_analisis = "SELECT '(" . $abv . ")' AS abv,
																								" . $row_paquetes["total"] . " AS total";

								if ($res_analisis = mysqli_query($enlace, $q_analisis)) {
									if (mysqli_num_rows($res_analisis) > 0) {
										while ($row_analisis = mysqli_fetch_array($res_analisis)) {
											$analisis .= '            ' . $row_analisis["abv"] . ', ';
										}
									}
								}
							}
						}
					}

					// 3. Obtiene análisis de Paquetes de Clientes
					$q_paquetes = "SELECT C.abv,
																			C.descripcion AS CLASIFICACION,
																			REA.cod_analisis,
																			REA.total,
																			REA.is_paquete,
																			REA.is_paquetecliente
																 FROM recepcion_ensayos_analisis REA
																			INNER JOIN tb_ensayos_analisisclasificaciones_paquetesclientes P ON REA.cod_analisis = P.Id
																			INNER JOIN tb_ensayos_analisisclasificaciones C ON P.cod_clasificacion = C.Id
																WHERE REA.id_detalle = " . $row_muestras["Id"] . "
																	AND REA.is_paquetecliente = 1";

					if ($res_paquetes = mysqli_query($enlace, $q_paquetes)) {
						if (mysqli_num_rows($res_paquetes) > 0) {
							while ($row_paquetes = mysqli_fetch_array($res_paquetes)) {
								// Armando la descripción de análisis por paquete
								$abv = '';
								$descripcion = '';

								$q_analisispaquete = "SELECT A.abv,
																										A.descripcion
																							 FROM tb_ensayos_analisisclasificaciones_paquetesclientes_detalle D
																										INNER JOIN tb_ensayos_analisis A ON D.cod_analisis = A.Id
																							WHERE D.cod_paquete = " . $row_paquetes["cod_analisis"];

								if ($res_analisispaquete = mysqli_query($enlace, $q_analisispaquete)) {
									if (mysqli_num_rows($res_analisispaquete) > 0) {
										while ($row_analisispaquete = mysqli_fetch_array($res_analisispaquete)) {
											$abv .= $row_analisispaquete["abv"] . ' - ';
											$descripcion .= $row_analisispaquete["descripcion"] . ' - ';
										}
									}
								}

								if (strlen($abv) > 0) {
									$abv = substr($abv, 0, -3);
									$descripcion = substr($descripcion, 0, -3);
								}

								// Creando el query final
								$q_analisis = "SELECT '(" . $abv . ")' AS abv,
																								" . $row_paquetes["total"] . " AS total";

								if ($res_analisis = mysqli_query($enlace, $q_analisis)) {
									if (mysqli_num_rows($res_analisis) > 0) {
										while ($row_analisis = mysqli_fetch_array($res_analisis)) {
											$analisis .= '            ' . $row_analisis["abv"] . ', ';
										}
									}
								}
							}
						}
					}

					if (strlen($analisis) > 0) {
						$analisis = substr($analisis, 0, -2);
					}

					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';
					$html .= '    ' . $analisis;
					$html .= '  </td>';
					$html .= '</tr>';

					if ($c == 1) {
						$first_Id = $row_ventas["Id"];
					}

					$c++;
				}
			}
		}

		echo json_encode(array('estado' => $estado, 'html' => $html, 'first_Id' => $first_Id));

		break;

	case 'get_IdRecepcion_Ampliacion':
		$estado = 1;

		// Recupera parámetros
		$id_recepcion_origen = mysqli_real_escape_string($enlace, $_POST["id_recepcion_origen"]);
		$arr_muestras = mysqli_real_escape_string($enlace, $_POST["arr_muestras"]);
		$usuario_registro = $_SESSION["usu_usuario"];

		// Obtiene el nuevo código de Requerimiento
		$num_ampliacion = '';

		$q_requerimiento = "SELECT COUNT(Id) + 1 AS _COUNT
															FROM recepcion_ensayos_cabecera
														 WHERE is_ampliacion_de = " . $id_recepcion_origen . "
															 AND is_recepcioncanceled = 0";

		if ($res_requerimiento = mysqli_query($enlace, $q_requerimiento)) {
			if (mysqli_num_rows($res_requerimiento) > 0) {
				while ($row_requerimiento = mysqli_fetch_array($res_requerimiento)) {
					$num_ampliacion = '-' . str_pad($row_requerimiento["_COUNT"], 2, "0", STR_PAD_LEFT);
				}
			}
		}

		// Si es un registro nuevo hace copia del original
		$q_copia = "INSERT INTO recepcion_ensayos_cabecera(cod_interno_preliminar, fechahora_recepcion, cliente_documento,
																cliente_razonsocial, entregado_por, celular_areportar, cod_sucursal, cod_moneda, observacion,
																tiene_recojo, is_temporal, cod_recibocorrelativo, recibo_codigo, is_ampliacion_de,
																ampliacion_idmuestras, fechahora_registro, usuario_registro)

										SELECT CONCAT(cod_interno_preliminar, '" . $num_ampliacion . "') AS cod_interno_preliminar,
													 '" . $g_fecha . "' AS fechahora_recepcion,
													 cliente_documento,
													 cliente_razonsocial,
													 entregado_por,
													 celular_areportar,
													 cod_sucursal,
													 cod_moneda,
													 observacion,
													 tiene_recojo,
													 1 AS is_temporal,
													 cod_recibocorrelativo,
													 CONCAT(recibo_codigo, '" . $num_ampliacion . "') AS recibo_codigo,
													 " . $id_recepcion_origen . " AS is_ampliacion_de,
													 '" . str_replace('|', ', ', $arr_muestras) . "' AS ampliacion_idmuestras,
													 '" . $g_fecha . "' AS fechahora_registro,
													 '" . $usuario_registro . "' AS usuario_registro
											FROM recepcion_ensayos_cabecera
										 WHERE Id = " . $id_recepcion_origen;

		if ($res_copia = mysqli_query($enlace, $q_copia)) {
			$id_recepcion = mysqli_insert_id($enlace);
			$id_md5 = md5($id_recepcion);

			// Actualiza el campo de "tiene_ampliacion" en la Recepción Original
			$q_update = "UPDATE recepcion_ensayos_cabecera SET
																tiene_ampliacion = 1
													WHERE Id = " . $id_recepcion_origen;

			if ($res_update = mysqli_query($enlace, $q_update)) {
				$estado = 1;

				// Actualiza detalle
				$num_detalle = 1;
				$d = 0;
				$arr_muestras = explode('|', $arr_muestras);

				while ($d < count($arr_muestras)) {
					$q_detalle = "INSERT INTO recepcion_ensayos_detalle (id_cabecera, cod_interno_preliminar, nombre_muestra,
																						peso_muestra, cod_estadomuestra, cod_envasemuestra, cod_tipomuestra, cod_ensayomuestra,
																						fechahora_registro, usuario_registro, is_ampliacion_de)

																SELECT " . $id_recepcion . " AS id_cabecera,
																	
																			 (SELECT CONCAT(C.cod_interno_preliminar, '-', '" . str_pad($num_detalle, 3, "0", STR_PAD_LEFT) . "')
																					FROM recepcion_ensayos_cabecera C
																				 WHERE C.Id = $id_recepcion) AS cod_interno_preliminar,

																			 nombre_muestra,
																			 peso_muestra,
																			 cod_estadomuestra,
																			 cod_envasemuestra,
																			 cod_tipomuestra,
																			 cod_ensayomuestra,
																			 '" . $g_fecha . "',
																			 '" . $usuario_registro . "',
																			 " . $arr_muestras[$d] . " AS is_ampliacion_de
																	FROM recepcion_ensayos_detalle
																 WHERE Id = " . $arr_muestras[$d];

					if ($res_detalle = mysqli_query($enlace, $q_detalle)) {
						// Actualiza estado de registro original
						$q_update = "UPDATE recepcion_ensayos_detalle
																			SET tiene_ampliacion = 1
																		WHERE Id = " . $arr_muestras[$d];

						if ($res_update = mysqli_query($enlace, $q_update)) {
						} else {
							$estado = 0;
						}
					} else {
						$estado = 0;
					}

					$d++;
					$num_detalle++;
				}
			}
		} else {
			$estado = 0;
		}

		echo json_encode(array('estado' => $estado, 'id_recepcion' => $id_recepcion, 'id_md5' => $id_md5));

		break;

	case 'anular_Venta':
		$res = array();
		$estado = 0;

		$id_recepcion = mysqli_real_escape_string($enlace, $_POST["id_recepcion"]);
		$usuario_registro = $_SESSION["usu_usuario"];

		// Elimina muestras
		$q_anular = "UPDATE recepcion_ensayos_cabecera
												SET is_recepcioncanceled = 1,
														facturador_estado = 'Venta Anulada',
														recepcioncanceled_fechahoraregistro = '" . $g_fecha . "',
														recepcioncanceled_usuarioregistro = '" . $usuario_registro . "'
											WHERE Id = " . $id_recepcion;

		if ($res_anular = mysqli_query($enlace, $q_anular)) {
			$estado = 1;
		}

		echo json_encode(array('estado' => $estado));

		break;

	case 'editar_Venta':
		$res = array();
		$estado = 0;

		$id_recepcion = mysqli_real_escape_string($enlace, $_POST["id_recepcion"]);
		$usuario_registro = $_SESSION["usu_usuario"];

		// Verificar que no haya un registro de venta en curso
		$tiene_venta = 0;

		$q_verify = "SELECT COUNT(Id) AS _COUNT
											 FROM recepcion_ensayos_cabecera
											WHERE usuario_registro = '" . $usuario_registro . "'
												AND is_temporal = 1";

		if ($res_verify = mysqli_query($enlace, $q_verify)) {
			if (mysqli_num_rows($res_verify) > 0) {
				while ($row_verify = mysqli_fetch_array($res_verify)) {
					if ($row_verify["_COUNT"] > 0) {
						$tiene_venta = 1;

						$estado = 2;

						echo json_encode(array('estado' => $estado));
						return;
					}
				}
			}
		}

		// Cambiar estado
		$q_editar = "UPDATE recepcion_ensayos_cabecera
												SET is_temporal = 1,
														usuario_registro = '" . $usuario_registro . "'
											WHERE Id = " . $id_recepcion;

		if ($res_editar = mysqli_query($enlace, $q_editar)) {
			$estado = 1;
		}

		echo json_encode(array('estado' => $estado));

		break;

	case 'get_LQRecepcionMuestras':
		$res = array();
		$estado = 0;
		$html = '';
		$d = 1;

		// Recuperando parámetros
		$fecha_inicio = mysqli_real_escape_string($enlace, $_POST["fecha_inicio"]);
		$fecha_fin = mysqli_real_escape_string($enlace, $_POST["fecha_fin"]);
		$filtro_CI = mysqli_real_escape_string($enlace, $_POST["filtro_CI"]);
		$filtro_opt1 = mysqli_real_escape_string($enlace, $_POST["filtro_opt1"]);
		$filtro_opt2 = mysqli_real_escape_string($enlace, $_POST["filtro_opt2"]);
		$filtro_opt3 = mysqli_real_escape_string($enlace, $_POST["filtro_opt3"]);

		// Obtiene datos
		$q_datos = "SELECT L.ccod_Lote,
													 CONCAT(CIV.dFechaIngreso, ' ', CIV.dhoraingresoPlanta) AS FECHAHORA_INGRESO,
													 CIV.placa,
													 CIV.placa2,
													 TM.descripcion AS TIPO_MINERAL,
													 L.nPesoNetoBalanza,
													 L.humedad_pesohumedad,
													 L.preparacion_fechahoraregistro,
													 L.preparacion_usuarioregistro
											FROM catalogolotes L
													 LEFT JOIN controlingresovehiculo CIV ON L.id_controlIngresoVehiculo = CIV.id_controlIngresoVehiculo
													 LEFT JOIN tbconfig_tipomineral TM ON L.balanza_id_tipomineral = TM.Id
										 WHERE 1 = 1";

		if (strlen(trim($filtro_CI)) > 0) {
			$q_datos .= "   AND L.ccod_Lote LIKE '%" . trim($filtro_CI) . "%'";
		} else {
