					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; font-weight: bold; text-align: center;">';
					$html .= '    ' . $row_detalle["TIPO_MUESTRA"] . '<br>' . $row_detalle["ESTADO_MUESTRA"];
					$html .= '  </td>';

