					// Arma un Array de los elementos en función al análisis
					$arr_analisismuestras = "'" . str_replace('|', "', '", str_replace(' ', '', $analisis_muestra) . "'");

					// Arma la cadena de códigos de elementos
					$arr_analisis_x = '';

					$q_codelementos = "SELECT Id,
																						abv AS cod_elemento
