					$total_acompanantes = (($total_acompanantes == 0) ? 1 : $total_acompanantes);

					$html .= '<tr id="tr_idunidad_' . $row_ingreso["id_controlIngresoVehiculo"] . '" style="font-size: 14px;">';

					if ($id_registro != $row_ingreso["id_controlIngresoVehiculo"]) {
						$html .= '  <td rowspan="' . $total_acompanantes . '" style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';
						$html .= '    ' . $d;
						$html .= '  </td>';

						$html .= '  <td rowspan="' . $total_acompanantes . '" style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';
						$html .= '    ' . $row_ingreso["FECHAHORA_REGISTRO"] . '<br><i>' . $row_ingreso["usuario_registro"] . '</i>';
						$html .= '  </td>';

						$html .= '  <td rowspan="' . $total_acompanantes . '" style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';
