								$campo_x = 'balanza_id_tipovehiculo';
							}

							// Actualiza el maestro de Unidades
							$q_update = "UPDATE transporte
																		SET " . $campo . " = " . ((strlen($valor) > 0) ? $valor : 'NULL') . "
																	WHERE cplaca = (SELECT balanza_placa
																										FROM despachos_primertramo_validaciondatos
