							return;
						}
					}
				}
			}

			// Guardando datos
			$q_save = " UPDATE tbconfig_plantas";
			$q_save .= "   SET ruc = '" . $planta_ruc . "', ";
			$q_save .= "       descripcion = '" . $planta_descripcion . "'";
			$q_save .= " WHERE Id = " . $id_planta;
