	case 'get_LotesProgramadosParaDespacho':
		$estado = 0;
		$html = '';

		// Recupera parámetros
		$id_planta = trim(mysqli_real_escape_string($enlace, $_POST['id_planta']));
		$cod_lote = trim(mysqli_real_escape_string($enlace, $_POST['cod_lote']));
		$cod_proveedorminero = trim(mysqli_real_escape_string($enlace, $_POST['cod_proveedorminero']));
		$cod_modalidadenvio = trim(mysqli_real_escape_string($enlace, $_POST['cod_modalidadenvio']));

		// Obtiene datos
		$d = 1;
		$id_lote = 0;

		$q_datos = "SELECT V.lote_cod_lote,
													 IFNULL(EM.nombres, '---') AS ENCARGADO_MUESTRA,
													 IFNULL(PM.razon_social, '---') AS PROVEEDOR_MINERO,
													 IFNULL(ME.descripcion, '---') AS MODALIDAD_ENVIO,
													 IFNULL(HC.cierre_prom, '') AS HUMEDAD,
													 IFNULL(PL.nombre_comercial, PL.descripcion) AS PLANTA_INGRESO,
													 SUM(V.lote_peso_neto) AS NETO_TMH
											FROM despachos_primertramo_validaciondatos V
													 LEFT JOIN tbconfig_encargadosmuestra EM ON V.lote_id_encargadomuestra = EM.Id
													 LEFT JOIN tb_clientes PM ON V.lote_id_proveedorminero = PM.Id
													 " . (($id_planta == 16) ? 'LEFT' : 'INNER') . " JOIN tbconfig_modalidadenvio ME ON V.despacho_id_modalidadenvio = ME.Id
													 LEFT JOIN analisislq_humedad_cabecera HC ON V.lote_cod_lote = HC.cod_interno
															AND HC.is_cierre = 1
													 LEFT JOIN catalogolotes L ON V.lote_cod_lote = L.ccod_Lote
													 LEFT JOIN tbconfig_plantas PL ON L.balanza_id_planta = PL.Id
										 WHERE 1 = 1";

		// Si es Planta de MINERAL RETIRADO
		if ($id_planta == 16) {
