			if ($res_save = mysqli_query($enlace, $q_save)) {
				$id_programacion = mysqli_insert_id($enlace);
				$estado = 1;
			} else {
				echo json_encode(array('estado' => $estado));
				return;
			}

			$l = 0;
			$lotes_in = explode('|', $arr_lotes);

			while ($l < count($lotes_in)) {
				$q_detalle = "INSERT INTO despachos_segundotramo_programacion_detalle (id_programacion, cod_lote, id_planta,
																			id_modalidadenvio, codigo_despacho, codigo_despacho_comercializacion,
																			codigo_planta, TMH, fechahora_registro, usuario_registro) VALUES (";
				$q_detalle .= $id_programacion . ", ";
				$q_detalle .= "'" . $lotes_in[$l] . "', ";
				$q_detalle .= $id_planta . ", ";
				$q_detalle .= 'NULL, ';
				$q_detalle .= 'NULL, ';
				$q_detalle .= 'NULL, ';
				$q_detalle .= 'NULL, ';
				$q_detalle .= "(SELECT SUM(lote_peso_neto) AS NETO_TMH
															FROM despachos_primertramo_validaciondatos
														 WHERE lote_cod_lote = '" . $lotes_in[$l] . "'), ";
				$q_detalle .= "'" . $g_fecha . "', ";
				$q_detalle .= "'" . $usuario_registro . "')";

				if ($res_detalle = mysqli_query($enlace, $q_detalle)) {
				}

				$l++;
			}

			echo json_encode(array('estado' => $estado));

			return;
		}

// ============================================================
		// LOGICA NUEVA: Colibri (3) y Solandra (5)
		// - Cabecera GLOBAL por planta (mismo codigo para todos los lotes de la programacion)
		// - Detalle COMPARTIDO por empresa dentro del mismo despacho
		//   (todos los lotes VIII = mismo codigo; todos los lotes 48 SAC = mismo codigo)
		// - Permite mezclar lotes de VIII y 48 SAC en la misma programacion
		// - Campana opcional para Solandra (id_campana puede ser null)
		// ============================================================

		$lotes_in = "'" . str_replace('|', "', '", $arr_lotes) . "'";

		// 1. Obtener los lotes seleccionados con su modalidad
		$lotes = array();

		$q_lotes_sel = "SELECT DISTINCT lote_cod_lote, despacho_id_modalidadenvio
												 FROM despachos_primertramo_validaciondatos
												WHERE lote_cod_lote IN (" . $lotes_in . ")
											 ORDER BY lote_cod_lote";

		if ($res_lotes_sel = mysqli_query($enlace, $q_lotes_sel)) {
			if (mysqli_num_rows($res_lotes_sel) > 0) {
				while ($row_lotes_sel = mysqli_fetch_array($res_lotes_sel)) {
					$lotes[] = array(
						'cod_lote' => $row_lotes_sel["lote_cod_lote"],
						'id_modalidadenvio' => intval($row_lotes_sel["despacho_id_modalidadenvio"])
					);
				}
			}
		}

		if (count($lotes) == 0) {
			echo json_encode(array('estado' => 6, 'mensaje' => 'No se encontraron lotes validos.'));
			return;
		}

		// 2. Agrupar lotes por modalidad para validar
		$lotes_por_modalidad = array();
		foreach ($lotes as $lote) {
			$mod = $lote['id_modalidadenvio'];
			if (!isset($lotes_por_modalidad[$mod])) {
				$lotes_por_modalidad[$mod] = array();
			}
			$lotes_por_modalidad[$mod][] = $lote['cod_lote'];
		}

		// 3. Para Solandra: la campana es OPCIONAL
		$id_campana = null;
		$codigo_campana = null;
		$is_campana_requerida = false;

		if ($id_planta == 5 && $is_aplica_campana == 1 && $id_campana_input > 0) {
			// Usuario indico aplicar campana y selecciono una: usar esa
			$id_campana = $id_campana_input;
			$is_campana_requerida = true;
		}
		// Si NO se aplica campana, $id_campana queda en null y la cabecera sera solo "S<nro>"

		// 4. Calcular UNA sola CABECERA GLOBAL para todo el despacho
		//    La cabecera es CONTINUA por planta (Colibri) o por planta+campana (Solandra).
		//    NO se reinicia por empresa. Todos los lotes del despacho comparten el
		//    mismo codigo de cabecera (Cxxx, CPyy-Sxxx o Sxxx).
		$cabecera_global = null;

		// Toma la primera modalidad valida (5 o 6) presente en los lotes, solo
		// para pasarla como parametro de firma (la CAB ya no depende de la modalidad).
		$modalidad_referencia = null;
		foreach (array_keys($lotes_por_modalidad) as $mod) {
			if ($mod == 5 || $mod == 6) {
				$modalidad_referencia = $mod;
				break;
			}
		}

		if (is_null($modalidad_referencia)) {
			echo json_encode(array('estado' => 5, 'mensaje' => 'No hay lotes de modalidades 5 (VIII) o 6 (48 SAC) para generar codigo.'));
			return;
		}

		// Calcular CABECERA global (compartida por todos los lotes del despacho)
		$cab = f_CalcularSiguienteCorrelativoDespacho($enlace, $id_planta, $modalidad_referencia, 'CAB', $id_campana, $is_campana_requerida);

		if (!is_null($cab['error'])) {
			echo json_encode(array('estado' => 5, 'mensaje' => $cab['error']));
			return;
		}

		// Tomar el codigo_campana resuelto por la funcion (puede ser null si no se aplica)
		$codigo_campana = $cab['codigo_campana'];

		$cabecera_global = array(
			'correlativo' => intval($cab['correlativo']),
			'codigo' => f_ConstruirCodigoCabecera($id_planta, $codigo_campana, $cab['correlativo'])
		);

		// 5. Registra la CABECERA de la programacion (sin modalidad, es solo agrupador)
		$q_save = "INSERT INTO despachos_segundotramo_programacion (id_planta, id_modalidadenvio, id_campana, fechahora_registro, usuario_registro) VALUES (";
		$q_save .= $id_planta . ', ';
		$q_save .= 'NULL, ';  // La cabecera de programacion es solo agrupador (las cabeceras por modalidad estan en correlativo_despacho)
		$q_save .= (($id_campana === null) ? 'NULL' : $id_campana) . ', ';
		$q_save .= "'" . $g_fecha . "', ";
		$q_save .= "'" . $usuario_registro . "')";

		if ($res_save = mysqli_query($enlace, $q_save)) {
			$id_programacion = mysqli_insert_id($enlace);
			$estado = 1;
		} else {
			echo json_encode(array('estado' => 0, 'mensaje' => 'Error al registrar la cabecera.'));
			return;
		}

		// 6. Registra UN SOLO CORRELATIVO DE CABECERA GLOBAL para el despacho
		//    (la cabecera es compartida por todas las modalidades: VIII y 48 SAC
		//    usan el mismo codigo Cxxx / CPyy-Sxxx / Sxxx).
		$q_corr_cab = "INSERT INTO correlativo_despacho (id_programacion, id_planta, id_modalidadenvio, id_campana, correlativo, codigo_programacion, fechahora_registro, usuario_registro) VALUES (";
		$q_corr_cab .= $id_programacion . ", ";
		$q_corr_cab .= $id_planta . ", ";
		$q_corr_cab .= "NULL, ";  // Cabecera global: no pertenece a una modalidad especifica
		$q_corr_cab .= (($id_campana === null) ? 'NULL' : $id_campana) . ", ";
		$q_corr_cab .= $cabecera_global['correlativo'] . ", ";
		$q_corr_cab .= "'" . $cabecera_global['codigo'] . "', ";
		$q_corr_cab .= "'" . $g_fecha . "', ";
		$q_corr_cab .= "'" . $usuario_registro . "')";

		if (!mysqli_query($enlace, $q_corr_cab)) {
			$estado = 7;
		}

		// 7. Calcular UNA sola vez el codigo de detalle POR MODALIDAD (no por lote).
		//    Todos los lotes de la misma empresa comparten el MISMO codigo detalle.
		$detalles_por_modalidad = array(); // [id_modalidadenvio] => array('correlativo'=>N, 'codigo'=>'...')

		foreach (array_keys($lotes_por_modalidad) as $mod) {
			if ($mod != 5 && $mod != 6) {
				continue;
			}

			$det = f_CalcularSiguienteCorrelativoDespacho($enlace, $id_planta, $mod, 'DET', $id_campana, $is_campana_requerida);

			if (!is_null($det['error'])) {
				echo json_encode(array('estado' => 5, 'mensaje' => $det['error']));
				return;
			}

			$detalle_correlativo = intval($det['correlativo']);
			$prefijo_empresa = f_GetPrefijoEmpresaDespacho($mod);
			$codigo_detalle = f_ConstruirCodigoDetalle($cabecera_global['codigo'], $prefijo_empresa, $detalle_correlativo);

			$detalles_por_modalidad[$mod] = array(
				'correlativo' => $detalle_correlativo,
				'codigo' => $codigo_detalle
			);
		}

		// 8. Por cada lote: inserta el detalle con el codigo compartido por modalidad
		foreach ($lotes as $lote) {
			$cod_lote = $lote['cod_lote'];
			$mod_lote = $lote['id_modalidadenvio'];

			$codigo_cabecera_lote = NULL;
			$codigo_detalle_lote = NULL;

			if ($mod_lote == 5 || $mod_lote == 6) {
				$codigo_cabecera_lote = $cabecera_global['codigo'];
				$codigo_detalle_lote = $detalles_por_modalidad[$mod_lote]['codigo'];
			}

			// a. Inserta el detalle
			$q_detalle = "INSERT INTO despachos_segundotramo_programacion_detalle (id_programacion, cod_lote, id_planta,
																				id_modalidadenvio, codigo_despacho, codigo_despacho_comercializacion,
																				codigo_planta, TMH, fechahora_registro, usuario_registro) VALUES (";
			$q_detalle .= $id_programacion . ", ";
			$q_detalle .= "'" . $cod_lote . "', ";
			$q_detalle .= $id_planta . ", ";
			$q_detalle .= $mod_lote . ", ";
			$q_detalle .= (($codigo_cabecera_lote === null) ? 'NULL' : "'" . $codigo_cabecera_lote . "'") . ", ";
			$q_detalle .= (($codigo_detalle_lote === null) ? 'NULL' : "'" . $codigo_detalle_lote . "'") . ", ";
			$q_detalle .= "NULL, ";
			$q_detalle .= "(SELECT SUM(lote_peso_neto) AS NETO_TMH
													 FROM despachos_primertramo_validaciondatos
											  WHERE lote_cod_lote = '" . $cod_lote . "'), ";
			$q_detalle .= "'" . $g_fecha . "', ";
			$q_detalle .= "'" . $usuario_registro . "')";

if ($res_detalle = mysqli_query($enlace, $q_detalle)) {
			} else {
				$estado = 9;
			}
		}

		// 9. Registra UN SOLO correlativo de detalle POR MODALIDAD POR DESPACHO
		foreach ($detalles_por_modalidad as $mod => $info) {
			$q_corr_det = "INSERT INTO correlativo_despacho_detalle (id_programacion, id_planta, id_modalidadenvio, id_campana, correlativo, codigo, fechahora_registro, usuario_registro) VALUES (";
			$q_corr_det .= $id_programacion . ", ";
			$q_corr_det .= $id_planta . ", ";
			$q_corr_det .= $mod . ", ";
			$q_corr_det .= (($id_campana === null) ? 'NULL' : $id_campana) . ", ";
			$q_corr_det .= $info['correlativo'] . ", ";
			$q_corr_det .= "'" . $info['codigo'] . "', ";
			$q_corr_det .= "'" . $g_fecha . "', ";
			$q_corr_det .= "'" . $usuario_registro . "')";

			if (!mysqli_query($enlace, $q_corr_det)) {
				$estado = 8;
			}
		}

		echo json_encode(array(
			'estado' => $estado,
			'id_programacion' => $id_programacion,
			'cabecera' => $cabecera_global,
			'mensaje' => ($estado == 1) ? 'Programacion registrada correctamente.' : 'Hubo observaciones al registrar. Revise los codigos.'
		));

		break;

case 'confirmar_ProgramacionLote_AddLote':
		$estado = 0;

		// Recupera variables
		$id_planta = intval(mysqli_real_escape_string($enlace, $_POST["id_planta"]));
		$id_programacion = intval(mysqli_real_escape_string($enlace, $_POST["id_programacion"]));
		$arr_lotes = mysqli_real_escape_string($enlace, $_POST["arr_lotes"]);
		$is_loteaum = intval(mysqli_real_escape_string($enlace, $_POST["is_loteaum"]));
		$is_aplica_campana = isset($_POST["is_aplica_campana"]) ? intval($_POST["is_aplica_campana"]) : 0;
		$id_campana_input = isset($_POST["id_campana"]) ? intval($_POST["id_campana"]) : 0;
		$usuario_registro = $_SESSION["usu_usuario"];

		// Solo aplica a Colibri y Solandra
		if ($id_planta != 3 && $id_planta != 5) {
			echo json_encode(array('estado' => 0, 'mensaje' => 'La planta seleccionada no aplica para esta logica.'));

			return;
		}

		// ============================================================
		// LOGICA NUEVA: Agregar lote(s) a una programacion existente.
		// - Los lotes nuevos comparten cabecera GLOBAL del despacho (ya creada).
		// - Los lotes nuevos REUTILIZAN el codigo detalle existente por empresa;
		//   si la empresa es nueva, se genera UN codigo detalle para todos sus lotes.
		// ============================================================

		// 1. Obtener cabecera existente (id_campana)
		$id_campana_cabecera = null;

		$q_cabecera = "SELECT id_campana
												 FROM despachos_segundotramo_programacion
												WHERE Id = " . $id_programacion . "
													AND id_planta = " . $id_planta . "
												LIMIT 1";

		if ($res_cabecera = mysqli_query($enlace, $q_cabecera)) {
			if (mysqli_num_rows($res_cabecera) > 0) {
				while ($row_cabecera = mysqli_fetch_array($res_cabecera)) {
					$id_campana_cabecera = is_null($row_cabecera["id_campana"]) ? null : intval($row_cabecera["id_campana"]);
				}
			}
		}

		// Si la programacion no tiene campana y se esta intentando aplicar una
		// (caso raro pero soportado): respetar la campana del input.
		$is_campana_requerida = false;
		if ($id_planta == 5) {
			if (!is_null($id_campana_cabecera)) {
				// Campana de la programacion existente: ya esta aplicada
				$is_campana_requerida = true;
			} elseif ($is_aplica_campana == 1 && $id_campana_input > 0) {
				$id_campana_cabecera = $id_campana_input;
				$is_campana_requerida = true;
			}
			// Si la programacion no tiene campana y no se aplica una, queda sin campana
		}

		// 2. Obtener cabecera GLOBAL del despacho (es UNA SOLA para todas las modalidades)
		//    y codigos de detalle existentes por modalidad.
		$cabecera_global_existente = null;
		$detalles_existentes_por_modalidad = array(); // [id_modalidadenvio] => array('correlativo'=>N, 'codigo'=>'...')

		$q_cabeceras = "SELECT correlativo, codigo_programacion
											 FROM correlativo_despacho
											WHERE id_programacion = " . $id_programacion . "
												AND id_planta = " . $id_planta . "
											ORDER BY Id ASC
											LIMIT 1";

		if ($res_cabeceras = mysqli_query($enlace, $q_cabeceras)) {
			if ($row_cabeceras = mysqli_fetch_array($res_cabeceras)) {
				$cabecera_global_existente = array(
					'correlativo' => intval($row_cabeceras["correlativo"]),
					'codigo' => $row_cabeceras["codigo_programacion"]
				);
			}
		}

		$q_det = "SELECT id_modalidadenvio, MAX(correlativo) AS MAX_CORR
								FROM correlativo_despacho_detalle
							 WHERE id_programacion = " . $id_programacion . "
								 AND id_planta = " . $id_planta . "
						 GROUP BY id_modalidadenvio";

		if ($res_det = mysqli_query($enlace, $q_det)) {
			while ($row_det = mysqli_fetch_array($res_det)) {
				$mod_ex = intval($row_det["id_modalidadenvio"]);
				$detalles_existentes_por_modalidad[$mod_ex] = array(
					'correlativo' => intval($row_det["MAX_CORR"])
				);
			}
		}

		// Obtener el codigo detalle correspondiente al MAX correlativo por modalidad.
		// De esta forma, si en la BD existe data antigua con multiples codigos por modalidad,
		// usamos el del correlativo mas alto (que es el ultimo generado).
		foreach ($detalles_existentes_por_modalidad as $mod_ex => $info) {
			$q_det_cod = "SELECT codigo
										FROM correlativo_despacho_detalle
									 WHERE id_programacion = " . $id_programacion . "
										 AND id_planta = " . $id_planta . "
										 AND id_modalidadenvio = " . $mod_ex . "
										 AND correlativo = " . intval($info['correlativo']) . "
									 LIMIT 1";

			if ($res_det_cod = mysqli_query($enlace, $q_det_cod)) {
				if ($row_det_cod = mysqli_fetch_array($res_det_cod)) {
					$detalles_existentes_por_modalidad[$mod_ex]['codigo'] = $row_det_cod["codigo"];
				}
			}
		}

		// 3. Procesar cada lote nuevo
		$lotes_arr = explode('|', $arr_lotes);
		$estado = 1;
		$detalles_nuevos_por_modalidad = array(); // Para registrar UNA sola vez por modalidad nueva

		foreach ($lotes_arr as $cod_lote) {
			if (strlen(trim($cod_lote)) == 0) {
				continue;
			}

			// Obtener la modalidad del lote
			$modalidad_lote = 0;

			$q_mod = "SELECT despacho_id_modalidadenvio
								FROM despachos_primertramo_validaciondatos
						 WHERE lote_cod_lote = '" . $cod_lote . "'";

			if ($res_mod = mysqli_query($enlace, $q_mod)) {
				if (mysqli_num_rows($res_mod) > 0) {
					while ($row_mod = mysqli_fetch_array($res_mod)) {
						$modalidad_lote = intval($row_mod["despacho_id_modalidadenvio"]);
					}
				}
			}

			$codigo_cabecera_lote = NULL;
			$codigo_detalle_lote = NULL;

			if ($modalidad_lote == 5 || $modalidad_lote == 6) {
				// Cabecera GLOBAL del despacho: si ya existe se reutiliza; si no, se genera UNA.
				if (!is_null($cabecera_global_existente)) {
					$codigo_cabecera_lote = $cabecera_global_existente['codigo'];
				} else {
					// Generar nueva cabecera GLOBAL del despacho
					$campana = ($id_planta == 5 && !is_null($id_campana_cabecera)) ? array('codigo_campana' => null) : null;
					if ($id_planta == 5 && !is_null($id_campana_cabecera)) {
						$q_c = "SELECT codigo_campana FROM tbconfig_plantas_campanas WHERE Id = " . intval($id_campana_cabecera) . " LIMIT 1";
						$res_c = mysqli_query($enlace, $q_c);
						if ($res_c && $row_c = mysqli_fetch_assoc($res_c)) {
							$campana['codigo_campana'] = $row_c['codigo_campana'];
						}
					}
					$codigo_campana = is_null($campana) ? null : $campana['codigo_campana'];

					$cab = f_CalcularSiguienteCorrelativoDespacho($enlace, $id_planta, $modalidad_lote, 'CAB', $id_campana_cabecera, $is_campana_requerida);

					if (!is_null($cab['error'])) {
						echo json_encode(array('estado' => 5, 'mensaje' => $cab['error']));
						return;
					}

					$codigo_cabecera_lote = f_ConstruirCodigoCabecera($id_planta, $codigo_campana, $cab['correlativo']);

					// Insertar nueva cabecera GLOBAL (id_modalidadenvio = NULL)
					$q_new_cab = "INSERT INTO correlativo_despacho (id_programacion, id_planta, id_modalidadenvio, id_campana, correlativo, codigo_programacion, fechahora_registro, usuario_registro) VALUES (";
					$q_new_cab .= $id_programacion . ", ";
					$q_new_cab .= $id_planta . ", ";
					$q_new_cab .= "NULL, ";
					$q_new_cab .= (($id_campana_cabecera === null) ? 'NULL' : $id_campana_cabecera) . ", ";
					$q_new_cab .= $cab['correlativo'] . ", ";
					$q_new_cab .= "'" . $codigo_cabecera_lote . "', ";
					$q_new_cab .= "'" . $g_fecha . "', ";
					$q_new_cab .= "'" . $usuario_registro . "')";
					mysqli_query($enlace, $q_new_cab);

					$cabecera_global_existente = array(
						'correlativo' => $cab['correlativo'],
						'codigo' => $codigo_cabecera_lote
					);
				}

				// Detalle: REUTILIZAR el codigo existente si la modalidad ya esta en este despacho;
				// si es nueva, generar UN solo codigo detalle para todos los lotes de esa modalidad.
				if (isset($detalles_existentes_por_modalidad[$modalidad_lote]) && isset($detalles_existentes_por_modalidad[$modalidad_lote]['codigo'])) {
					// Reutilizar codigo existente
					$codigo_detalle_lote = $detalles_existentes_por_modalidad[$modalidad_lote]['codigo'];
				} else {
					// Generar nuevo codigo detalle (solo una vez por modalidad nueva)
					if (!isset($detalles_nuevos_por_modalidad[$modalidad_lote])) {
						$det = f_CalcularSiguienteCorrelativoDespacho($enlace, $id_planta, $modalidad_lote, 'DET', $id_campana_cabecera, $is_campana_requerida);

						if (!is_null($det['error'])) {
							echo json_encode(array('estado' => 5, 'mensaje' => $det['error']));
							return;
						}

						$prefijo_empresa = f_GetPrefijoEmpresaDespacho($modalidad_lote);
						$codigo_detalle_nuevo = f_ConstruirCodigoDetalle($codigo_cabecera_lote, $prefijo_empresa, intval($det['correlativo']));

						$detalles_nuevos_por_modalidad[$modalidad_lote] = array(
							'correlativo' => intval($det['correlativo']),
							'codigo' => $codigo_detalle_nuevo
						);

						// Actualizar el listado de existentes para los siguientes lotes del mismo despacho
						$detalles_existentes_por_modalidad[$modalidad_lote] = array(
							'correlativo' => intval($det['correlativo']),
							'codigo' => $codigo_detalle_nuevo
						);
					}

					$codigo_detalle_lote = $detalles_nuevos_por_modalidad[$modalidad_lote]['codigo'];
				}
			}

			// Insertar detalle
			$q_detalle = "INSERT INTO despachos_segundotramo_programacion_detalle (id_programacion, cod_lote, id_planta,
																				id_modalidadenvio, codigo_despacho, codigo_despacho_comercializacion,
																				codigo_planta, TMH, fechahora_registro, usuario_registro) VALUES (";
			$q_detalle .= $id_programacion . ", ";
			$q_detalle .= "'" . $cod_lote . "', ";
			$q_detalle .= $id_planta . ", ";
			$q_detalle .= $modalidad_lote . ", ";
			$q_detalle .= (($codigo_cabecera_lote === null) ? 'NULL' : "'" . $codigo_cabecera_lote . "'") . ", ";
			$q_detalle .= (($codigo_detalle_lote === null) ? 'NULL' : "'" . $codigo_detalle_lote . "'") . ", ";
			$q_detalle .= "NULL, ";
			$q_detalle .= "(SELECT SUM(lote_peso_neto) AS NETO_TMH
													 FROM despachos_primertramo_validaciondatos
											  WHERE lote_cod_lote = '" . $cod_lote . "'), ";
			$q_detalle .= "'" . $g_fecha . "', ";
			$q_detalle .= "'" . $usuario_registro . "')";

			if (!$res_detalle = mysqli_query($enlace, $q_detalle)) {
				$estado = 4;
			}
		}

		// 4. Inserta UN SOLO correlativo de detalle POR CADA modalidad nueva del despacho
		foreach ($detalles_nuevos_por_modalidad as $mod => $info) {
			$q_corr_det = "INSERT INTO correlativo_despacho_detalle (id_programacion, id_planta, id_modalidadenvio, id_campana, correlativo, codigo, fechahora_registro, usuario_registro) VALUES (";
			$q_corr_det .= $id_programacion . ", ";
			$q_corr_det .= $id_planta . ", ";
			$q_corr_det .= $mod . ", ";
			$q_corr_det .= (($id_campana_cabecera === null || $id_campana_cabecera === 0) ? 'NULL' : $id_campana_cabecera) . ", ";
			$q_corr_det .= $info['correlativo'] . ", ";
			$q_corr_det .= "'" . $info['codigo'] . "', ";
			$q_corr_det .= "'" . $g_fecha . "', ";
			$q_corr_det .= "'" . $usuario_registro . "')";

			if (!mysqli_query($enlace, $q_corr_det)) {
				$estado = 3;
			}
		}

		echo json_encode(array(
			'estado' => $estado,
			'mensaje' => ($estado == 1) ? 'Lotes agregados correctamente.' : 'Hubo observaciones al agregar los lotes.'
		));

		break;

	// ====================================================================
	// GESTIÓN DE CAMPAÑAS (Solandra)
	// ====================================================================
	case 'get_CampanaActivaPlanta':
		$estado = 0;
		$id_planta = intval($_POST["id_planta"]);

		$campana = f_GetCampanaActiva($enlace, $id_planta);

		if (!is_null($campana['id_campana'])) {
			$estado = 1;
		}

		echo json_encode(array(
			'estado' => $estado,
			'id_campana' => $campana['id_campana'],
			'codigo_campana' => $campana['codigo_campana'],
			'fecha_inicio' => $campana['fecha_inicio']
		));

		break;

	case 'get_ListadoCampanasPlanta':
		$estado = 0;
		$id_planta = intval($_POST["id_planta"]);
		$res = array();

		$q = "SELECT Id,
										 id_planta,
										 codigo_campana,
										 fecha_inicio,
										 fecha_fin,
										 estado,
										 fechahora_registro,
										 usuario_registro
							FROM tbconfig_plantas_campanas
						 WHERE id_planta = " . $id_planta . "
						 ORDER BY Id DESC";

		if ($res_q = mysqli_query($enlace, $q)) {
			if (mysqli_num_rows($res_q) > 0) {
				$estado = 1;

				while ($row = mysqli_fetch_array($res_q)) {
					array_push($res, $row);
				}
			}
		}

		echo json_encode(array('estado' => $estado, 'res' => $res));

		break;

	case 'get_ListadoCampanasActivasPlanta':
		// Devuelve SOLO las campanas ACTIVAS (estado='A' y sin fecha_fin)
		$estado = 0;
		$id_planta = intval($_POST["id_planta"]);
		$res = array();

		$q = "SELECT Id,
										 id_planta,
										 codigo_campana,
										 fecha_inicio,
										 estado,
										 fechahora_registro,
										 usuario_registro
							FROM tbconfig_plantas_campanas
						 WHERE id_planta = " . $id_planta . "
							 AND estado = 'A'
							 AND fecha_fin IS NULL
						 ORDER BY Id DESC";

		if ($res_q = mysqli_query($enlace, $q)) {
			if (mysqli_num_rows($res_q) > 0) {
				$estado = 1;

				while ($row = mysqli_fetch_array($res_q)) {
					array_push($res, $row);
				}
			}
		}

		echo json_encode(array('estado' => $estado, 'res' => $res));

		break;

	case 'grabar_CampanaPlanta':
		$estado = 0;
		$id_planta = intval($_POST["id_planta"]);
		$codigo_campana = strtoupper(trim(mysqli_real_escape_string($enlace, $_POST["codigo_campana"])));
		$usuario_registro = $_SESSION["usu_usuario"];

		// 1. Validar que el código de campaña no exista ya
		$q_exists = "SELECT COUNT(Id) AS _EXISTS
								 FROM tbconfig_plantas_campanas
								WHERE id_planta = " . $id_planta . "
									AND codigo_campana = '" . $codigo_campana . "'";

		if ($res_exists = mysqli_query($enlace, $q_exists)) {
			if (mysqli_num_rows($res_exists) > 0) {
				while ($row_exists = mysqli_fetch_array($res_exists)) {
					if ($row_exists["_EXISTS"] > 0) {
						echo json_encode(array(
							'estado' => 2,
							'mensaje' => 'El codigo de campana "' . $codigo_campana . '" ya existe para esta planta.'
						));
						return;
					}
				}
			}
		}

		// 2. Inactivar la campaña activa actual (si existe) y guardar fecha_fin
		$q_inactivar = "UPDATE tbconfig_plantas_campanas
										SET estado = 'I',
												fecha_fin = NOW()
									WHERE id_planta = " . $id_planta . "
										AND estado = 'A'
										AND fecha_fin IS NULL";

		mysqli_query($enlace, $q_inactivar);

		// 3. Insertar la nueva campaña activa
		$q_insert = "INSERT INTO tbconfig_plantas_campanas (id_planta, codigo_campana, fecha_inicio, estado, fechahora_registro, usuario_registro)
								 VALUES (
									" . $id_planta . ",
									'" . $codigo_campana . "',
									NOW(),
									'A',
									NOW(),
									'" . $usuario_registro . "')";

		if ($res_insert = mysqli_query($enlace, $q_insert)) {
			$estado = 1;
		}

		echo json_encode(array(
			'estado' => $estado,
			'mensaje' => ($estado == 1) ? 'Campana registrada correctamente.' : 'Error al registrar la campana.'
		));

		break;


	case 'eliminar_Lote':
		$estado = 0;

		// Recupera variables
		$id_lote = $_POST["id_lote"];
		$usuario_registro = $_SESSION["usu_usuario"];

		// Guarda Log del registro original
		$q_log = "
		INSERT INTO catalogolotes_deletelog(
			id_CatalogoLotes,
			nNro_ticketsBalanza,
			item_ticketbalanza,
			id_TramoPesaje,
			dFechaBalanza,
			ccod_Lote,
			dFechaIngreso,
			tHora_Ingreso,
			tFechaInicialBalanza,
			tHoraInicialBalanza,
			nPeso_InicialBalanza,
			pesoinicial_observacion,
			dFechaFinalBalanza,
			tHoraFinalBalanza,
			nPeso_FinalBalanza,
			pesofinal_observacion,
			nPesoBalanza,
			nPorcentajeHumedad,
			nPesoHumedad,
			nPesoSeco,
			nPesoEnviado,
			nPesoPendienteEnvio,
			id_TipoMaterial,
			id_OrigenCarga,
			id_PlantaDestino,
			id_PresentacionMaterial,
			id_Encargado,
			id_cliente,
			id_transporte,
			bTramo1,
			bTramo2,
			bSolicitudDocumentacion,
			bRecepciondocumentacion,
			bEnvioDocumentacion,
			id_EstadoLoteDespacho,
			bLiberacionLoteCliente,
			tNotasBalanza,
			tNotasGerencia,
			tNotasDespacho,
			id_ModalidadEnvio,
			cEstado_Registro,
			id_ModalidadGuiasDestino,
			id_EstadoLoteComercializacion,
			id_controlIngresoVehiculo,
			cCodSecuenciaLote,
			nPesoBrutoBalanza,
			nPesoTaraBalanza,
			nPesoNetoBalanza,
			id_UsuarioCreacion,
			dFechaCreacion,
			id_UsuarioModificacion,
			dFechaModificacion,
			id_choferes,
			placa,
			cEliminado,
			bDocumentosValidados,
			balanza_id_tipocarga,
			balanza_id_zonaorigen,
			balanza_id_proveedorminero,
			balanza_id_encargadomuestra,
			balanza_id_producto,
			balanza_id_tipomineral,
			balanza_observacion,
			balanza_id_planta,
			tObservacion_T1,
			preparacion_fechahoraregistro,
			preparacion_usuarioregistro,
			humedad_pesohumedad,
			humedad_pesohumedad_fechahoraregistro,
			humedad_pesohumedad_usuarioregistro,
			is_copiacomercializacion,
			is_loteaum,
			is_cierregestionlote,
			is_cierregestionlote_fechahoraregistro,
			is_cierregestionlote_usuarioregistro,
			serie_guia_remitente,
			numero_guia_remitente,
			serie_guia_transportista,
			numero_guia_transportista,
			fechahora_log,
			usuario_log
		)
		";
		$q_log .= "SELECT *, ";
		$q_log .= "'" . $g_fecha . "', ";
		$q_log .= "'" . $usuario_registro . "'";
		$q_log .= "  FROM catalogolotes";
		$q_log .= " WHERE id_CatalogoLotes = " . $id_lote;

		saveLog(['$q_log' => $q_log]);
		if ($res_log = mysqli_query($enlace, $q_log)) {
			// Recalculando el Ticket de Balanza
			if (f_RecalcularTicketsBalanza($enlace, $id_lote)) {
				// Elimina el registro
				$q_delete = "DELETE FROM catalogolotes";
				$q_delete .= " WHERE id_CatalogoLotes = " . $id_lote;

				if ($res_delete = mysqli_query($enlace, $q_delete)) {
					$estado = 1;
				}

				// // Elimina Ticket de Balanza
				// 	$q_delete = "DELETE FROM correlativo_ticketsbalanza";
				// 	$q_delete .= " WHERE id_lote = ".$id_lote;

