		if ($item == 3) {
			$campo = 'I.placa2';
		}

		if ($item == 4) {
			$campo = 'I.id_transportista';
		}

		if ($item == 5) {
			$campo = 'I.id_tipovehiculo';
		}

		if ($item == 6) {
			$campo = 'I.id_choferes';
		}

		if ($item == 7) {
			$campo = 'L.balanza_id_tipocarga';

			$is_tablalotes = 1;
		}

		if ($item == 8) {
			$campo = 'L.balanza_id_zonaorigen';

			$is_tablalotes = 1;
		}

		if ($item == 9) {
			$campo = 'L.balanza_id_proveedorminero';

			$is_tablalotes = 1;
		}

		if ($item == 10) {
			$campo = 'L.balanza_id_encargadomuestra';

			$is_tablalotes = 1;
		}

		if ($item == 11) {
			$campo = 'L.balanza_id_producto';

			$is_tablalotes = 1;
		}

		if ($item == 12) {
			$campo = 'L.balanza_id_tipomineral';

			$is_tablalotes = 1;
		}

		if ($item == 13) {
			$campo = 'L.nPeso_InicialBalanza';

			$is_tablalotes = 1;
		}

		if ($item == 14) {
			$campo = 'L.nPeso_FinalBalanza';

			$is_tablalotes = 1;
		}

		if ($item == 15) {
			$campo = 'L.balanza_observacion';

			$is_tablalotes = 1;

			if ($tipo_condicion == 2) {
				$campo = 'observacion';

				$is_tabladistribucionlotes = 1;
