				$q_update .= "id_tipovehiculo = " . $valor;
				$q_update .= " WHERE cplaca IN (SELECT placa
																						 FROM controlingresovehiculo
																						WHERE id_controlIngresoVehiculo = " . $id_registro . ")";

				if ($res_update = mysqli_query($enlace, $q_update)) {
				}
			}

