						$html .= '      <input id="cmh_codigoguias_' . $row_datos["ID_DETALLE"] . '" type="text" class="form-control col-md-12 col-xs-12" style="text-align: center; font-size: 13px; font-weight: bold; text-transform: uppercase;" onblur="f_GrabarCodigosCMH(' . $row_datos["ID_DETALLE"] . ', 2);" value="' . $row_datos["CMH_CODIGOSGUIAS"] . '">';
						$html .= '  </td>';
