					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; background-color: #ffffff; font-weight: bold;">';
					$html .= '    ' . $row_datos["codigo_despacho"];
					$html .= '    <input id="td_programacionloteaum_' . $d . '" type="hidden" value="' . $is_loteaum . '">';
					$html .= '  </td>';

					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; background-color: #ffffff; font-weight: bold;" ' . (($id_planta != 3) ? '' : '') . '>';
					$html .= '    ' . $row_datos["codigo_despacho_comercializacion"];
					$html .= '  </td>';

					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; background-color: #ffffff; font-weight: bold;" ' . (($id_planta != 3) ? 'hidden' : '') . '>';
					$html .= '		<div id="trdiv_CodigoPlanta_' . $row_datos["ID_DETALLE"] . '" class="col-md-12 col-sm-12 col-xs-12">';
					$html .= '    	' . $row_datos["CODIGO_PLANTA"];

					if ($id_planta == 3) {
						$html .= '    	<i class="bi bi-pencil-square" style="cursor: pointer;" onclick="f_EditCodigoPlanta(' . $row_datos["ID_DETALLE"] . ", '" . $row_datos["cod_lote"] . "', '" . $row_datos["CODIGO_PLANTA"] . "'" . ')"></i>';
					}

					$html .= '		</div>';
					$html .= '  </td>';

					// Total Distribuído
					$total_distribuido = $row_datos["TOTAL_DISTRIBUIDO"];
					$total_distribuido = ((strlen($total_distribuido) == 0) ? 0 : $total_distribuido);

					$html .= '  <td id="td_lotetmh_' . $d . '" class="tmh_primertramo_' . $p . '" style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; background-color: #ffffff; font-weight: bold;">';

					// Total TMH
					$total_tmh = $row_datos["TOTAL_TMH"];

					// if ($is_loteaum == 1){
					// 	$total_tmh = $total_distribuido * 1000;
					// }

					$html .= '    ' . number_format($total_tmh / 1000, 3, '.', ',');
					$html .= '  </td>';

					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; font-weight: bold;">';

					// Obtiene Peso Seco
					$peso_seco = f_GetPesoSeco($total_tmh, $row_datos["HUMEDAD"]);

					if (strlen($peso_seco) > 0) {
						$html .= '    ' . number_format(($peso_seco / 1000), 3, '.', ',');
					} else {
						$html .= '		<label style="font-size: 13px; color: #FF5F5D;">';
						$html .= '			<i>Humedad Pendiente</i>';
						$html .= '		</label>';
					}

					$html .= '  </td>';

					// Evaluando distribución
					$bg_color = '';

					if (number_format(($total_tmh / 1000), 3, '.', '') == number_format($total_distribuido, 3, '.', '')) {
						$bg_color = '#B6F279';
					}

					$html .= '  <td id="td_pesodistribuido_' . $d . '" class="tmh_distribuidoprograma_' . $p . '" style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; background-color: ' . $bg_color . '; font-weight: bold;">';

					$html .= '    ' . number_format($total_distribuido, 3, '.', ',');

					$html .= '  </td>';

					if ($id_prog != $row_datos["Id"]) {
						$html .= '  <td id="td_cierreprograma_1_' . $p . '" rowspan="' . $row_datos["TOTAL_LOTES"] . '" style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; background-color: #ffffff; text-align: center; font-size: 13px;">';

						if ($row_datos["is_cerrado"] == 0) {
							$html .= '    <button class="btn btn-primary" type="button" onclick="f_LoadItemProgramacion(' . $x . ', ' . $row_datos["Id"] . ', 1, ' . $p . ');" style="font-size: 13px;">';
							$html .= '			<b>Cerrar</b>';
							$html .= '    </button>';
						} else {
							$html .= '		<label style="font-style: italic; color: #F23030; cursor: pointer;" onclick="f_Reabrir(' . $row_datos["Id"] . ', ' . $p . ')">';
							$html .= '			<u> Reabrir </u>';
							$html .= '		</label>';
						}

						$html .= '  </td>';

						$html .= '  <td id="td_cierreprograma_2_' . $p . '" rowspan="' . $row_datos["TOTAL_LOTES"] . '" style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; background-color: #ffffff; text-align: center; font-weight: bold;">';
						$html .= '    ' . $row_datos["fechaestimada_despacho"];
						$html .= '  </td>';

						$html .= '  <td id="td_cierreprograma_3_' . $p . '" rowspan="' . $row_datos["TOTAL_LOTES"] . '" style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; background-color: #ffffff; text-align: center;">';
						$html .= '    ' . $row_datos["cerrado_fechahoraregistro"];
						$html .= '  </td>';

						$html .= '  <td id="td_cierreprograma_4_' . $p . '" rowspan="' . $row_datos["TOTAL_LOTES"] . '" style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; background-color: #ffffff; text-align: center;">';
						$html .= '    ' . $row_datos["cerrado_usuarioregistro"];
						$html .= '  </td>';

						$x++;
					}

					$html .= '</tr>';

					$id_prog = $row_datos["Id"];

					$d++;
				}
			}
		}

		echo json_encode(array('estado' => $estado, 'html' => $html, 'id_programacion' => $id_programacion));

		break;

	case 'eliminar_Programacion':
		$estado = 0;

		// Recupera variables
		$id_programacion = $_POST["id_programacion"];
		$usuario_registro = $_SESSION["usu_usuario"];

		// Guarda el Log de la Programación
		$q_log = "INSERT INTO despachos_segundotramo_programacion_log (Id, id_planta, fechahora_registro, usuario_registro, is_cerrado, cerrado_fechahoraregistro, cerrado_usuarioregistro, fechahora_log, usuario_log) ";
		$q_log .= "SELECT Id,
													id_planta,
													fechahora_registro,
													usuario_registro,
													is_cerrado,
													cerrado_fechahoraregistro,
													cerrado_usuarioregistro,
													'" . $g_fecha . "',
													'" . $usuario_registro . "'
										 FROM despachos_segundotramo_programacion
										WHERE Id = " . $id_programacion;

		if ($res_log = mysqli_query($enlace, $q_log)) {
			// Obtiene la información de los lotes asignados a la programación
			$q_datos = "SELECT Id
													FROM despachos_segundotramo_programacion_detalle
												 WHERE id_programacion = " . $id_programacion;

			if ($res_datos = mysqli_query($enlace, $q_datos)) {
				if (mysqli_num_rows($res_datos) > 0) {
					while ($row_datos = mysqli_fetch_array($res_datos)) {
						// Eliminando registro
						f_Eliminar_DespachoSegundoTramo_ProgramacionLote($enlace, $row_datos["Id"], $g_fecha, $usuario_registro);
					}

					// Eliminar registro de Programación
					$q_delete = "DELETE FROM despachos_segundotramo_programacion
																WHERE Id = " . $id_programacion;

					if ($res_delete = mysqli_query($enlace, $q_delete)) {
						$estado = 1;
					}
				}
			}
		}

		echo json_encode(array('estado' => $estado));

		break;

	case 'eliminar_ProgramacionLote':
		$estado = 0;

		// Recupera variables
		$id_programacionlote = $_POST["id_programacionlote"];
		$usuario_registro = $_SESSION["usu_usuario"];

		// Eliminando registro
		$estado = f_Eliminar_DespachoSegundoTramo_ProgramacionLote($enlace, $id_programacionlote, $g_fecha, $usuario_registro);

		echo json_encode(array('estado' => $estado));

		break;

	case 'get_LotesProgramadosParaDespacho_Distribucion':
		$estado = 0;

		$d = 1;
		$html = '';

		// Recupera parámetros
		$id_programacion = trim(mysqli_real_escape_string($enlace, $_POST['id_programacion']));
		$id_planta = trim(mysqli_real_escape_string($enlace, $_POST['id_planta']));

		// Obtiene la información de cada lote de la programación
		$cod_lote = '';
		$tmh = 0;
		$proveedor_minero = '';
		$modalidad_envio = '';
		$is_loteaum = 0;

		$q_datos = "SELECT DISTINCT PD.cod_lote,
													 
													 CASE WHEN CL.is_loteaum = 1
														 THEN V.despacho_loteaum_pesoestimado
													 ELSE PD.TMH END AS TMH,

													 IFNULL(PM.razon_social, '---') AS PROVEEDOR_MINERO,
													 IFNULL(ME.descripcion, '---') AS MODALIDAD_ENVIO,
													 CL.is_loteaum
											FROM despachos_segundotramo_programacion_detalle PD
													 INNER JOIN despachos_primertramo_validaciondatos V ON PD.cod_lote = V.lote_cod_lote
													 LEFT JOIN tb_clientes PM ON V.lote_id_proveedorminero = PM.Id
													 " . (($id_planta == 16) ? 'LEFT' : 'INNER') . " JOIN tbconfig_modalidadenvio ME ON V.despacho_id_modalidadenvio = ME.Id
													 INNER JOIN catalogolotes CL ON CL.ccod_Lote = PD.cod_lote
										 WHERE PD.id_programacion = " . $id_programacion . "
										ORDER BY PD.cod_lote";

		if ($res_datos = mysqli_query($enlace, $q_datos)) {
			if (mysqli_num_rows($res_datos) > 0) {
				while ($row_datos = mysqli_fetch_array($res_datos)) {
					// Obteniendo el Código del Lote y TMH
					$cod_lote = $row_datos["cod_lote"];
					$tmh = number_format(($row_datos["TMH"] / 1000), 3, '.', ',');

					$proveedor_minero = $row_datos["PROVEEDOR_MINERO"];
					$modalidad_envio = $row_datos["MODALIDAD_ENVIO"];
					$is_loteaum = $row_datos["is_loteaum"];

					// Obteniendo las toneladas distribuidas del lotes, si es que las tuviera
					$tmh_distribuido = 0;

					$q_distribuido = "SELECT IFNULL(SUM(peso_distribuido), 0) AS DISTRIBUIDO
																		FROM despachos_segundotramo_distribucion_lotes
																	 WHERE cod_lote = '" . $cod_lote . "'";

					if ($res_distribuido = mysqli_query($enlace, $q_distribuido)) {
						if (mysqli_num_rows($res_distribuido) > 0) {
							while ($row_distribuido = mysqli_fetch_array($res_distribuido)) {
								$tmh_distribuido = $row_distribuido["DISTRIBUIDO"];
							}
						}
					}

					// Verifica si es Lote Aum y tiene distribuciones
					$is_loteaum_x = $is_loteaum;

					if ($is_loteaum == 1) {
						$q_distribuciones = "SELECT COUNT(Id) AS _COUNT
																				 FROM despachos_segundotramo_distribucion_lotes
																				WHERE cod_lote = '" . $cod_lote . "'";

						if ($res_distribuciones = mysqli_query($enlace, $q_distribuciones)) {
							if (mysqli_num_rows($res_distribuciones) > 0) {
								while ($row_distribuciones = mysqli_fetch_array($res_distribuciones)) {
									if ($row_distribuciones["_COUNT"] > 0) {
										$is_loteaum_x = 0;
									}
								}
							}
						}
					}

					// Solo se deben listar los lotes con diferencia enter TMH y TMH Distribuído
					$por_distribuir = number_format($tmh, 3, '.', '') - number_format($tmh_distribuido, 3, '.', '');

					if ($por_distribuir > 0 || $is_loteaum_x == 1) {
						$estado = 1;

						$html .= '<tr id="tr_distribucion_' . $d . '" style="cursor: pointer; font-size: 14px; max-height: 25px;">';
						$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';
						$html .= '    ' . $d;
						$html .= '		<input id="chk_lotedistribucion_' . $d . '" class="form-check-input chk_cierre" type="checkbox" style="transform: scale(1.2);" onchange="f_CountSelected_Distribucion();">';
						$html .= '    <input id="td_loteaum_' . $d . '" type="hidden" value="' . $is_loteaum . '">';
						$html .= '  </td>';

						$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; font-weight: bold;">';
						$html .= '     <label id="lote_distribucion_' . $d . '">' . $cod_lote . '</label>';

						if ($is_loteaum == 1) {
							$html .= '    <label style="text-align: center; font-size: 10px; text-shadow: 2px 2px 2px #F2CB05;"><i>Lote AUM</i></label>';
						}
						$html .= '  </td>';

						$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';
						$html .= '    ' . $proveedor_minero;
						$html .= '  </td>';

						$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';
						$html .= '    ' . $modalidad_envio;
						$html .= '  </td>';

						$html .= '  <td id="por_distribuir_' . $d . '" style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';
						$html .= '    ' . $por_distribuir;
						$html .= '  </td>';

						$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';
						$html .= '		<input id="tmh_distribuido_' . $d . '" type="number" class="form-control col-md-12 col-xs-12" style="text-align: center; font-size: 13px; font-weight: bold;" onkeyup="f_CountSelected_Distribucion();" value="' . $por_distribuir . '">';
						$html .= '  </td>';

						$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';
						$html .= '  	<div class="d-flex justify-content-center">';

						// Comprobando si puede ser complemento. "Complemento" pueden ser solo los Lotes que ya existen al menos en una unidad.
						$c = 1;
						$exists = 0;
						$num_parte = 0;
						$html_x = '';

						$q_exists = "SELECT Id,
																				num_parte
																	 FROM despachos_segundotramo_distribucion_lotes
																	WHERE cod_lote = '" . $cod_lote . "'
																		AND is_complemento = 0";

						if ($res_exists = mysqli_query($enlace, $q_exists)) {
							if (mysqli_num_rows($res_exists) > 0) {
								$exists = 1;

								while ($row_exists = mysqli_fetch_array($res_exists)) {
									$num_parte = $row_exists["num_parte"];

									$html_x .= '<option value="' . $row_exists["Id"] . '" ' . (($c == 1) ? 'selected' : '') . '>PARTE ' . $row_exists["num_parte"] . '</option>';

									$c++;
								}
							}
						}

						$html .= '			<input id="chk_lotecomplemento_' . $d . '" class="form-check-input chk_cierre" type="checkbox" style="transform: scale(1.2); display: ' . (($exists == 0) ? 'none' : 'block') . '">';

						$html .= '  	</div>';
						$html .= '  </td>';

						$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; min-width: 120px;">';
						$html .= '  	<div class="d-flex justify-content-center">';
						$html .= '			<select id="sel_complemento_' . $d . '" class="form-select" style="text-align: left; font-size: 14px; display: ' . (($exists == 0) ? 'none' : 'block') . '">';

						if ($exists == 1) {
							$html .= $html_x;
						}

						$html .= '  		</select>';
						$html .= '  	</div>';
						$html .= '  </td>';

						$html .= '</tr>';

						$d++;
					}
				}
			}
		}

		echo json_encode(array('estado' => $estado, 'html' => $html));

		break;

	case 'confirmar_DistribucionLotes':
		$estado = 0;

		// Recupera variables
		$id_programacion = $_POST["id_programacion"];
		$tipo_unidad = explode('|', $_POST["tipo_unidad"])[0];
		$id_unidad = $_POST["id_unidad"];
		$id_unidad2 = $_POST["id_unidad2"];
		$capacidad = $_POST["capacidad"];
		$script_x = $_POST["script_x"];
		$usuario_registro = $_SESSION["usu_usuario"];

		// Graba la Unidad
		$id_distribucionunidad = 0;

		$q_insert = "INSERT INTO despachos_segundotramo_distribucion_unidades (id_programacion, id_tipovehiculo, id_unidad, id_unidad2, capacidad_unidad, fechahora_registro, usuario_registro) VALUES (";
		$q_insert .= $id_programacion . ', ';
		$q_insert .= $tipo_unidad . ', ';
		$q_insert .= ((strlen(trim($id_unidad)) == 0) ? 'NULL' : trim($id_unidad)) . ', ';
		$q_insert .= ((strlen(trim($id_unidad2)) == 0) ? 'NULL' : trim($id_unidad2)) . ', ';
		$q_insert .= $capacidad . ', ';
		$q_insert .= "'" . $g_fecha . "', ";
		$q_insert .= "'" . $usuario_registro . "')";

		if ($res_insert = mysqli_query($enlace, $q_insert)) {
			$estado = 1;

			$id_distribucionunidad = mysqli_insert_id($enlace);
		}

		// Arma cadena de Grabar según Script
		$arr_script = explode('|', $script_x);

		// Recorre Array de Lotes y arma la cadena final de grabación
		$s = 0;

		while ($s < count($arr_script)) {
			// Inicia Insert
			$q_insert = 'INSERT INTO despachos_segundotramo_distribucion_lotes (id_distribucionunidad, cod_lote, num_parte, peso_distribuido, color_lote, color_lote_fechahoraregistro, color_lote_usuarioregistro, is_complemento, is_complemento_de, fechahora_registro, usuario_registro) VALUES ';

			// Verificando si el Lote tiene particiones previamente registradas, "solo para los No Complementos".
			$num_parte = 'NULL';

			if (explode(';', $arr_script[$s])[4] == 0) {
				if (explode(';', $arr_script[$s])[2] == 0) {
					$q_count = "SELECT COUNT(Id) + 1 AS _COUNT
															FROM despachos_segundotramo_distribucion_lotes
														 WHERE cod_lote = '" . explode(';', $arr_script[$s])[0] . "'
															 AND is_complemento = 0";

					if ($res_count = mysqli_query($enlace, $q_count)) {
						if (mysqli_num_rows($res_count) > 0) {
							while ($row_count = mysqli_fetch_array($res_count)) {
								$num_parte = $row_count["_COUNT"];
							}
						}
					}
				} else {
					// Si está completo, igual verifica si tiene distribuciones anteriores para asignarle el correlativo final
					$q_count = "SELECT COUNT(Id) AS _COUNT
																FROM despachos_segundotramo_distribucion_lotes
															 WHERE cod_lote = '" . explode(';', $arr_script[$s])[0] . "'
																 AND is_complemento = 0";

					if ($res_count = mysqli_query($enlace, $q_count)) {
						if (mysqli_num_rows($res_count) > 0) {
							while ($row_count = mysqli_fetch_array($res_count)) {
								if ($row_count["_COUNT"] == 0) {
									$num_parte = 'NULL';
								} else {
									$num_parte = $row_count["_COUNT"] + 1;
								}
							}
						}
					}
				}
			}

			// Si es Complemento
			$is_complemento = explode(';', $arr_script[$s])[4];
			$is_complemento_de = explode(';', $arr_script[$s])[5];

			// Verifica si es Lote AUM
			// if (explode(';', $arr_script[$s])[3] == 1){
			// 	$num_parte = 'NULL';
			// }

			// Comprueba si hay otros lotes con Color asignado
			$bg_color = 'NULL';
			$bg_color_fechahoraregistro = 'NULL';
			$bg_color_usuarioregistro = 'NULL';

			$q_color = "SELECT color_lote,
															 color_lote_fechahoraregistro,
