													 VD.lote_id_proveedorminero,
													 PM.documento AS PROVEEDORMINERO_RUC,
													 PM.razon_social AS PROVEEDORMINERO_RAZONSOCIAL,
													 EM.nombres AS ENCARGADO_MUESTRA,
													 DL.peso_distribuido,
													 DL.id_tipocarga,
													 DU.fecha_ingresoplanta,
													 DU.hora_ingresoplanta,
													 IFNULL(DL.color_lote, '') AS COLOR_LOTE,
													 P.is_cerrado,
													 PD.codigo_planta,
													 DL.is_complemento,
													 DL.is_complemento_de,
													 DU.id_coordinadortransporte,
													 PD.codigo_despacho,
													 P.id_planta,
													 RE.ruc AS REMITENTE_RUC,
													 DU.configuracionvehicular_pesobrutomaximo,
													 DU.configuracionvehicular_pesobrutomaximo2,
													 DU.configuracionvehicular_pesobrutototaltransportado,
													 CV.tiene_ingresomanual,

