															 L.num_parte,
															 L.peso_distribuido,
															 L.id_tipocarga,
															 TC.descripcion AS TIPO_CARGA,
															 L.num_bigbag,
															 L.peso_tara,
															 L.peso_bruto,
															 L.peso_neto,
															 L.observacion,
															 U.balanza_cerrado,
															 U.balanza_cerrado_fechahoraregistro,
															 U.balanza_cerrado_usuarioregistro,
															 I.id_tipoingresounidad,
															 P.fechaestimada_despacho,
															 CL.is_loteaum,
															 PL.nombre_comercial AS DESTINO,

															 (SELECT COUNT(Id)
																	FROM despachos_segundotramo_distribucion_lotes L_x
																 WHERE L_x.id_distribucionunidad = U.Id
																	 AND L_x.peso_neto IS NULL) AS TOTAL_LOTES

													FROM controlingresovehiculo I
															 INNER JOIN despachos_segundotramo_distribucion_unidades U ON I.dFechaIngreso >= U.fecha_ingresoplanta
															 INNER JOIN despachos_segundotramo_programacion P ON U.id_programacion = P.Id
															 INNER JOIN transporte T ON U.id_unidad = T.id_transporte
																 AND I.placa = T.cplaca
															 INNER JOIN tbconfig_tipovehiculo TV ON T.id_tipovehiculo = TV.Id
															 INNER JOIN despachos_segundotramo_distribucion_lotes L ON U.Id = L.id_distribucionunidad
																 AND L.is_complemento = 0
															 INNER JOIN tbconfig_tipocarga TC ON L.id_tipocarga = TC.Id
															 LEFT JOIN tb_clientes ET ON T.id_Transportista = ET.Id
															 INNER JOIN catalogolotes CL ON L.cod_lote = CL.ccod_Lote
															 INNER JOIN tbconfig_plantas PL ON P.id_planta = PL.Id
												 WHERE I.id_tipoingresounidad = 2
													 /*AND I.dFechaIngreso BETWEEN '" . $fecha_inicio . "' AND '" . $fecha_fin . "'*/
													 AND (L.peso_tara IS NULL
														OR L.peso_bruto IS NULL)";

		if (strlen($filtro_transportista) > 0) {
			$q_balanza .= "   AND I.id_transportista = " . $filtro_transportista;
		}

		if (strlen($filtro_placa) > 0) {
			$q_balanza .= "   AND I.placa LIKE '%" . $filtro_placa . "%'";
		}

		if (strlen($filtro_lote) > 0) {
			$q_balanza .= "   AND L.cod_lote LIKE '%" . $filtro_lote . "%'";
		}

		$q_balanza .= " ORDER BY I.dhoraingresoPlanta, L.cod_lote";

