		$is_loteaum = $_POST["is_loteaum"];
		$usuario_registro = $_SESSION["usu_usuario"];

		// Seteando campos
		$is_tablabalanza = 0;
		$is_tablalotes = 0;
		$campo1 = '';
		$campo2 = '';
		$campo3 = '';

