			$campo1 = 'num_bigbag';
			$campo2 = 'num_bigbag_fechahoraregistro';
			$campo3 = 'num_bigbag_usuarioregistro';

			$is_tablalotes = 1;
		}

		if ($item == 3) { // PESO INICIAL
			$campo1 = 'peso_tara';
			$campo2 = 'peso_tara_fechahoraregistro';
			$campo3 = 'peso_tara_usuarioregistro';

			$valor = $valor / 1000;

			$is_tablalotes = 1;
		}

		if ($item == 4) {
			$campo1 = 'peso_bruto';
			$campo2 = 'peso_bruto_fechahoraregistro';
			$campo3 = 'peso_bruto_usuarioregistro';

			$valor = $valor / 1000;

			$is_tablalotes = 1;
		}

		if ($item == 5) {
			$campo1 = 'observacion';
			$campo2 = 'observacion_fechahoraregistro';
			$campo3 = 'observacion_usuarioregistro';

			$is_tablalotes = 1;
		}

		// Si es Peso Inicial genera el nuevo correlativo para el Ticket de Balanza
		$correlativo_ticket = 0;

		$q_correlativo = "SELECT IFNULL(MAX(correlativo), 0) + 1 AS CORRELATIVO";
		$q_correlativo .= "  FROM correlativo_ticketsbalanza";

		if ($res_correlativo = mysqli_query($enlace, $q_correlativo)) {
			if (mysqli_num_rows($res_correlativo) > 0) {
				while ($row_correlativo = mysqli_fetch_array($res_correlativo)) {
					$correlativo_ticket = $row_correlativo["CORRELATIVO"];
				}
			}
		}

		// Guarda Log del registro original
		if ($is_tablabalanza == 1) {
			$q_save = "UPDATE controlingresovehiculo SET";
			$q_save .= "   " . $campo1 . " = " . ((strlen($valor) == 0) ? 'NULL' : "'" . mb_strtoupper($valor) . "'") . ", ";
			$q_save .= "   " . $campo2 . " = '" . $g_fecha . "', ";
			$q_save .= "   " . $campo3 . " = '" . $usuario_registro . "'";
			$q_save .= " WHERE id_controlIngresoVehiculo = " . $id_registro;
		}

		if ($is_tablalotes == 1) {
			$q_save = "UPDATE despachos_segundotramo_distribucion_lotes SET";
			$q_save .= "   " . $campo1 . " = " . ((strlen($valor) == 0) ? 'NULL' : "'" . mb_strtoupper($valor) . "'") . ", ";
			$q_save .= "   " . $campo2 . " = '" . $g_fecha . "', ";
			$q_save .= "   " . $campo3 . " = '" . $usuario_registro . "'";
			$q_save .= " WHERE Id = " . $id_registro;
		}

		if ($res_save = mysqli_query($enlace, $q_save)) {
			$estado = 1;

			// Actualiza el Correlativo del Ticket
			if ($item == 3) {
				$q_save = "UPDATE despachos_segundotramo_distribucion_lotes SET";
				$q_save .= "   num_ticketbalanza = " . $correlativo_ticket;
				$q_save .= " WHERE Id = " . $id_registro;

				if ($res_save = mysqli_query($enlace, $q_save)) {
					// Registra el Correlativo del Ticket
					$q_correlativo = "INSERT INTO correlativo_ticketsbalanza (is_segundotramo, correlativo, fechahora_registro, usuario_registro) VALUES (";
					$q_correlativo .= "1, ";
					$q_correlativo .= $correlativo_ticket . ", ";
					$q_correlativo .= "'" . $g_fecha . "', ";
					$q_correlativo .= "'" . $usuario_registro . "')";

					if ($res_correlativo = mysqli_query($enlace, $q_correlativo)) {
					}
				}
			}

			// Calcula el Peso Neto
			if ($item == 4) {
				$q_save = "UPDATE despachos_segundotramo_distribucion_lotes SET";
				$q_save .= "   peso_neto = peso_bruto - peso_tara";
				$q_save .= " WHERE Id = " . $id_registro;

				if ($res_save = mysqli_query($enlace, $q_save)) {
					// Obtiene el Peso Neto
					$peso_neto = 0;

					$q_neto = "SELECT peso_neto
															 FROM despachos_segundotramo_distribucion_lotes
															WHERE Id = " . $id_registro;

					if ($res_neto = mysqli_query($enlace, $q_neto)) {
						if (mysqli_num_rows($res_neto) > 0) {
							while ($row_neto = mysqli_fetch_array($res_neto)) {
								$peso_neto = $row_neto["peso_neto"];
							}
						}
					}

					// Cambia el Estado del Lote en Validación a Despachado
					$q_update = "UPDATE despachos_primertramo_validaciondatos SET";
					$q_update .= "  despacho_id_estadolote = 8";
					$q_update .= " WHERE lote_cod_lote = '" . $cod_lote . "'";

					if ($res_datos = mysqli_query($enlace, $q_update)) {
					}
				}

				// Actualiza la tabla de Validación y registra el Peso Neto + 2%, solo para Lote AUM
				if ($is_loteaum == 1) {
					$q_update = "UPDATE despachos_primertramo_validaciondatos SET";
					$q_update .= "  lote_peso_neto_loteaum = " . (round($peso_neto * 1.02, 2) * 1000);
					$q_update .= ", lote_peso_neto = " . (round($peso_neto * 1.02, 2) * 1000);
					$q_update .= " WHERE lote_cod_lote = '" . $cod_lote . "'";

					if ($res_update = mysqli_query($enlace, $q_update)) {
					}
				}
			}

			// Devuelve el ID_MD5 para la impresión del ticket
			$id_md5 = '';

			if ($item == 3 || $item == 4) {
				$q_idmd5 = "SELECT MD5(Id) AS ID_MD5
														FROM despachos_segundotramo_distribucion_lotes
													 WHERE Id = " . $id_registro;

				if ($res_idmd5 = mysqli_query($enlace, $q_idmd5)) {
					if (mysqli_num_rows($res_idmd5) > 0) {
						while ($row_idmd5 = mysqli_fetch_array($res_idmd5)) {
							$id_md5 = $row_idmd5["ID_MD5"];
						}
					}
				}
			}
		}

		cerrar_lote_desde_segundo_tramo($enlace, $id_registro, $g_fecha, $usuario_registro);

		echo json_encode(array('estado' => $estado, 'id_md5' => md5($id_registro)));

		break;

	case 'cierre_SegundoTramo_PesosBalanza':
		$estado = 0;

		// Recupera variables
		$id_unidad = $_POST["id_unidad"];
