		// Obtiene los lotes de Balanza (Que no sean Lote AUM)
		$q_validacion = "	SELECT DISTINCT
																	 V.lote_num_ticket,
																	 V.lote_id_lote,
																	 V.lote_cod_lote,
																	 MD5(V.lote_id_lote) AS ID_MD5,
																	 V.despacho_id_responsablelote,
																	 V.despacho_id_modalidadenvio,
																	 V.despacho_id_destinoplanta,
																	 V.despacho_destinoplanta_fechahoraregistro,
																	 V.despacho_id_estadolote,
																	 V.balanza_observacion,
																	 V.lote_id_encargadomuestra,
																	 /*V.lote_pesoinicial_fechahoraregistro,*/

																	 V.lote_id_proveedorminero,
																	 CL.proveedorminero_concesion,
																	 CL.proveedorminero_codigounico,
																	 CL.proveedorminero_ubicacion,
																	 CL.documento,

																	 V.lote_id_tipomineral,
																	 V.lote_id_tipocarga,
																	 V.despacho_color,
																	 V.operaciones_humedad,
																	 V.is_cerrado,
																	 V.cerrado_fechahoraregistro,
																	 V.cerrado_usuarioregistro,
																	 L.is_loteaum,
																	 V.lote_peso_neto_loteaum,
																	 V.lote_id_proveedorminero_concesion
															FROM despachos_primertramo_validaciondatos V
																	 LEFT JOIN tb_clientes CL ON V.lote_id_proveedorminero = CL.Id
																	 INNER JOIN catalogolotes L ON V.lote_cod_lote = L.ccod_Lote
														 WHERE L.is_loteaum = 0
															 /*AND (YEAR(balanza_fechahoraregistro) >= 2024*/
															 AND (YEAR(L.tFechaInicialBalanza) >= 2024
																OR V.lote_cod_lote IN ('AUM-2587', 'AUM-3000', 'AUM-2337', 'AUM-2585', 'AUM-2907', 'AUM-2980'))";

		if (strlen($arr_lotes) > 0) {
			$q_validacion .= "   AND V.lote_cod_lote IN (" . $arr_lotes . ")";
		} else {
			// $q_validacion .= "   AND DATE(V.lote_pesoinicial_fechahoraregistro) BETWEEN '".$fecha_inicio."' AND '".$fecha_fin."'";
			$q_validacion .= "   AND DATE(L.tFechaInicialBalanza) BETWEEN '" . $fecha_inicio . "' AND '" . $fecha_fin . "'";

			if (strlen($filtro_estadolote) > 0) {
				$q_validacion .= "   AND V.despacho_id_estadolote = " . $filtro_estadolote;
			}

			if (strlen($filtro_planta) > 0) {
				$q_validacion .= "   AND V.despacho_id_destinoplanta = " . $filtro_planta;
			}

			if (strlen($filtro_estadocierre) > 0) {
				$q_validacion .= "   AND V.is_cerrado = " . $filtro_estadocierre;
			}
		}

		// Obtiene los lotes AUM creados en Despachos
		$q_validacion .= " UNION

														SELECT DISTINCT
																	 V.lote_num_ticket,
																	 V.lote_id_lote,
																	 V.lote_cod_lote,
																	 MD5(V.lote_id_lote) AS ID_MD5,
																	 V.despacho_id_responsablelote,
																	 V.despacho_id_modalidadenvio,
																	 V.despacho_id_destinoplanta,
																	 V.despacho_destinoplanta_fechahoraregistro,
																	 V.despacho_id_estadolote,
																	 V.balanza_observacion,
																	 V.lote_id_encargadomuestra,
																	 /*V.lote_pesoinicial_fechahoraregistro,*/

																	 V.lote_id_proveedorminero,
																	 CL.proveedorminero_concesion,
																	 CL.proveedorminero_codigounico,
																	 CL.proveedorminero_ubicacion,
																	 CL.documento,

																	 V.lote_id_tipomineral,
																	 V.lote_id_tipocarga,
																	 V.despacho_color,
																	 V.operaciones_humedad,
																	 V.is_cerrado,
																	 V.cerrado_fechahoraregistro,
																	 V.cerrado_usuarioregistro,
																	 L.is_loteaum,
																	 V.lote_peso_neto_loteaum,
																	 V.lote_id_proveedorminero_concesion
															FROM despachos_primertramo_validaciondatos V
																	 LEFT JOIN tb_clientes CL ON V.lote_id_proveedorminero = CL.Id
																	 INNER JOIN catalogolotes L ON V.lote_cod_lote = L.ccod_Lote
														 WHERE L.is_loteaum = 1
															 /*AND YEAR(balanza_fechahoraregistro) >= 2024*/
															 AND YEAR(L.tFechaInicialBalanza) >= 2024";

		if (strlen($arr_lotes) > 0) {
			$q_validacion .= "   AND V.lote_cod_lote IN (" . $arr_lotes . ")";
		} else {
			$q_validacion .= "   AND L.tFechaInicialBalanza BETWEEN '" . $fecha_inicio . "' AND '" . $fecha_fin . "'";

			if (strlen($filtro_estadolote) > 0) {
				$q_validacion .= "   AND V.despacho_id_estadolote = " . $filtro_estadolote;
			}

			if (strlen($filtro_planta) > 0) {
				$q_validacion .= "   AND V.despacho_id_destinoplanta = " . $filtro_planta;
