					// Obtiene Fecha Real de Peso Inicial de Balanza
					$fecha_pesoinicial = '';

					$q_balanza = "SELECT tFechaInicialBalanza
																FROM catalogolotes
															 WHERE ccod_Lote = '" . $row_validacion["lote_cod_lote"] . "'";

					if ($res_balanza = mysqli_query($enlace, $q_balanza)) {
						if (mysqli_num_rows($res_balanza) > 0) {
							while ($row_balanza = mysqli_fetch_array($res_balanza)) {
								$fecha_pesoinicial = $row_balanza["tFechaInicialBalanza"];
							}
						}
					}

					// Verifica los 4 criterios completos para las guías
					$cierre_pendiente = 0;

					// Comrpueba que todos los tickets tengan Placa
					$placa_pendiente = 0;

					$q_pendiente = "SELECT COUNT(Id) AS _COUNT
																		FROM despachos_primertramo_validaciondatos
																	 WHERE lote_cod_lote = '" . $row_validacion["lote_cod_lote"] . "'
																		 AND balanza_placa IS NULL";

					if ($res_pendiente = mysqli_query($enlace, $q_pendiente)) {
						if (mysqli_num_rows($res_pendiente) > 0) {
							while ($row_pendiente = mysqli_fetch_array($res_pendiente)) {
								if ($row_pendiente["_COUNT"] > 0) {
									$placa_pendiente = 1;
								}
							}
						}
					}

					if (
						$row_validacion["despacho_id_modalidadenvio"] == 3 ||
						$row_validacion["despacho_id_modalidadenvio"] == 4 ||
						$row_validacion["despacho_id_modalidadenvio"] == 5 ||
						$row_validacion["despacho_id_modalidadenvio"] == 6
					) {
						if (
							$placa_pendiente == 1 ||
							strlen($row_validacion["despacho_id_modalidadenvio"]) == 0 ||
							strlen($row_validacion["lote_id_proveedorminero"]) == 0
						) {
							$cierre_pendiente = 0;
						}
					} else {
						if (
							$placa_pendiente == 1 ||
							strlen($row_validacion["despacho_id_modalidadenvio"]) == 0 ||
							strlen($row_validacion["despacho_id_destinoplanta"]) == 0 ||
							strlen($row_validacion["lote_id_proveedorminero"]) == 0
						) {
							$cierre_pendiente = 0;
						}
					}

					// Obtiene datos de Balanza
					$total_neto = 0;

					$q_datos = "SELECT CONCAT(tFechaInicialBalanza, ' ', tHoraInicialBalanza) AS FECHAHORA_INICIO,
																	 tFechaInicialBalanza AS FECHA_INICIO,
																	 nPesoNetoBalanza
															FROM catalogolotes
														 WHERE ccod_Lote = '" . $row_validacion["lote_cod_lote"] . "'";

					if ($res_datos = mysqli_query($enlace, $q_datos)) {
						if (mysqli_num_rows($res_datos) > 0) {
							while ($row_datos = mysqli_fetch_array($res_datos)) {
								$f = $row_datos["FECHA_INICIO"];
								$total_neto = $row_datos["nPesoNetoBalanza"] / 1000;
							}
						}
					}

					// Inicia con la carga de datos
					$html .= '  <td id="td_select_1_' . $d . '" class="sticky td_bgselect" style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; cursor: pointer; background-color: ' . (($d == 1) ? '#FFF587' : '#ffffff') . ';">';
					$html .= '    <div class="d-flex">';
					$html .= '    	<div style="width: 25px;">';
					$html .= '    		<img class="cs_imgselect" id="img_select_' . $d . '" src="' . $img_select . '" style="width: 20px; display: ' . (($d == 1) ? 'block' : 'none') . ';">';
					$html .= '    	</div>';
					$html .= '    	' . $d;
					$html .= '    </div>';
