					$html .= '		<input id="td_iscerrado_' . $d . '" type="hidden" value="' . $is_cerrado . '">';
					$html .= '  </td>';

					$html .= '  <td id="td_select_2_' . $d . '" class="sticky-3 td_bgselect" style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; min-width: 60px; cursor: pointer; background-color: ' . (($d == 1) ? '#FFF587' : '#ffffff') . ';" hidden>';
					$html .= '    ' . $row_validacion["lote_num_ticket"];
					$html .= '  </td>';

					$html .= '  <td id="td_select_3_' . $d . '" class="sticky-4 td_bgselect" style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; font-weight: bold; cursor: pointer; background-color: ' . (($d == 1) ? '#FFF587' : '#ffffff') . ';">';
					$html .= '    <spam><img src="../' . $img_colores . '" style="width: 15px; margin-top: -5px; margin-right: 3px; cursor: pointer;" onclick="f_SetColor(' . $d . ", '" . $row_validacion["lote_cod_lote"] . "'" . ');"></spam>';
					$html .= '    <label id="td_lote_' . $d . '" style="cursor: pointer;">';
					$html .= '    	' . $row_validacion["lote_cod_lote"];
					$html .= '    </label>';

					if ($is_cerrado == 1) {
						$html .= '    <label style="font-size: 13px; color: #FF5F5D; text-align: center;">';
						$html .= '    	<i>Cerrado</i>';
						$html .= '    </label>';
					}

					$html .= '  </td>';

					// Carga lista de Responsables de Despachos
					$html .= '  <td class="sticky-5" style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; background-color: #ffffff;">';
					$html .= '		<select id="val_1_' . $d . '" class="form-select select_datos input_datos_' . $d . '" data-placeholder="Elija una opción..." style="text-align: left; font-size: 14px;" onchange="f_UpdateDatos(' . $d . ', 1);">';

					$id_row = $row_validacion["despacho_id_responsablelote"];

					$_html_encargadolote_x = str_replace('value="' . $id_row . '"', 'value="' . $id_row . '" selected', $_html_encargadolote);

					$html .= '			' . $_html_encargadolote_x;
					$html .= '		</select>';
					$html .= '  </td>';

					$html .= '  <td id="td_fechainicial_' . $d . '" style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';
					$html .= '    ' . substr($fecha_pesoinicial, 0, 10);
					$html .= '  </td>';

					// Cálculo de días totales
					$bgcolor_diastranscurridos = '';

					if ($row_validacion["cerrado_fechahoraregistro"] == 4) {
						$fechaDada = $fecha_pesoinicial;
					} else {
						$fechaDada = $fecha_pesoinicial;
					}

					$fechaHoy = new DateTime(); // Obtiene la fecha y hora actual

					$fechaInicio = new DateTime($fechaDada);
					$diferencia = $fechaInicio->diff($fechaHoy);

					$totalHoras = $diferencia->days * 24 + $diferencia->h + ($diferencia->i / 60) + ($diferencia->s / 3600);
					$formatoDias = number_format($totalHoras / 24, 1);

					if ($formatoDias >= 0 && $formatoDias <= 3) {
						$bgcolor_diastranscurridos = '#03A64A;';
					}

					if ($formatoDias >= 3.01 && $formatoDias <= 6) {
						$bgcolor_diastranscurridos = '#EB8F10';
					}

					if ($formatoDias > 6) {
						$bgcolor_diastranscurridos = '#FF2F24;';
					}

					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; font-weight: bold; color: ' . $bgcolor_diastranscurridos . '">';
					$html .= '    ' . $formatoDias;
					$html .= '  </td>';

					// Obtiene Total de Toneladas Distribuídas
					$tmh_distribuido = 0;

					$q_datos = "SELECT SUM(lote_peso_neto) AS TOTAL_TMH
															FROM despachos_primertramo_validaciondatos
														 WHERE lote_cod_lote = '" . $row_validacion["lote_cod_lote"] . "'";

					if ($res_datos = mysqli_query($enlace, $q_datos)) {
						if (mysqli_num_rows($res_datos) > 0) {
							while ($row_datos = mysqli_fetch_array($res_datos)) {
								$tmh_distribuido = $row_datos["TOTAL_TMH"] / 1000;

								// Solo para Sara Briceño
								if ($row_validacion["lote_id_encargadomuestra"] == 3 || $row_validacion["lote_id_encargadomuestra"] == 42) {
									if (floatval($tmh_distribuido) != floatval($total_neto)) {
										$total_neto = $tmh_distribuido;
