																	 IFNULL(DL.guiatransportista_numero, '--') AS guiatransportista_numero,
																	 MD5(DL.guiaremitente_serie) AS guiaremitente_serie_MD5,
																	 MD5(DL.guiaremitente_numero) AS guiaremitente_numero_MD5,
																	 MD5(DL.guiatransportista_serie) AS guiatransportista_serie_MD5,
																	 MD5(DL.guiatransportista_numero) AS guiatransportista_numero_MD5,
																	 TR.documento AS TRANSPORTISTA_RUC,
