														 WHERE P.is_cerrado = 1) AS DATOS
													 LEFT JOIN tbconfig_modalidadenvio ME ON DATOS.guias_idmodalidadenvio = ME.Id
										 WHERE DATOS.codigo_despacho = '" . $codigo_despacho . "'
											 AND DATOS.id_modalidadenvio = " . $id_modalidadenvio . "
											 AND DATOS.ID_UNIDAD_x = " . $id_distribucionunidad . "
											 AND DATOS.cplaca " . $placa;

