					$marca_2 = $row_placa2["id_marca"];
					$capacidad = ((strlen($row_placa2["nCapacidad"]) > 0) ? number_format($row_placa2["nCapacidad"] / 1000, 2, '.', '') : 0);
				}
			}
		}

		// 7. Motivo de Traslado
		if ($ruc_remitente == $ruc_destinatario) {
