					$html .= '  </td>';

					$html .= '  <td id="guialote_lote_' . $d . '" style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; background-color: #ffffff; font-weight: bold;">';
					$html .= '    ' . $row_datos["cod_lote"];
					$html .= '  </td>';

					$html .= '  <td id="guialote_parte_' . $d . '" style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; background-color: #ffffff; font-weight: bold;">';
					$html .= '    ' . ((strlen($row_datos["num_parte"]) == 0) ? '---' : 'PARTE ' . $row_datos["num_parte"]);
					$html .= '  </td>';

					// Descripción del Bien
					$id_descripcionbien_x = 1;

