					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; background-color: #ffffff; font-weight: bold;">';
					$html .= '		<select id="guialote_descripcionbien_' . $d . '" class="form-select select_datos" style="text-align: left; font-size: 14px;">';

					$q_descripcionbien = "SELECT Id,
																						 descripcion
																				FROM tbconfig_segundotramo_guiasdescripcionbien
																			 WHERE estado = 'A'";

					if ($res_descripcionbien = mysqli_query($enlace, $q_descripcionbien)) {
						if (mysqli_num_rows($res_descripcionbien) > 0) {
							while ($row_descripcionbien = mysqli_fetch_array($res_descripcionbien)) {
								$html .= '<option ' . (($row_descripcionbien["Id"] == $id_descripcionbien_x) ? 'selected' : '') . ' value="' . $row_descripcionbien["Id"] . '">' . $row_descripcionbien["descripcion"] . '</option>';
							}
						}
					}

					$html .= '  </td>';

					$html .= '  <td id="guialote_presentacion_' . $d . '" style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; background-color: #ffffff; font-weight: bold;">';
					$html .= '    ' . ((strlen($row_datos["num_bigbag"]) == 0) ? '' : $row_datos["num_bigbag"] . ' ') . $row_datos["TIPO_CARGA"];
					$html .= '  </td>';

					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; background-color: #ffffff; font-weight: bold;">';

					// Obteniendo el Peso Neto de Balanza
					$total_distribuido_x = number_format(($row_datos["peso_bruto"] - $row_datos["peso_tara"]), 2, '.', '');

					if ($row_datos["TIENE_COMPLEMENTO"] == 1) {
						$total_distribuido_x = $total_distribuido_x - $row_datos["COMPLEMENTO_PESODISTRIBUIDO"];
					}

					if ($row_datos["is_complemento"] == 1) {
						$total_distribuido_x = $row_datos["COMPLEMENTO_PESODISTRIBUIDO2"];
					}

					$total_distribuido += $total_distribuido_x;

					$html .= '    ' . number_format($total_distribuido_x, 2, '.', '');
					$html .= '  </td>';

					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; background-color: #ffffff; font-weight: bold;">';

					$total_ajustado_x = number_format(f_Redondear_Mas(($total_distribuido_x), 1), 2, '.', '');
					$total_ajustado += $total_ajustado_x;

					$html .= '    <input id="guialote_pesoajustado_' . $d . '" type="number" class="form-control" style="text-align: center; font-size: 13px; font-weight: bold;" value="' . number_format($total_ajustado_x, 2, '.', '') . '" onkeyup="f_GetTotalPesoAjustado();" onchange="f_GetTotalPesoAjustado();">';
					$html .= '  </td>';

					$d++;
				}

				// Agregando fila de totales
				$html .= '<tr style="font-size: 14px;">';
				$html .= '  <td colspan="5" style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: right; background-color: #37393c; color: #ffffff; font-weight: bold;">';
				$html .= '    TOTAL: ';
				$html .= '  </td>';

				$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; background-color: #37393c; color: #ffffff; font-weight: bold;">';
				$html .= '		' . number_format($total_distribuido, 2, '.', '');
				$html .= '  </td>';

				$html .= '  <td id="guialote_totalpesoajustado" style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; background-color: #37393c; color: #ffffff; font-weight: bold;">';
				$html .= '		' . number_format($total_ajustado, 2, '.', '');
				$html .= '  </td>';
				$html .= '</tr>';
			}
		}

		echo json_encode(array('estado' => $estado, 'punto_partida' => $punto_partida, 'punto_destino' => $punto_destino, 'remitente' => ($ruc_remitente . ' - ' . $remitente), 'destinatario' => $destinatario, 'transportista' => $transportista, 'codigo_mtc_1' => $codigo_mtc_1, 'marca_1' => $marca_1, 'chofer' => $chofer, 'motivo_traslado' => $motivo_traslado, 'codigo_mtc_2' => $codigo_mtc_2, 'marca_2' => $marca_2, 'capacidad' => $capacidad, 'html' => $html, "fechahora_emision" => $fechahora_emision, "fecha_guia" => $fecha_guia));

		break;

	case 'get_ListaResumenBalanza_GestionMuestras':
		$res = array();
		$estado = 0;

		// Recupera parámetros
		$fecha_inicio = mysqli_real_escape_string($enlace, $_POST['fecha_inicio']);
		$fecha_fin = mysqli_real_escape_string($enlace, $_POST['fecha_fin']);
		$filtro_condicioningreso = mysqli_real_escape_string($enlace, $_POST['filtro_condicioningreso']);
		$filtro_transportista = mysqli_real_escape_string($enlace, $_POST['filtro_transportista']);
		$filtro_placa = mysqli_real_escape_string($enlace, $_POST['filtro_placa']);
		$filtro_lote = mysqli_real_escape_string($enlace, $_POST['filtro_lote']);
		$gestionmuestras_operaciones = mysqli_real_escape_string($enlace, $_POST['gestionmuestras_operaciones']);
		$gestionmuestras_vigilancia = mysqli_real_escape_string($enlace, $_POST['gestionmuestras_vigilancia']);
		$gestionmuestras_apoyointerno = mysqli_real_escape_string($enlace, $_POST['gestionmuestras_apoyointerno']);
		$gestionmuestras_acopiador = mysqli_real_escape_string($enlace, $_POST['gestionmuestras_acopiador']);

		// Obtiene datos y arma el html
		$d = 1;
		$id_lote = 0;
		$html = '';

		$q_balanza = "SELECT I.id_controlIngresoVehiculo,
														 MD5(L.id_CatalogoLotes) AS ID_MD5,
														 CONCAT(I.dFechaIngreso, ' ', I.dhoraingresoPlanta) AS FECHAHORA_REGISTRO,
														 I.id_tipoingresounidad,
														 IU.descripcion AS CLIENTE_CONDICION,
														 I.placa,
														 I.placa2,
														 I.id_transportista,
														 T.documento AS RUC_EMPRESATRANSPORTE,
														 T.razon_social AS EMPRESA_TRANSPORTE,
														 I.id_tipovehiculo,
														 TV.descripcion AS TIPO_VEHICULO,
														 I.id_choferes,
														 CD.dni_licencia,
														 CD.nombres AS CONDUCTOR,
														 L.balanza_id_tipocarga,
														 TC.descripcion AS TIPO_CARGA,
														 L.balanza_id_zonaorigen,
														 ZO.descripcion AS ZONA_ORIGEN,
														 I.cNotas,
														 L.id_CatalogoLotes, 
														 L.ccod_Lote,
														 MD5(L.ccod_Lote) AS MD5_LOTE,
														 L.dFechaCreacion AS FECHAHORA_CREACIONLOTE,
														 L.nNro_ticketsBalanza,
														 L.item_ticketbalanza,
														 L.nPeso_InicialBalanza,
														 L.tFechaInicialBalanza,
														 L.tHoraInicialBalanza,
														 L.pesoinicial_observacion,
														 U_I.usu_usuario AS USUARIO_INICIO,
														 L.nPeso_FinalBalanza,
														 L.dFechaFinalBalanza,
														 L.tHoraFinalBalanza,
														 L.pesofinal_observacion,
														 L.id_UsuarioModificacion,
														 U_F.usu_usuario AS USUARIO_FIN,
														 L.balanza_id_proveedorminero,
														 CONCAT(PM.documento, ' - ', UPPER(PM.razon_social)) AS PROVEEDOR_MINERO,
														 L.balanza_id_encargadomuestra,
														 --UPPER(EM.nombres) AS ENCARGADO_MUESTRA,
														 /*Max 29082024: Solicitó cambio por código de encargado muestra*/
														 EM.codigo AS ENCARGADO_MUESTRA,
														 L.balanza_id_producto,
														 UPPER(P.descripcion) AS PRODUCTO,
														 L.balanza_id_tipomineral,
														 UPPER(TM.descripcion) AS TIPO_MINERAL,
														 UPPER(L.balanza_observacion) AS LOTE_OBSERVACION,
														 HC.cierre_prom,
														 HC.Id AS ID_CABECERAHUMEDAD
												FROM controlingresovehiculo I
														 INNER JOIN tbconfig_tipoingresounidades IU ON I.id_tipoingresounidad = IU.Id
														 LEFT JOIN tb_clientes T ON I.id_transportista = T.Id
														 INNER JOIN tbconfig_tipovehiculo TV ON I.id_tipovehiculo = TV.Id
														 INNER JOIN tbconfig_conductores CD ON I.id_choferes = CD.Id
														 INNER JOIN catalogolotes L ON I.id_controlIngresoVehiculo = L.id_controlIngresoVehiculo
														 LEFT JOIN tbconfig_tipocarga TC ON L.balanza_id_tipocarga = TC.Id
														 LEFT JOIN tbconfig_zonaorigen ZO ON L.balanza_id_zonaorigen = ZO.Id
														 LEFT JOIN tb_usuario U_I ON L.id_UsuarioCreacion = U_I.Id
														 LEFT JOIN tb_usuario U_F ON L.id_UsuarioModificacion = U_F.Id
														 LEFT JOIN tb_clientes PM ON L.balanza_id_proveedorminero = PM.Id
														 LEFT JOIN tbconfig_encargadosmuestra EM ON L.balanza_id_encargadomuestra = EM.Id
														 LEFT JOIN tbconfig_producto P ON L.balanza_id_producto = P.Id
														 LEFT JOIN tbconfig_tipomineral TM ON L.balanza_id_tipomineral = TM.Id
