			$estado = 1;

			// Migrando Lotes cerrados a la tabla de datos Consolidados
			f_MigrarLotes_CierreContable($enlace, 2, $arr_idlotes, $g_fecha, $usuario_registro);

			// Devuelve los números de ticket para ser actualizados
			$q_tickets = "SELECT id_registro,
																 num_ticketbalanza
														FROM consolidado_lotes_cierrecontable
													 WHERE id_registro IN (" . $arr_idlotes . ")
														 AND id_tipoingreso = 2";

			if ($res_tickets = mysqli_query($enlace, $q_tickets)) {
				if (mysqli_num_rows($res_tickets) > 0) {
					while ($row_tickets = mysqli_fetch_array($res_tickets)) {
						array_push($arr_tickets, $row_tickets);
					}
				}
			}
		}

		echo json_encode(array('estado' => $estado, 'cerrado_fechahoraregistro' => $g_fecha, 'cerrado_usuarioregistro' => $usuario_registro, 'arr_tickets' => $arr_tickets));

		break;

	case 'reabrir_SegundoTramo_CierreLotes':
		$estado = 0;

		// Recupera parámetros
