		$q_update .= "  SET is_cerradolote = 0, ";
		$q_update .= "			cerradolote_fechahoraregistro = NULL, ";
		$q_update .= "			cerradolote_usuarioregistro = NULL";
		$q_update .= " WHERE Id = " . $id_registro;

		if ($res_update = mysqli_query($enlace, $q_update)) {
			$estado = 1;

			// Eliminando registro del Consolidado
			$q_delete = "DELETE FROM consolidado_lotes_cierrecontable";
			$q_delete .= " WHERE id_tipoingreso = 2";
			$q_delete .= "   AND id_registro = " . $id_registro;

			if ($res_delete = mysqli_query($enlace, $q_delete)) {
			}
