		$q_update .= "  SET llegadaplanta_iscierre = 0, ";
		$q_update .= "			llegadaplanta_iscierre_fechahoraregistro = NULL, ";
		$q_update .= "			llegadaplanta_iscierre_usuarioregitro = NULL";
		$q_update .= " WHERE Id = " . $id_registro;

		if ($res_update = mysqli_query($enlace, $q_update)) {
			$estado = 1;
		}

		echo json_encode(array('estado' => $estado));

		break;

	case 'get_ConfiguracionVehicular':
		$estado = 0;
		$res = array();

		// Recupera parámetros
		$id_distribucionunidad = $_POST['id_distribucionunidad'];
		$remitente_ruc = $_POST['remitente_ruc'];

		// Obtiene datos
		$q_datos = "SELECT CV.Id,
													 CONCAT(DU.id_configuracionvehicular, '|', CV.pesobruto_maximopermitido, '|', CV.tiene_ingresomanual) AS ID_CONFIGURACIONVEHICULAR,
													 DU.configuracionvehicular_pesobrutomaximo,
													 DU.configuracionvehicular_pesobrutomaximo2,
													 DU.configuracionvehicular_pesobrutototaltransportado
											FROM despachos_segundotramo_distribucion_unidades DU
													 LEFT JOIN tbconfig_configuracionvehicular CV ON DU.id_configuracionvehicular = CV.Id
										WHERE DU.Id = " . $id_distribucionunidad;

		if ($res_datos = mysqli_query($enlace, $q_datos)) {
			if (mysqli_num_rows($res_datos) > 0) {
				$estado = 1;

				while ($row_datos = mysqli_fetch_array($res_datos)) {
					array_push($res, $row_datos);
				}
			}
		}

		// Obtiene Toneladas Distribuídas
		$q_toneladas = "SELECT DL.peso_bruto
													FROM despachos_segundotramo_programacion_detalle PD
															 INNER JOIN despachos_segundotramo_programacion P ON PD.id_programacion = P.Id
															 INNER JOIN despachos_segundotramo_distribucion_unidades U ON P.Id = U.id_programacion
															 INNER JOIN despachos_segundotramo_distribucion_lotes DL ON U.Id = DL.id_distribucionunidad
																 AND PD.cod_lote = DL.cod_lote
															 INNER JOIN tbconfig_remitentessegundotramo RE ON DL.guias_iddestino = RE.id_destino
																 AND DL.guias_idmodalidadenvio = RE.id_modalidadenvio
												 WHERE U.Id = '" . $id_distribucionunidad . "'
													 AND RE.ruc = '" . $remitente_ruc . "'
													 AND DL.guiaremitente_serie IS NOT NULL
											 ORDER BY DL.peso_bruto DESC LIMIT 1";

		if ($res_toneladas = mysqli_query($enlace, $q_toneladas)) {
			if (mysqli_num_rows($res_toneladas) > 0) {
				while ($row_toneladas = mysqli_fetch_array($res_toneladas)) {
					$peso_distribuido = $row_toneladas["peso_bruto"] * 1000;
				}
			}
		}

		echo json_encode(array('estado' => $estado, 'res' => $res, 'peso_distribuido' => $peso_distribuido));

		break;

	case 'grabar_ConfiguracionVehicular_PesosyMedidas':
		$estado = 0;
		$res = array();

		// Recupera variables
		$id_distribucionunidad = $_POST["id_distribucionunidad"];
		$id_configuracionvehicular = explode('|', $_POST["id_configuracionvehicular"])[0];
		$pesobruto_maximo = $_POST["pesobruto_maximo"];
		$pesobruto_maximo2 = $_POST["pesobruto_maximo2"];
		$pesobruto_total = $_POST["pesobruto_total"];
		$usuario_registro = $_SESSION["usu_usuario"];

		// Grabando datos
		$q_save = "UPDATE despachos_segundotramo_distribucion_unidades SET";
		$q_save .= "   id_configuracionvehicular = " . $id_configuracionvehicular . ', ';
		$q_save .= "   configuracionvehicular_pesobrutomaximo = " . $pesobruto_maximo . ', ';
		$q_save .= "   configuracionvehicular_pesobrutomaximo2 = " . ((strlen($pesobruto_maximo2) == 0) ? 'NULL' : $pesobruto_maximo2) . ', ';
		$q_save .= "   configuracionvehicular_pesobrutototaltransportado = '" . $pesobruto_total . "', ";
		$q_save .= "   configuracionvehicular_fechahoraregistro = '" . $g_fecha . "', ";
		$q_save .= "   configuracionvehicular_usuarioregistro = '" . $usuario_registro . "'";
		$q_save .= " WHERE Id = " . $id_distribucionunidad;

		if ($res_save = mysqli_query($enlace, $q_save)) {
			$estado = 1;

			// Obtiene el/los remitentes por Unidad
			$q_remitentes = "
			SELECT DISTINCT
				RE.ruc,
				RE.razon_social
			FROM
				despachos_segundotramo_programacion_detalle PD
			LEFT JOIN despachos_segundotramo_programacion P ON
				PD.id_programacion = P.Id
			LEFT JOIN despachos_segundotramo_distribucion_unidades U ON
				P.Id = U.id_programacion
			LEFT JOIN despachos_segundotramo_distribucion_lotes DL ON
				U.Id = DL.id_distribucionunidad AND PD.cod_lote = DL.cod_lote
			LEFT JOIN tbconfig_remitentessegundotramo RE ON
				DL.guias_iddestino = RE.id_destino AND DL.guias_idmodalidadenvio = RE.id_modalidadenvio
			WHERE
				U.Id = " . $id_distribucionunidad;

			if ($res_remitentes = mysqli_query($enlace, $q_remitentes)) {
				if (mysqli_num_rows($res_remitentes) > 0) {
					$estado = 1;

					while ($row_remitentes = mysqli_fetch_array($res_remitentes)) {
						array_push($res, $row_remitentes);
					}
				}
			}
		}

		echo json_encode(array('estado' => $estado, 'res' => $res));

		break;

	case 'get_GestionTransporte_ListaUnidades':
		$res = array();
		$estado = 0;
		$d = 1;
		$cod_despacho = '';
		$id_unidad = '';
		$id_modalidadenvio = '';
		$arr_modalidades = array();

		// Recuperando parámetros
		$id_planta = mysqli_real_escape_string($enlace, $_POST["id_planta"]);
		$fecha_inicio = mysqli_real_escape_string($enlace, $_POST['fecha_inicio']);
		$fecha_fin = mysqli_real_escape_string($enlace, $_POST['fecha_fin']);
		$estado_cierre = mysqli_real_escape_string($enlace, $_POST['estado_cierre']);
		$filtro_codigodespacho = $_POST['filtro_codigodespacho'];
		$filtro_lote = $_POST['filtro_lote'];

		// Setea Filtro de Lotes
		$l = 0;
		$arr_lotes = '';

		if (isset($filtro_lote) && is_array($filtro_lote)) {
			while ($l < count($filtro_lote)) {
				$arr_lotes .= "'" . $filtro_lote[$l] . "', ";

				$l++;
			}

			if (strlen($arr_lotes) > 0) {
				$arr_lotes = substr($arr_lotes, 0, -2);
			}
		}

		// Setea Filtro de Despachos
		$l = 0;
		$arr_codigosdespacho = '';

		if (isset($filtro_codigodespacho) && is_array($filtro_codigodespacho)) {
			while ($l < count($filtro_codigodespacho)) {
				$arr_codigosdespacho .= "'" . $filtro_codigodespacho[$l] . "', ";

				$l++;
			}

			if (strlen($arr_codigosdespacho) > 0) {
				$arr_codigosdespacho = substr($arr_codigosdespacho, 0, -2);
			}
		}

		// Obtiene datos
		$d = 1;
		$html = '';

		$q_datos = "SELECT DATOS.ID_UNIDAD,
													 DATOS.codigo_despacho,
													 DATOS.codigo_despacho_comercializacion,
													 DATOS.guias_idmodalidadenvio AS ID_MODALIDAD_ENVIO,
													 DATOS.MODALIDAD_ENVIO,
													 DATOS.FECHAHORA_SALIDA,
													 /*DATOS.FECHA_LLEGADAPLANTA,*/
													 DATOS.TIPO_VEHICULO,
													 DATOS.PLACA1,
													 DATOS.PLACA2,
													 DATOS.TRANSPORTISTA_RUC,
													 DATOS.TRANSPORTISTA_RAZONSOCIAL,
													 MO.abv AS MONEDA_ABV,
													 IFNULL(LC.tarifa, TT.tarifa_sin_igv) AS tarifa_sin_igv,
													 DATOS.id_coordinadortransporte,
													 DATOS.COORDINADOR_TRANSPORTE,
													 guias_remitenteruc,
													 LC.Id AS ID_CIERRE,
													 MD5(LC.Id) AS ID_CIERRE_MD5,
													 LC.fechahora_registro AS FECHAHORA_CERRE,
													 LC.usuario_registro AS USUARIO_CIERRE,

													 SUM(llegadaplanta_pesonetoplanta) AS TMH_TOTAL

											FROM (SELECT DISTINCT
																	 U.Id AS ID_UNIDAD,
																	 PD.codigo_despacho,
																	 PD.codigo_despacho_comercializacion,

																	 DL.guias_idmodalidadenvio,
																	 ME.descripcion AS MODALIDAD_ENVIO,
				 
																	 /*(SELECT CI.fechahora_salida
																			FROM controlingresovehiculo CI
																		 WHERE CI.placa = UN.cplaca
																			 AND CI.dFechaIngreso BETWEEN U.fecha_ingresoplanta AND P.fechaestimada_despacho
																		ORDER BY CI.fechahora_salida DESC
																		LIMIT 1) AS FECHAHORA_SALIDA,*/

																	 U.inforci_fechasalida AS FECHAHORA_SALIDA,
																		
																	 DATE(DL.llegadaplanta_fechaingreso) AS FECHA_LLEGADAPLANTA,
																	 TV.descripcion AS TIPO_VEHICULO,
																	 UN.cplaca AS PLACA1,
																	 UN2.cplaca AS PLACA2,
																	 TR.documento AS TRANSPORTISTA_RUC,
																	 TR.razon_social AS TRANSPORTISTA_RAZONSOCIAL,
																	 DL.llegadaplanta_pesonetoplanta,
																	 PD.id_planta,
																	 U.id_coordinadortransporte,
																	 CT.nombres AS COORDINADOR_TRANSPORTE,
																	 DL.guias_remitenteruc
															FROM despachos_segundotramo_programacion_detalle PD
																	 INNER JOIN despachos_segundotramo_programacion P ON PD.id_programacion = P.Id
																	 INNER JOIN despachos_segundotramo_distribucion_unidades U ON P.Id = U.id_programacion
																	 INNER JOIN despachos_segundotramo_distribucion_lotes DL ON U.Id = DL.id_distribucionunidad
																		 AND PD.cod_lote = DL.cod_lote
																	 INNER JOIN transporte UN ON U.id_unidad = UN.id_transporte
																	 LEFT JOIN transporte UN2 ON U.id_unidad2 = UN2.id_transporte
																	 INNER JOIN tb_clientes TR ON UN.id_Transportista = TR.Id
																	 INNER JOIN tbconfig_plantas PL ON PD.id_planta = PL.Id
																	 LEFT JOIN tbconfig_modalidadenvio ME ON DL.guias_idmodalidadenvio = ME.Id
																	 INNER JOIN tbconfig_tipovehiculo TV ON UN.id_tipovehiculo = TV.Id
																	 LEFT JOIN tbconfig_coordinadorestransporte CT ON U.id_coordinadortransporte = CT.Id
														 WHERE DL.is_complemento = 0
															 AND DL.guias_fecha IS NOT NULL
															 AND P.id_planta = $id_planta ";
		/*AND P.id_planta = " . $id_planta;*/

		if (strlen($arr_lotes) > 0 || strlen($arr_codigosdespacho) > 0) {
			if (strlen($arr_lotes) > 0) {
				$q_datos .= "   AND P.Id IN (SELECT PD_x.id_programacion
																					 FROM despachos_segundotramo_programacion_detalle PD_x
																					WHERE PD_x.cod_lote IN (" . $arr_lotes . "))";
			}

			if (strlen($arr_codigosdespacho) > 0) {
				$q_datos .= "   AND PD.codigo_despacho IN (" . $arr_codigosdespacho . ")";
			}
		} else {
			$q_datos .= "   AND DATE(P.fechaestimada_despacho) BETWEEN '" . $fecha_inicio . "' AND '" . $fecha_fin . "'";

			// if (strlen($estado_cierre) > 0){
			// 	$q_datos .= "   AND P.is_cerrado = ".$estado_cierre;
			// }
		}

		$q_datos .= ") AS DATOS
										 LEFT JOIN tbconfig_tarifatransporte TT ON TT.estado = 'A'
											 AND DATOS.id_coordinadortransporte = TT.id_coordinadortransporte
											 AND DATOS.id_planta = TT.id_planta
										 LEFT JOIN tbconfig_monedas MO ON TT.id_moneda = MO.Id
										 LEFT JOIN liquidaciones_transporte LC ON DATOS.codigo_despacho = LC.codigo_despacho
											 AND DATOS.guias_remitenteruc = LC.remitente_ruc
											 AND DATOS.PLACA1 = LC.placa
										 GROUP BY DATOS.ID_UNIDAD, DATOS.codigo_despacho, DATOS.codigo_despacho_comercializacion, DATOS.guias_idmodalidadenvio, DATOS.FECHAHORA_SALIDA, /*DATOS.FECHA_LLEGADAPLANTA,*/ DATOS.TIPO_VEHICULO, DATOS.PLACA1, DATOS.PLACA2, DATOS.TRANSPORTISTA_RUC, DATOS.TRANSPORTISTA_RAZONSOCIAL, MO.abv, IFNULL(LC.tarifa, TT.tarifa_sin_igv), DATOS.id_coordinadortransporte, COORDINADOR_TRANSPORTE, guias_remitenteruc, LC.Id
										 ORDER BY (LC.Id IS NULL) DESC, codigo_despacho";

		if ($res_datos = mysqli_query($enlace, $q_datos)) {
			if (mysqli_num_rows($res_datos) > 0) {
				$estado = 1;

				while ($row_datos = mysqli_fetch_array($res_datos)) {
					if ($d == 1) {
						$cod_despacho = $row_datos["codigo_despacho"];
						$id_unidad = $row_datos["ID_UNIDAD"];
						$id_modalidadenvio = $row_datos["ID_MODALIDAD_ENVIO"];
					}

					$is_cerrado = 0;

					if (strlen($row_datos["FECHAHORA_CERRE"]) > 0) {
						$is_cerrado = 1;
					}

					// Recolecta modalidades unicas
					$modalidad_key = $row_datos["ID_MODALIDAD_ENVIO"];
					if (!isset($arr_modalidades[$modalidad_key])) {
						$arr_modalidades[$modalidad_key] = array('id' => $row_datos["ID_MODALIDAD_ENVIO"], 'descripcion' => $row_datos["MODALIDAD_ENVIO"]);
					}

					$html .= '<tr id="tr_detalle_' . $d . '" class="bg_selected bg_selected_' . $d . '" data-modalidad="' . $row_datos["ID_MODALIDAD_ENVIO"] . '" style="font-size: 14px; cursor: pointer; background-color: ' . (($d == 1) ? '#FFF587' : '#ffffff') . ';" onclick="f_LoadItemInformacionLotes(' . $d . ", '" . $row_datos["codigo_despacho"] . "', " . $row_datos["ID_UNIDAD"] . ', ' . $row_datos["ID_MODALIDAD_ENVIO"] . ')">';

					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';
					$html .= '    ' . $d;
					$html .= '  </td>';

					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; font-weight: bold;">';
					$html .= '    ' . $row_datos["codigo_despacho"];

					if ($row_datos["ID_MODALIDAD_ENVIO"] == 6 || $row_datos["ID_MODALIDAD_ENVIO"] == 3 || $row_datos["ID_MODALIDAD_ENVIO"] == 4 || $row_datos["ID_MODALIDAD_ENVIO"] == 5) {
						$html .= ' / ' . $row_datos["codigo_despacho_comercializacion"];
					}

					$html .= '  </td>';

					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';
					$html .= '    ' . $row_datos["MODALIDAD_ENVIO"];
					$html .= '  </td>';

					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';
					$html .= '    ' . substr($row_datos["FECHAHORA_SALIDA"], 0, 10);
					$html .= '  </td>';

					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';
					$html .= '    ' . substr($row_datos["llegadaplanta_fechaingreso"], 0, 10);
					$html .= '  </td>';

					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';
					$html .= '    ' . $row_datos["TIPO_VEHICULO"];
					$html .= '  </td>';

					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; font-weight: bold;">';
					$html .= '    ' . $row_datos["PLACA1"];
					$html .= '  </td>';

					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; font-weight: bold;">';
					$html .= '    ' . $row_datos["PLACA2"];
					$html .= '  </td>';

					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; font-weight: bold;">';
					$html .= '    ' . $row_datos["COORDINADOR_TRANSPORTE"];
					$html .= '  </td>';

					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';
					$html .= '    ' . $row_datos["TRANSPORTISTA_RUC"];
					$html .= '  </td>';

					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';
					$html .= '    ' . $row_datos["TRANSPORTISTA_RAZONSOCIAL"];
					$html .= '  </td>';

					$html .= '  <td id="td_tmh_' . $d . '" style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';
					$html .= '    ' . number_format($row_datos["TMH_TOTAL"], 3, '.', '');
					$html .= '  </td>';

					$html .= '  <td id="td_preciotonelada_' . $d . '" style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';

					if ($id_planta == 4) { // Solo para Lomas
						$html .= '		<div class="d-flex">';
						$html .= '			<label style="padding-top: 7px;">' . $row_datos["MONEDA_ABV"] . '</label>';
						$html .= '			<input id="edit_tarifa_' . $d . '" type="text" class="form-control" style="text-align: center; font-size: 14px; margin-left: 5px;" value="' . $row_datos["tarifa_sin_igv"] . '" onkeyup="f_EditTarifa(' . $d . ", '" . $row_datos["codigo_despacho"] . "', '" . $row_datos["guias_remitenteruc"] . "', '" . $row_datos["PLACA1"] . "', " . $id_planta . ', ' . $row_datos["ID_MODALIDAD_ENVIO"] . ')" ' . (($is_cerrado == 1) ? 'disabled' : '') . '>';
						$html .= '		</div>';
					} else {
						$html .= '    <label id="lbl_preciotonelada_' . $d . '">' . $row_datos["MONEDA_ABV"] . ' ' . number_format($row_datos["tarifa_sin_igv"], 2, '.', ',') . '</label>';
					}

					$html .= '  </td>';

					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';
					$html .= '		<div class="d-flex justify-content-center">';
					$html .= '			<label>';
					$html .= '    		' . $row_datos["MONEDA_ABV"];
					$html .= '			</label>';

					$html .= '			<label id="td_totalbase_' . $d . '" style="margin-left: 5px; text-align: right;">';
					$html .= '  		  	' . number_format($row_datos["TMH_TOTAL"] * $row_datos["tarifa_sin_igv"], 2, '.', ',');
					$html .= '			</label>';
					$html .= '  	</td>';
					$html .= '  </td>';

					// Seteo de columnas de Cierre
					$html .= '  <td id="td_cierre_1_' . $d . '" style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';

					if ($is_cerrado == 0) {
						// Para plantas distintas a Lomas, se pasa la tarifa actual para auto-seleccionarla en el modal
						$tarifa_actual_param = '';
						if ($id_planta != 4) {
							$tarifa_actual_param = ', ' . number_format((float)$row_datos["tarifa_sin_igv"], 2, '.', '');
						}

						if ($row_datos["ID_MODALIDAD_ENVIO"] == 3 || $row_datos["ID_MODALIDAD_ENVIO"] == 6 || $row_datos["ID_MODALIDAD_ENVIO"] == 4 || $row_datos["ID_MODALIDAD_ENVIO"] == 5 || ($id_planta == 3 && ($row_datos["ID_MODALIDAD_ENVIO"] == 1 || $row_datos["ID_MODALIDAD_ENVIO"] == 2))) {
							$html .= '		<button class="btn btn-warning" type="button" onclick="f_CierreLiquidacion(' . $d . ", '" . $row_datos["codigo_despacho"] . "', '" . $row_datos["guias_remitenteruc"] . "', '" . $row_datos["PLACA1"] . "', " . $id_planta . ', ' . $row_datos["ID_MODALIDAD_ENVIO"] . ', 0, 0, ' . $row_datos["id_coordinadortransporte"] . $tarifa_actual_param . ');" style="width: 100%; color: #ffffff; font-size: 12px; background-color: #cfaa41; padding: 5px;">';
							$html .= '			<b>Generar Liquidación</b>';
							$html .= '		</button>';
						} else {
							if ($id_planta == 4 && ($row_datos["ID_MODALIDAD_ENVIO"] == 1 || $row_datos["ID_MODALIDAD_ENVIO"] == 2)) {
								$html .= '		<button class="btn btn-warning" type="button" onclick="f_CierreLiquidacion(' . $d . ", '" . $row_datos["codigo_despacho"] . "', '" . $row_datos["guias_remitenteruc"] . "', '" . $row_datos["PLACA1"] . "', " . $id_planta . ', ' . $row_datos["ID_MODALIDAD_ENVIO"] . ', 1, ' . $row_datos["id_coordinadortransporte"] . $tarifa_actual_param . ');" style="width: 100%; color: #ffffff; font-size: 12px; background-color: #cfaa41; padding: 5px;">';
								$html .= '			<b>Confirmar Flete</b>';
								$html .= '		</button>';
							}
						}
					} else {
						// Determinando si es Flete
						$is_flete = 0;

						if ($id_planta == 4 && ($row_datos["ID_MODALIDAD_ENVIO"] == 1 || $row_datos["ID_MODALIDAD_ENVIO"] == 2)) {
