		if ($orden_campo == 2) {
			$campo = 'observacion';
		}

		if ($orden_campo == 3) {
			$campo = 'cierrelote_complementotara';
		}

		// Seteando query
		$q_save = "UPDATE despachos_segundotramo_distribucion_lotes";
		$q_save .= "  SET " . $campo . " = " . ((strlen($valor) > 0) ? "'" . $valor . "'" : 'NULL');

		// Campos de auditoría
		if ($orden_campo == 3) {
			$q_save .= ', ' . $campo . "_fechahoraregistro = " . ((strlen($valor) > 0) ? "'" . $g_fecha . "'" : 'NULL');
			$q_save .= ', ' . $campo . "_usuarioregistro = " . ((strlen($valor) > 0) ? "'" . $usuario_registro . "'" : 'NULL');
