		$q_save .= " WHERE Id = " . $id;

		if ($res_save = mysqli_query($enlace, $q_save)) {
			$estado = 1;

			// Actualiza el Peso Bruto
			if ($orden_campo == 3) {
				$peso_bruto = 0;

				$update = "UPDATE despachos_segundotramo_distribucion_lotes SET";
				$update .= "  peso_bruto = (cierrelote_complementotara / 1000) + " . $complemento_pesodistribuido;
				$update .= " WHERE Id = " . $id;

				if ($res_save = mysqli_query($enlace, $update)) {
					$q_pesobruto = "SELECT peso_bruto
																	FROM despachos_segundotramo_distribucion_lotes
																 WHERE Id = " . $id;

					if ($res_pesobruto = mysqli_query($enlace, $q_pesobruto)) {
						if (mysqli_num_rows($res_pesobruto) > 0) {
							while ($row_pesobruto = mysqli_fetch_array($res_pesobruto)) {
								$peso_bruto = ($row_pesobruto["peso_bruto"] * 1000);
							}
						}
					}
				}
			}
		}

		echo json_encode(array('estado' => $estado, 'peso_bruto' => number_format($peso_bruto, 0, '.', ',')));

