					) {
						if ($id_modalidadenvio == 1 || $id_modalidadenvio == 2) {
							$num_criterio = 3;
						}

						if ($id_modalidadenvio == 3 || $id_modalidadenvio == 4 || $id_modalidadenvio == 5 || $id_modalidadenvio == 6) {
							$num_criterio = 2;
						}
					}

					if ($row_datos["verificaciondocumento_seguntotramo_criteriounidades"] == 1) {
						$num_criterio = 4;
					}

					$html .= '<tr style="font-size: 14px;">';
