					$html .= '    ' . $row_datos["documento"];
					$html .= '  </td>';

					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center;">';

					if ($row_datos["is_primertramo_showlink"] == 1) {
						$html .= '    <a href="' . $row_datos["link_busqueda"] . '" target="_blank">Abrir...</a>';
