					$a = 1;

					if ($num_criterio == 1) {
						$q_archivos = "SELECT Id,
																				nom_archivo
																	 FROM tb_verificaciondocumentos_segundotramo
																	WHERE id_programacion = " . $id_programacion . "
																		AND id_verificaciondocumento = " . $row_datos["Id"] . "
																		AND guiaremitente_serie = '" . $guia_serie . "'
																		AND guiaremitente_numero = '" . $guia_numero . "'";

						if ($res_archivos = mysqli_query($enlace, $q_archivos)) {
							if (mysqli_num_rows($res_archivos) > 0) {
								while ($row_archivos = mysqli_fetch_array($res_archivos)) {
									$html .= '<tr style="font-size: 14px;">';
									$html .= '  <td style="vertical-align: middle; border: solid; border-width: 1px; border-color: #BFBFBF; padding: 3px; text-align: center; width: 20px;">';
									$html .= '  	' . $a;
