		$html = '';

		$q_gestiondocumentaria = "
					SELECT
								D.Id as id_detalle,
								TD.Id,
								CTD.input_type,
								IF(TEMP1.input_value IS NULL,'', TEMP1.input_value) as input_value,
								TEMP1.id_gestiondocumentaria_tipo_dato,
								D.cod_tipo_cliente,
								TEMP1.is_principal,

								(SELECT COUNT(TD_x.Id)
