					$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; min-width: 60px; cursor: pointer;" hidden>';

					$html .= '		<input id="val_1_' . $d . '_' . str_replace(' ', '', $row_datos["codigo_despacho"]) . '" class="form-control edit_' . str_replace(' ', '', $row_datos["codigo_despacho"]) . '" type="time" class="form-control" style="text-align: center; font-size: 14px;" value="' . substr($row_datos["hora_estimada"], 0, 10) . '" onblur="f_Edit(1, ' . $d . ", '" . $row_datos["codigo_despacho"] . "', '" . $row_datos["hora_estimada"] . "'" . ')">';

