	case 'get_OperacionesGestionLotes_GetPosition':
		$lotes = [];

		// Consulta SQL para obtener solo la última posición de cada cod_lote
		// $q_datos = "SELECT L.ccod_Lote AS cod_lote, 
		// 									 COALESCE(P.eje_x, 10) AS eje_x, 
		// 									 COALESCE(P.eje_y, 10) AS eje_y
		// 							FROM catalogolotes L
		// 									 LEFT JOIN (SELECT cod_lote, eje_x, eje_y
		// 																FROM operaciones_gestionlotes_position
		// 															 WHERE Id IN (SELECT MAX(Id)
		// 																							FROM operaciones_gestionlotes_position
		// 																						GROUP BY cod_lote)
		// 														 ) P ON L.ccod_Lote = P.cod_lote
		// 						LIMIT 10";

		$q_datos = "SELECT DISTINCT
													 P.cod_lote,
													 P.eje_x,
													 P.eje_y,
													 PM.documento AS PROVEEDORMINERO_RUC,
													 PM.razon_social AS PROVEEDORMINERO_RAZONSOCIAL,

													 (SELECT CONCAT(L.nPeso_InicialBalanza, '|', IFNULL(L.nPeso_FinalBalanza, 0))
													 		FROM catalogolotes L
													 	 WHERE L.ccod_Lote = P.cod_lote) AS PESO_LOTE

											FROM operaciones_gestionlotes_position P
													 INNER JOIN despachos_primertramo_validaciondatos V ON P.cod_lote = V.lote_cod_lote
													 LEFT JOIN tb_clientes PM ON V.lote_id_proveedorminero = PM.Id
										 WHERE P.Id IN (SELECT MAX(Id)
																			FROM operaciones_gestionlotes_position
																		GROUP BY cod_lote)";

		if ($res_datos = mysqli_query($enlace, $q_datos)) {
			if (mysqli_num_rows($res_datos) > 0) {
				$estado = 1;

				while ($row_datos = mysqli_fetch_assoc($res_datos)) {
					$lotes[] = $row_datos;
				}
			}
		}

		echo json_encode($lotes);

