		$id_proceso = 0;
		$estado_proceso = '';

		$q_recursos = "SELECT id_procesooperaciones,
															estado
												 FROM operaciones_gestionlotes_lotesprocesos
												WHERE cod_lote = '" . $cod_lote . "'
