		break;

	case 'get_OperacionesGestionLotes_InfoRecursos':
		$estado = '';

		// Recuperando parámetros
		$cod_lote = mysqli_real_escape_string($enlace, $_POST["cod_lote"]);
		$id_proceso = mysqli_real_escape_string($enlace, $_POST["id_proceso"]);
		$id_tipovehiculo = mysqli_real_escape_string($enlace, $_POST["id_tipovehiculo"]);
		$id_tipocarga = mysqli_real_escape_string($enlace, $_POST["id_tipocarga"]);

		// Seteando Tipo de Vechiculo y Tipo de Carga
		if ($id_proceso != 1) {
			$id_tipovehiculo = 'NULL';
			$id_tipocarga = 'NULL';
		}

		// Obteniendo los recursos
		$arr_recursos = array();

		$q_datos = "SELECT OPR.Id AS ID_RECURSO,
													 OPR.descripcion AS RECURSO,

													 CASE WHEN DF.Id IS NOT NULL
														 THEN 1
													 ELSE 0 END AS IS_SELECTED

											FROM tbconfig_operaciones_recursos OPR
													 LEFT JOIN tbconfig_operaciones_recursos_bydefault DF ON OPR.Id = DF.id_recurso 
														 AND DF.id_procesooperaciones = " . $id_proceso . "
														 AND DF.id_tipovehiculo " . (($id_proceso != 1) ? 'IS' : '=') . " " . $id_tipovehiculo . "
														 AND DF.id_tipocarga " . (($id_proceso != 1) ? 'IS' : '=') . " " . $id_tipocarga;

		if ($res_datos = mysqli_query($enlace, $q_datos)) {
			if (mysqli_num_rows($res_datos) > 0) {
				while ($row_datos = mysqli_fetch_assoc($res_datos)) {
					$arr_recursos[] = $row_datos;
				}
			}
		}

		// Obtiene el estado del último proceso ejecutado
		$estado = '';

		$q_datos = "SELECT estado
											FROM operaciones_gestionlotes_lotesprocesos
										 WHERE cod_lote = '" . $cod_lote . "'
										 	 AND id_procesooperaciones = " . $id_proceso . "
										ORDER BY fechahora_registro DESC
										LIMIT 1";

		if ($res_datos = mysqli_query($enlace, $q_datos)) {
			if (mysqli_num_rows($res_datos) > 0) {
				while ($row_datos = mysqli_fetch_assoc($res_datos)) {
					$estado = $row_datos["estado"];
				}
			}
		}

		// Verificando si se tiene al menos un check seleccionado por el usuario
		$tiene_checks = 0;

		$q_datos = "SELECT Id
											FROM operaciones_gestionlotes_lotesprocesos_recursos
										 WHERE cod_lote = '" . $cod_lote . "'
											 AND id_procesooperaciones = " . $id_proceso;

		if ($res_datos = mysqli_query($enlace, $q_datos)) {
			if (mysqli_num_rows($res_datos) > 0) {
				$tiene_checks = 1;
			}
		}

		// Cargando la lista de Recursos
		$d = 1;

		if ($tiene_checks == 0) {
			foreach ($arr_recursos as $recurso) {
				$html .= '<tr style="cursor: pointer; font-size: 12px;">';

				$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; width: 60px;">';
				$html .= '		<input id="chk_Recursos_' . $d . '" class="form-check-input" type="checkbox" style="transform: scale(1.5)" ' . (($recurso["IS_SELECTED"] == 1) ? 'checked' : '') . '>';
				$html .= '  </td>';

				$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; width: 60px;">';
				$html .= '   ' . $d;
				$html .= '  </td>';

				$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; font-weight: bold;">';
				$html .= '   ' . $recurso["RECURSO"];
				$html .= '  </td>';

				$html .= '</tr>';

				$d++;
			}
		} else {
			$q_recursos = "SELECT OPR.Id,
																UPPER(OPR.descripcion) AS DESCRIPCION,
												        OPR.icono,
												        
												        CASE WHEN LPR.Id IS NOT NULL
												          THEN 1
												        ELSE 0 END AS SELECTED

												 	 FROM tbconfig_operaciones_recursos OPR
																LEFT JOIN operaciones_gestionlotes_lotesprocesos_recursos LPR ON OPR.Id = LPR.id_recurso
												          AND LPR.cod_lote = '" . $cod_lote . "'
												          AND LPR.id_procesooperaciones = " . $id_proceso . "
													WHERE OPR.estado = 'A'
												 ORDER BY OPR.orden";

			if ($res_recursos = mysqli_query($enlace, $q_recursos)) {
				if (mysqli_num_rows($res_recursos) > 0) {
					while ($row_recursos = mysqli_fetch_assoc($res_recursos)) {
						$html .= '<tr style="cursor: pointer; font-size: 12px;">';

						$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; width: 60px;">';
						$html .= '		<input id="chk_Recursos_' . $d . '" class="form-check-input" type="checkbox" style="transform: scale(1.5)" ' . (($row_recursos["SELECTED"] == 1) ? 'checked' : '') . '>';
						$html .= '  </td>';

						$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; width: 60px;">';
						$html .= '   ' . $d;
						$html .= '  </td>';

						$html .= '  <td style="border: solid; border-width: 1px; border-color: #D9D9D9; vertical-align: middle; text-align: center; font-weight: bold;">';
						$html .= '   ' . $row_recursos["DESCRIPCION"];
						$html .= '  </td>';

						$html .= '</tr>';

						$d++;
					}
				}
			}
		}

		echo json_encode(array('estado' => $estado, 'html' => $html));

		break;

	case 'grabar_OperacionesGestionLotes_ProcesosEstados':
		$estado = 0;

		// Recuperando parámetros
		$cod_lote = mysqli_real_escape_string($enlace, $_POST["cod_lote"]);
		$id_proceso = mysqli_real_escape_string($enlace, $_POST["id_proceso"]);
		$estado = mysqli_real_escape_string($enlace, $_POST["estado"]);
		$recursos_selected = $_POST["recursos_selected"];
		$usuario_registro = $_SESSION["usu_usuario"];

		// Grabando datos
		$q_save = "INSERT INTO operaciones_gestionlotes_lotesprocesos (cod_lote, id_procesooperaciones, estado, fechahora_registro, usuario_registro) VALUES (";
		$q_save .= "'" . $cod_lote . "', ";
		$q_save .= $id_proceso . ", ";
		$q_save .= "'" . $estado . "', ";
		$q_save .= "'" . $g_fecha . "', ";
		$q_save .= "'" . $usuario_registro . "')";

		if ($res_save = mysqli_query($enlace, $q_save)) {
			$estado = 1;

			// Eliminando Checks previos
			$q_delete = "DELETE FROM operaciones_gestionlotes_lotesprocesos_recursos ";
			$q_delete .= " WHERE cod_lote = '" . $cod_lote . "'";
			$q_delete .= "   AND id_procesooperaciones = " . $id_proceso;

			if ($res_delete = mysqli_query($enlace, $q_delete)) {
			}

			// Grabando Checks (Recursos)
			if (isset($recursos_selected) && is_array($recursos_selected)) {
				$q_insert = "INSERT INTO operaciones_gestionlotes_lotesprocesos_recursos (cod_lote, id_procesooperaciones, id_recurso, fechahora_registro, usuario_registro) VALUES ";

				foreach ($recursos_selected as $recurso) {
					$q_insert .= "(";
					$q_insert .= "'" . $cod_lote . "', ";
					$q_insert .= $id_proceso . ", ";
					$q_insert .= $recurso . ", ";
					$q_insert .= "'" . $g_fecha . "', ";
					$q_insert .= "'" . $usuario_registro . "'";
					$q_insert .= "), ";
				}

				$q_insert = substr($q_insert, 0, -2);

				if ($res_insert = mysqli_query($enlace, $q_insert)) {
				}
			}
		}

		echo json_encode(array('estado' => $estado));

		break;

	case 'get_OperacionesGestionLotes_HistorialLote':
		$estado = 0;

		// Recuperando parámetros
		$cod_lote = mysqli_real_escape_string($enlace, $_POST["cod_lote"]);

		// Cargando historial de Lotes
		$d = 1;
		$html = '<table style="width: 100%;">';

		$q_datos = "SELECT LP.id_procesooperaciones,
													 PO.descripcion AS PROCESO,
													 PO.color,
													 LP.motivo,
													 LP.estado,
													 LP.fechahora_registro,
													 LP.usuario_registro
											FROM operaciones_gestionlotes_lotesprocesos LP
													 INNER JOIN tbconfig_procesosoperaciones PO ON LP.id_procesooperaciones = PO.Id
										 WHERE LP.cod_lote = '" . $cod_lote . "'
										ORDER BY LP.id_procesooperaciones, LP.fechahora_registro";

		if ($res_datos = mysqli_query($enlace, $q_datos)) {
			if (mysqli_num_rows($res_datos) > 0) {
				$estado = 1;
				$current_proceso = null;

				while ($row_datos = mysqli_fetch_array($res_datos)) {
					// Si el proceso cambia, creamos una nueva fila de encabezado
					if ($current_proceso !== $row_datos['id_procesooperaciones']) {
						$current_proceso = $row_datos['id_procesooperaciones'];

						$html .= '<tr style="background-color: ' . $row_datos["color"] . '; font-weight: bold; font-size: 14px; cursor: pointer;" onclick="f_ShowHistorial(' . $row_datos["id_procesooperaciones"] . ')">';
						$html .= '	<td colspan="2" style="border: solid; border-width: 1px; border-color: #ffffff; color: #ffffff; vertical-align: middle; padding: 8px; width: 95%; border-right-color: ' . $row_datos["color"] . '; border-top-left-radius: 15px;">';
						$html .= '		' . htmlspecialchars($row_datos['PROCESO']);
						$html .= '	</td>';

						$html .= '	<td style="border: solid; border-width: 1px; border-color: #ffffff; vertical-align: middle; padding: 8px; text-align: center; border-top-right-radius: 15px;">';
						$html .= '		<img id="img_ProcesoHistorial_' . $row_datos["id_procesooperaciones"] . '" src="' . $img_button_up . '" style="width: 10px;">';
						$html .= '	</td>';
						$html .= '</tr>';
					}

					// Seteando estados
					$estado_proceso = '';
					$img_button_proceso = '';

					if ($row_datos['estado'] == 'I') {
						$estado_proceso = 'INICIADO';
						$img_button_proceso = $img_button_play;
					}

					if ($row_datos['estado'] == 'F') {
						$estado_proceso = 'FINALIZADO';
						$img_button_proceso = $img_button_finish;
					}

					if ($row_datos['estado'] == 'P') {
						$estado_proceso = 'PAUSADO';
						$img_button_proceso = $img_button_pause;
					}

					if ($row_datos['estado'] == 'C') {
						$estado_proceso = 'CANCELADO';
						$img_button_proceso = $img_button_cancel;
					}

					// Agregamos las filas de estado con una tabulación visual
					$html .= '<tr class="tr_ProcesoHistorial_' . $row_datos["id_procesooperaciones"] . '">';
					$html .= '	<td style="vertical-align: top; font-size: 12px; padding: 5px; padding-left: 20px;">';
					$html .= '		<img src="' . $img_button_proceso . '" style="width: 20px;">';
					$html .= '	</td>';

					$html .= '	<td style="vertical-align: middle; padding: 5px; width: 90%;">';
					$html .= '		<label style="font-weight: bold; font-size: 12px;"> ' . $estado_proceso . '</label>';
					$html .= '		<br><label style="font-size: 12px; padding-left: 10px;"> - ' . $row_datos['fechahora_registro'] . '</label>';
					$html .= '		<br><label style="font-size: 12px; padding-left: 10px;"> - ' . $row_datos['usuario_registro'] . '</label>';
					$html .= '	</td>';
					$html .= '</tr>';
				}
			}
		}

		$html .= '</table>';

		echo json_encode(array('estado' => $estado, 'html' => $html));

		break;

	case 'get_OperacionesGestionLotes_ColoresProcesos':
		$estado = 0;

		// Recuperando parámetros
		$cod_lote = mysqli_real_escape_string($enlace, $_POST["cod_lote"]);

		// Cargando historial de Lotes
		$colores_procesos = '';

		$q_datos = "SELECT PO.Id AS ID_PROCESO,
													 PO.descripcion AS PROCESO,
													 PO.color,
													 IFNULL(LP.cod_lote, 'x') AS LOTE
											FROM tbconfig_procesosoperaciones PO
													 LEFT JOIN operaciones_gestionlotes_lotesprocesos LP ON PO.Id = LP.id_procesooperaciones
													   AND LP.cod_lote = '" . $cod_lote . "'
										GROUP BY PO.id_procesosarea, PO.descripcion, PO.color, LP.cod_lote
										ORDER BY PO.orden";

		if ($res_datos = mysqli_query($enlace, $q_datos)) {
			if (mysqli_num_rows($res_datos) > 0) {
				$estado = 1;

				while ($row_datos = mysqli_fetch_array($res_datos)) {
					$colores_procesos .= $row_datos["ID_PROCESO"] . ';' . $row_datos["color"] . ';' . $row_datos["LOTE"] . '|';
				}
			}
		}

		$colores_procesos = substr($colores_procesos, 0, -1);

		echo json_encode(array('estado' => $estado, 'colores_procesos' => $colores_procesos));

		break;

	case 'grabar_OperacionesGestionLotes_ProcesosEstados_Motivo':
		$estado = 0;

		// Recuperando parámetros
		$cod_lote = mysqli_real_escape_string($enlace, $_POST["cod_lote"]);
		$id_proceso = mysqli_real_escape_string($enlace, $_POST["id_proceso"]);
		$estado = mysqli_real_escape_string($enlace, $_POST["estado"]);
		$motivo = mysqli_real_escape_string($enlace, $_POST["motivo"]);
		$usuario_registro = $_SESSION["usu_usuario"];

		// Grabando datos
		$q_save = "INSERT INTO operaciones_gestionlotes_lotesprocesos (cod_lote, id_procesooperaciones, motivo, estado, fechahora_registro, usuario_registro) VALUES (";
		$q_save .= "'" . $cod_lote . "', ";
		$q_save .= $id_proceso . ", ";
		$q_save .= "'" . $motivo . "', ";
		$q_save .= "'" . $estado . "', ";
		$q_save .= "'" . $g_fecha . "', ";
		$q_save .= "'" . $usuario_registro . "')";

		if ($res_save = mysqli_query($enlace, $q_save)) {
			$estado = 1;
		}

		echo json_encode(array('estado' => $estado));

		break;

	case 'update_RegistroManual_Humedad':
		$estado = 0;

		// Recupera parámetros
		$cod_lote = trim($_POST["cod_lote"]);
		$valor = trim($_POST["valor"]);
		$usuario_registro = $_SESSION["usu_usuario"];

		// Seteando query
		$q_save = "UPDATE despachos_primertramo_validaciondatos SET";
		$q_save .= "  humedad_registromanual = " . ((strlen($valor) > 0) ? "'" . $valor . "'" : 'NULL');
		$q_save .= ", humedad_registromanual_fechahoraregistro = " . ((strlen($valor) > 0) ? "'" . $g_fecha . "'" : 'NULL');
		$q_save .= ", humedad_registromanual_usuarioregistro = " . ((strlen($valor) > 0) ? "'" . $usuario_registro . "'" : 'NULL');
		$q_save .= " WHERE lote_cod_lote = '" . $cod_lote . "'";

		if ($res_update = mysqli_query($enlace, $q_save)) {
			$estado = 1;
		}

		echo json_encode(array('estado' => $estado, 'md5_lote' => MD5($cod_lote)));

		break;

	case 'empresitas_por_distribuion_despacho':
        $estado = 0;
        $res = array();

        // Recupera y limpia parámetro, se envia uno u otro
		$id_programacion = intval(trim($_POST["id_programacion"]));
        $id_distribucion = intval(trim($_POST["id_distribucion"]));

        $sql = "
        SELECT DISTINCT
            pl.Id AS id_empresita,
            RE.ruc,
            RE.razon_social
        FROM
            despachos_segundotramo_programacion_detalle PD
        LEFT JOIN despachos_segundotramo_programacion P ON
            PD.id_programacion = P.Id
        LEFT JOIN despachos_segundotramo_distribucion_unidades U ON
            P.Id = U.id_programacion
        LEFT JOIN despachos_segundotramo_distribucion_lotes DL ON
            U.Id = DL.id_distribucionunidad AND PD.cod_lote = DL.cod_lote
        LEFT JOIN tbconfig_remitentessegundotramo RE ON
            DL.guias_iddestino = RE.id_destino AND DL.guias_idmodalidadenvio = RE.id_modalidadenvio
        LEFT JOIN tbconfig_plantas pl ON pl.nombre_comercial = RE.razon_social OR RE.ruc = pl.ruc    
        WHERE 1=1";

		if($id_programacion != null){
			$sql .= " AND P.Id = $id_programacion";
		}

		if($id_distribucion != null){
			$sql .= " AND U.Id = $id_distribucion";
		}

        if ($query = mysqli_query($enlace, $sql)) {
            $estado = 1;
            while ($row = mysqli_fetch_assoc($query)) {
                $res[] = array(
                    'id_empresita' => $row['id_empresita'],
                    'ruc'          => $row['ruc'],
                    'razon_social' => $row['razon_social']
                );
            }
        }

        echo json_encode(array(
            'estado' => $estado,
            'res'    => $res
        ));

        break;

	default:

		# code...

		break;

}

?>